window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-1/physio-patho-2","titre":"Physiopathologie II","sources":[{"t":"Évaluation cardiovasculaire et athérosclérose","q":"m1-cardiovasculaire-atherosclerose/quiz.html","f":"m1-cardiovasculaire-atherosclerose/fiche.html"},{"t":"Hémato-oncologie","q":"m1-hemato-oncologie/quiz.html","f":"m1-hemato-oncologie/fiche.html"},{"t":"Pathologie hématologique","q":"m1-pathologie-hematologique/quiz.html","f":"m1-pathologie-hematologique/fiche.html"},{"t":"Valvulopathies, myocardiopathies, HTA et AOMI","q":"m1-valvulopathies-hta/quiz.html","f":"m1-valvulopathies-hta/fiche.html"},{"t":"Pathologie gastrique et œsophagienne","q":"m2-pathologie-gastrique/quiz.html","f":"m2-pathologie-gastrique/fiche.html"},{"t":"Pathologie hépatique","q":"m2-pathologie-hepatique/quiz.html","f":"m2-pathologie-hepatique/fiche.html"},{"t":"Pathologie inflammatoire intestinale et pathologie colique","q":"m2-pathologie-intestinale/quiz.html","f":"m2-pathologie-intestinale/fiche.html"},{"t":"Pathologie rénale","q":"m2-pathologie-renale/quiz.html","f":"m2-pathologie-renale/fiche.html"},{"t":"Voies biliaires et pancréas","q":"m2-voies-biliaires-pancreas/quiz.html","f":"m2-voies-biliaires-pancreas/fiche.html"},{"t":"Diabète sucré et complications","q":"m3-diabete-sucre/quiz.html","f":"m3-diabete-sucre/fiche.html"},{"t":"Pathologie psychiatrique","q":"m3-pathologie-psychiatrique/quiz.html","f":"m3-pathologie-psychiatrique/fiche.html"},{"t":"Stress, sommeil et veille","q":"m3-stress-et-sommeil/quiz.html","f":"m3-stress-et-sommeil/fiche.html"},{"t":"Pathologie du système endocrinien","q":"m3-systeme-endocrinien/quiz.html","f":"m3-systeme-endocrinien/fiche.html"},{"t":"Pathologie du système reproducteur","q":"m3-systeme-reproducteur/quiz.html","f":"m3-systeme-reproducteur/fiche.html"},{"t":"Système tégumentaire et brûlures","q":"m3-systeme-tegumentaire/quiz.html","f":"m3-systeme-tegumentaire/fiche.html"}],"questions":[{"q":"Pourquoi les fibres du muscle cardiaque se contractent-elles simultanément ?","o":["Le tissu cardiaque fonctionne comme un syncytium","Le nerf vague les active toutes en même temps","Les fuseaux neuromusculaires synchronisent toutes les fibres","Une hormone circulante déclenche leur contraction"],"r":0,"e":"Le stimulus électrique se transmet rapidement à toutes les fibres.","s":0},{"q":"Comment se caractérise la circulation pulmonaire ?","o":["Un circuit court, à basse pression","Un circuit long, à haute pression","Un circuit à haute résistance, rigide","Un circuit qui nourrit les tissus, en oxygène"],"r":0,"e":"Elle fait le lien entre la circulation et les échanges gazeux dans le poumon. La résistance y est aussi basse.","s":0},{"q":"Comment se caractérise la circulation systémique ?","o":["Haute pression, elle nourrit les tissus","Basse pression, basse résistance","Circuit court, vers les poumons","Échanges gazeux, au niveau pulmonaire"],"r":0,"e":"La circulation pulmonaire est à basse pression et basse résistance. Elle fournit oxygène et nutriments aux tissus.","s":0},{"q":"Quels sont les facteurs de risque cardiovasculaire NON modifiables ?","o":["L'âge, le sexe, les antécédents familiaux","Le tabagisme, l'obésité, la sédentarité marquée","L'hypertension, le diabète, le cholestérol","L'inactivité physique, le stress"],"r":0,"e":"Ils sont recherchés lors de l'évaluation subjective.","s":0},{"q":"Quelle est la cause de l'angor ?","o":["L'ischémie du myocarde","Une inflammation pleurale","Une contracture musculaire","Une hernie hiatale"],"r":0,"e":"Il est décrit comme une douleur cardiaque, un serrement thoracique ou une brûlure rétro-sternale.","s":0},{"q":"Qu'est-ce qui aggrave l'angor ?","o":["L'exercice ou l'activité","L'inspiration profonde","La palpation locale","Le mouvement articulaire"],"r":0,"e":"S'il se modifie avec l'inspiration, la palpation ou le mouvement, ce n'est probablement pas un angor.","s":0},{"q":"Quel élément permet d'écarter le diagnostic d'angor ?","o":["Une douleur modifiée par l'inspiration ou la palpation","Une douleur aggravée par l'effort, puis calmée au repos","Une brûlure rétro-sternale, irradiant vers la mâchoire","Un serrement thoracique, avec une irradiation au bras gauche"],"r":0,"e":"L'angor est lié à l'ischémie du myocarde, non à une cause mécanique. Une douleur modifiée par le mouvement articulaire oriente aussi vers une cause mécanique.","s":0},{"q":"Comment l'angor peut-il être perçu par certains patients ?","o":["Comme une dyspnée","Comme une douleur abdominale","Comme une céphalée","Comme des crampes de jambes"],"r":0,"e":"Il peut ne pas être ressenti comme une douleur thoracique.","s":0},{"q":"Quels autres symptômes évoquent une maladie cardiaque ?","o":["Dyspnée, fatigue, étourdissements, palpitations","Toux, expectoration, sifflements","Douleur lombaire, raideur matinale, sciatalgie droite","Paresthésies des mains, crampes"],"r":0,"e":"Ils sont recherchés à l'évaluation subjective, avec l'angor.","s":0},{"q":"Que mesure l'échelle de Borg dans ce contexte ?","o":["La perception de l'effort et de la dyspnée","La pression artérielle mesurée pendant l'effort","La fréquence cardiaque au repos","Le tour de taille, en centimètres"],"r":0,"e":"Elle sert à identifier et mesurer les symptômes à l'examen objectif.","s":0},{"q":"Quel questionnaire évalue l'activité physique ?","o":["L'IPAQ","Le McNew","Le SF-36","Le Borg"],"r":0,"e":"Le McNew évalue la qualité de vie.","s":0},{"q":"Quel questionnaire évalue la qualité de vie en pathologie cardiovasculaire ?","o":["Le McNew","L'IPAQ","Le NDI","Le KOOS"],"r":0,"e":"L'IPAQ évalue l'activité physique.","s":0},{"q":"Comment définit-on le pouls artériel ?","o":["La transmission de la pression du ventricule gauche aux artères","Le battement du ventricule droit, transmis aux artères pulmonaires","La contraction des oreillettes, perçue au cou","Le retour du sang veineux vers le cœur droit"],"r":0,"e":"Il permet d'évaluer les événements du cœur gauche et l'état de l'artère palpée. Elle survient après l'ouverture de la valve aortique.","s":0},{"q":"Quelle est la fréquence normale du pouls ?","o":["60 à 100 par minute","40 à 60 par minute, au repos","100 à 120 par minute","80 à 140 par minute"],"r":0,"e":"En dessous de 60 on parle de bradycardie, au-dessus de 100 de tachycardie. La valeur moyenne est d'environ 75 par minute.","s":0},{"q":"De quoi dépend l'amplitude du pouls ?","o":["De la pression pulsée, systolique moins diastolique","De la fréquence cardiaque, au repos","De la régularité du rythme, mesurée sur une minute entière","De la température corporelle, en degrés"],"r":0,"e":"Le pouls est classé en ample ou peu ample.","s":0},{"q":"Quand dit-on que le pouls est régulier ?","o":["Lorsque son amplitude ne varie pas","Lorsque sa fréquence reste constante dans le temps","Lorsqu'il est ample et bien frappé","Lorsqu'il dépasse 60 battements"],"r":0,"e":"On le dit rythmique lorsque la fréquence est constante.","s":0},{"q":"Quels facteurs affectent la morphologie de l'onde de pouls ?","o":["L'éjection, la résistance et la distensibilité artérielles","La température et l'humidité ambiantes","L'âge seul, quel que soit l'état des artères","Le poids corporel, la taille et la surface cutanée du patient"],"r":0,"e":"Ce sont les quatre facteurs cités dans le cours. L'éjection s'entend en vitesse et en volume.","s":0},{"q":"Quel marqueur d'inflammation augmente le risque d'athérosclérose ?","o":["La protéine C réactive","Le cholestérol HDL","Les triglycérides","La ferritine"],"r":0,"e":"Un taux bas de cholestérol HDL est aussi un facteur de risque.","s":0},{"q":"Quel profil lipidique augmente le risque d'athérosclérose ?","o":["Un cholestérol total élevé, un HDL bas","Un cholestérol total bas, un HDL normal","Un HDL élevé, un LDL normal","Un LDL bas, des triglycérides bas"],"r":0,"e":"Le HDL est le « bon cholestérol ».","s":0},{"q":"Quand l'athérosclérose devient-elle symptomatique ?","o":["Quand l'apport sanguin d'un organe diminue","Dès l'apparition de la première plaque","Uniquement après 70 ans, chez l'homme","Uniquement en cas de diabète, mal équilibré"],"r":0,"e":"Les manifestations varient selon l'organe spécifique atteint.","s":0},{"q":"Comment distingue-t-on un AIT d'un AVC ?","o":["L'AIT régresse en moins de 24 heures","L'AIT dure plus de 24 heures","L'AIT ne donne aucun symptôme","L'AVC ne donne jamais de douleur ni de céphalée"],"r":0,"e":"Les manifestations cérébrales incluent confusion, troubles visuels et difficultés d'élocution.","s":0},{"q":"Quelle manifestation abdominale évoque une athérosclérose ?","o":["Une douleur peu après le repas","Une douleur au réveil, à jeun","Une douleur nocturne, sans lien avec le repas","Une douleur soulagée par le repas"],"r":0,"e":"Un blocage complet d'une artère intestinale donne une douleur intense avec vomissements et diarrhée. Elle survient 15 à 30 minutes après le repas.","s":0},{"q":"Comment se manifeste l'athérosclérose des artères des jambes ?","o":["Par une crampe qui augmente avec l'activité","Par une douleur soulagée par la marche, puis par l'effort","Par des paresthésies nocturnes isolées","Par un œdème bilatéral des chevilles"],"r":0,"e":"En cas de douleur de repos, les orteils et les pieds peuvent devenir pâles puis cyanosés.","s":0},{"q":"Existe-t-il un traitement curatif de l'athérosclérose ?","o":["Non, mais on peut ralentir sa progression","Oui, l'angioplastie la guérit définitivement","Oui, les statines la guérissent","Oui, le pontage la guérit"],"r":0,"e":"L'objectif principal est de prévenir un rétrécissement significatif des artères. On peut aussi interrompre son aggravation.","s":0},{"q":"Quels médicaments contrôlent les symptômes d'angor ?","o":["Dérivés nitrés, bêtabloquants, inhibiteurs calciques","Antibiotiques, corticoïdes, antalgiques","Anticoagulants et héparines, seuls","Diurétiques, laxatifs, antiémétiques, antihistaminiques"],"r":0,"e":"L'aspirine et les bêtabloquants servent à prévenir les infarctus.","s":0},{"q":"Que signifie CABG ?","o":["Un pontage coronarien chirurgical","Une angioplastie au ballonnet, avec un stent","Une valvuloplastie aortique","Une greffe cardiaque complète"],"r":0,"e":"L'angioplastie, souvent avec pose de stents, est l'autre technique de revascularisation citée. C'est une technique de revascularisation.","s":0},{"q":"Quel mécanisme explique l'œdème aigu du poumon ?","o":["Une hausse brutale de la pression de remplissage gauche","Une baisse brutale de la pression artérielle, avec un choc","Une hyperventilation, par anxiété ou par douleur","Une obstruction bronchique, par un bouchon de mucus"],"r":0,"e":"Le liquide passe rapidement des capillaires pulmonaires vers les alvéoles. Le liquide plasmatique passe alors vers l'interstitium et les alvéoles.","s":0},{"q":"Quelle cause d'œdème aigu du poumon est citée ?","o":["L'ischémie coronaire aiguë","Une pneumonie bactérienne","Une embolie graisseuse","Un pneumothorax"],"r":0,"e":"On retient aussi la décompensation d'insuffisance cardiaque, les arythmies et la valvulopathie aiguë.","s":0},{"q":"Quelles comorbidités explore-t-on dans l'évaluation cardiovasculaire ?","o":["Respiratoires, neurologiques, orthopédiques, tumorales","Respiratoires seulement, le reste étant exclu","Métaboliques seulement, comme le diabète et la thyroïde","Aucune, l'évaluation restant cardiaque"],"r":0,"e":"Elles font partie de l'évaluation subjective. L'inflammation et une néoplasie antérieure sont aussi explorées.","s":0},{"q":"Quels outils objectivent le niveau d'activité physique ?","o":["Les accéléromètres et les podomètres","L'échelle de Borg, à l'effort","Le tour de taille et l'indice de masse","Le questionnaire McNew"],"r":0,"e":"L'IPAQ est le questionnaire d'activité physique correspondant.","s":0},{"q":"La circulation pulmonaire se caractérise par :","o":["Une haute pression, une haute résistance","Un circuit court, à basse pression","Un circuit long, à haute pression","Aucun échange gazeux, une basse pression"],"r":1,"e":"Elle fait le lien entre la circulation et les échanges gazeux dans le poumon. La circulation systémique, à haute pression, fournit oxygène et nutriments aux tissus. Sa résistance est aussi basse.","s":0},{"q":"Les fibres du muscle cardiaque se contractent simultanément en raison :","o":["Leur innervation individuelle, fibre par fibre","Leur organisation syncytiale, fibre à fibre","Leur richesse en mitochondries, pour l'énergie","Leur grande longueur, d'une base à l'autre"],"r":1,"e":"C'est ce qui permet au cœur de fonctionner comme une pompe efficace : une contraction fragmentée n'éjecterait rien.","s":0},{"q":"Parmi les facteurs de risque cardiovasculaire NON modifiables figurent :","o":["Le tabagisme, l'obésité","L'âge, le sexe, l'hérédité","L'hypertension artérielle, le diabète","L'inactivité, la sédentarité"],"r":1,"e":"Les autres facteurs cités — cholestérol, HDL bas, CRP élevée, hypertension, diabète, tabac, obésité, sédentarité — sont modifiables. L'hérédité correspond aux antécédents familiaux.","s":0},{"q":"L'angor peut être perçu par certains patients :","o":["Comme une dyspnée","Comme une douleur abdominale","Comme des céphalées","Comme un vertige isolé"],"r":0,"e":"Cette présentation atypique est un piège diagnostique classique : le patient ne décrit alors aucune douleur thoracique.","s":0},{"q":"Parmi les autres symptômes évoquant une maladie cardiaque, le cours cite :","o":["Dyspnée, fatigue, étourdissements, palpitations","Toux sèche isolée, sans autre signe respiratoire","Douleurs lombaires, raideur du dos","Paresthésies, fourmillements des doigts"],"r":0,"e":"L'examen subjectif explore par ailleurs les antécédents, les facteurs de risque, l'angor et les comorbidités.","s":0},{"q":"L'échelle de Borg, dans l'évaluation cardiovasculaire, mesure :","o":["La pression artérielle, à l'effort","La perception de l'effort, la dyspnée","La fréquence cardiaque, maximale","Le tour de taille du patient"],"r":1,"e":"L'IPAQ évalue l'activité physique et le McNew la qualité de vie en pathologie cardiaque.","s":0},{"q":"Le niveau d'activité physique peut être objectivé par :","o":["Des accéléromètres et des podomètres","La seule échelle de Borg","Le tour de taille","La fréquence cardiaque de repos"],"r":0,"e":"Ces mesures objectives complètent les questionnaires déclaratifs, souvent biaisés par la surestimation de son propre niveau d'activité.","s":0},{"q":"Le pouls artériel se définit comme :","o":["La contraction du ventricule gauche, ressentie au thorax","La pression du ventricule gauche transmise aux artères","Le remplissage des oreillettes, en fin de diastole","La pression veineuse, mesurée au niveau jugulaire"],"r":1,"e":"Il permet d'évaluer les événements produits par le cœur gauche ainsi que l'état fonctionnel et organique de l'artère palpée. Elle se transmet après l'ouverture de la valve aortique.","s":0},{"q":"La valeur moyenne de la fréquence du pouls est de :","o":["60/min","75/min","90/min","100/min"],"r":1,"e":"La variation normale s'étend de 60 à 100. En dessous de 60, on parle de bradycardie ; au-delà de 100, de tachycardie.","s":0},{"q":"L'amplitude du pouls dépend :","o":["De la fréquence cardiaque, au repos","De la pression pulsée, systolique moins diastolique","De la régularité du rythme cardiaque","De la température du corps, en particulier la fièvre"],"r":1,"e":"Le pouls est alors classé en ample ou peu ample. La régularité concerne, elle, l'absence de variation d'amplitude.","s":0},{"q":"Le pouls est dit rythmique lorsque :","o":["L'amplitude est constante","La fréquence est constante","Il est ample","Il est palpable aux quatre membres"],"r":1,"e":"Il est dit régulier lorsqu'il n'y a pas de variation de l'amplitude : rythme et régularité désignent donc deux propriétés distinctes.","s":0},{"q":"Parmi les facteurs affectant la morphologie de l'onde de pouls, le cours cite :","o":["L'éjection, la résistance, la distensibilité artérielle","La température corporelle, la fièvre éventuelle","Le taux d'hémoglobine, la viscosité du sang","La fréquence respiratoire, l'amplitude thoracique"],"r":0,"e":"La rigidité artérielle liée à l'âge modifie ainsi nettement l'aspect de l'onde, indépendamment de la fonction cardiaque. L'éjection s'entend en vitesse et en volume.","s":0},{"q":"Une douleur abdominale survenant 15 à 30 minutes après le repas évoque une athérosclérose :","o":["Coronarienne","Des artères intestinales","Cérébrale","Des membres inférieurs"],"r":1,"e":"En cas de blocage complet d'une artère intestinale, s'ajoutent une douleur abdominale intense, des vomissements, une diarrhée ou une augmentation du volume abdominal.","s":0},{"q":"L'athérosclérose des artères des jambes se manifeste par :","o":["Une crampe qui augmente avec l'activité","Une douleur permanente de repos, d'emblée","Un œdème isolé de la cheville","Des varices visibles tout le long de la jambe"],"r":0,"e":"En cas de douleur au repos, les orteils et les pieds peuvent présenter une pâleur pouvant évoluer vers une cyanose — signe de gravité.","s":0},{"q":"Concernant le traitement de l'athérosclérose, le cours précise qu'il :","o":["Est curatif, si on le commence tôt","Ralentit la progression, sans guérir","Est exclusivement chirurgical","Se limite au régime, sans aucun médicament"],"r":1,"e":"L'objectif principal est de prévenir un rétrécissement significatif des artères pour que les symptômes ne se développent jamais.","s":0},{"q":"Les médicaments contrôlant les symptômes d'angor cités par le cours sont :","o":["Nitrés, bêtabloquants, inhibiteurs calciques","Statines seules, à forte dose","Diurétiques, à doses croissantes","Anticoagulants, antibiotiques, corticoïdes oraux"],"r":0,"e":"L'aspirine et les bêtabloquants sont cités, eux, pour la prévention des infarctus.","s":0},{"q":"Le sigle CABG désigne :","o":["Une angioplastie au ballonnet","La chirurgie de pontage coronarien","Un test d'effort","Une échographie cardiaque"],"r":1,"e":"L'angioplastie au ballonnet, souvent avec pose de stents, constitue l'autre option de revascularisation citée.","s":0},{"q":"Le mécanisme de l'œdème aigu du poumon est :","o":["Une hausse brutale des pressions du cœur gauche","Une infection des alvéoles, par une bactérie","Une obstruction bronchique, par un bouchon","Une rupture de la plèvre, avec un pneumothorax"],"r":0,"e":"Ses causes citées sont l'ischémie coronaire aiguë, la décompensation d'insuffisance cardiaque, l'arythmie, une valvulopathie aiguë ou une surcharge de volume. Le plasma passe des capillaires vers l'interstitium et les alvéoles.","s":0},{"q":"Les comorbidités explorées dans l'évaluation cardiovasculaire comprennent :","o":["Respiratoires, neurologiques, orthopédiques, tumorales","Respiratoires seulement, sans autre système","Le diabète seulement, avec ses complications","Les antécédents familiaux, uniquement cardiaques"],"r":0,"e":"Cette exploration large conditionne la faisabilité et la sécurité du réentraînement à l'effort qui sera proposé. L'inflammation est aussi explorée.","s":0},{"q":"Un accident ischémique transitoire (AIT) se distingue de l'AVC par :","o":["La localisation de la lésion, dans le cerveau","Des symptômes qui régressent en moins d'un jour","L'absence de céphalées, au début des symptômes","Son caractère hémorragique, à l'imagerie"],"r":1,"e":"Au-delà de 24 heures, on parle d'AVC constitué. L'AIT est un signal d'alarme majeur qui impose un bilan étiologique urgent. Le seuil est de 24 heures.","s":0},{"q":"Quelle est la fonction des leucocytes et des tissus lymphoïdes ?","o":["La protection de l'organisme, l'immunité","Le transport de l'oxygène, vers les tissus","L'hémostase, en cas de saignement","La production d'hormones, pour la croissance"],"r":0,"e":"Leur durée de vie courte impose un renouvellement constant.","s":1},{"q":"De quelles cellules souches dérivent les granulocytes et les monocytes ?","o":["Des cellules souches myéloïdes","Des cellules souches lymphoïdes","Des cellules du stroma","Des blastes lymphoïdes"],"r":0,"e":"Les lymphocytes dérivent des cellules souches lymphoïdes.","s":1},{"q":"Comment appelle-t-on les cellules immatures précurseurs des lignées leucocytaires ?","o":["Les blastes","Les réticulocytes","Les mégacaryocytes","Les plasmocytes"],"r":0,"e":"Elles suivent un processus de maturation avant de devenir monocytes, granulocytes et lymphocytes.","s":1},{"q":"Quelles causes peuvent expliquer une leucopénie ?","o":["Un déficit en cellules souches ou en facteurs de croissance","Une infection aiguë, avec une hausse des neutrophiles","Une leucémie, avec un excès de globules blancs","Un lymphome, avec une prolifération des lymphocytes"],"r":0,"e":"Les dysfonctions prolifératives peuvent être réactives ou néoplasiques.","s":1},{"q":"Quelles sont les deux formes de dysfonctions prolifératives ?","o":["Réactives et néoplasiques","Congénitales et acquises","Aiguës et chroniques, selon la durée","Myéloïdes et lymphoïdes"],"r":0,"e":"Elles correspondent à une augmentation des leucocytes. Exemple de forme réactive : l'infection ; formes néoplasiques : leucémies et lymphomes.","s":1},{"q":"En quoi les lymphocytes T se différencient-ils lors de leur maturation ?","o":["En auxiliaires et cytotoxiques","En lymphocytes B et en cellules NK","En monocytes et macrophages","En granulocytes neutrophiles et éosinophiles"],"r":0,"e":"Dans le ganglion, les lymphocytes B et T poursuivent leur prolifération et leur production d'anticorps. Auxiliaires = CD4+, cytotoxiques = CD8+.","s":1},{"q":"Quelle est la différence entre leucopénie et neutropénie ?","o":["La leucopénie touche tous les leucocytes, la neutropénie les neutrophiles","Ce sont deux synonymes, employés indifféremment en clinique","La neutropénie touche les lymphocytes, la leucopénie les plaquettes","La leucopénie ne concerne que les monocytes, la neutropénie les éosinophiles"],"r":0,"e":"Les neutrophiles constituent la majorité des leucocytes.","s":1},{"q":"Pourquoi la neutropénie augmente-t-elle le risque d'infection ?","o":["Ils sont la première défense de la peau et du tube digestif","Ils fabriquent les anticorps, avec l'aide des lymphocytes T","Ils transportent l'oxygène jusqu'aux tissus","Ils assurent l'hémostase, avec les plaquettes"],"r":0,"e":"D'où les lésions cutanées, stomatites, pharyngites et diarrhées. Les neutrophiles constituent la majorité des leucocytes.","s":1},{"q":"Quelles peuvent être les causes acquises de neutropénie ?","o":["Auto-immune, infectieuse ou médicamenteuse","Génétique seulement, dès la naissance","Traumatique seulement, après une chute","Nutritionnelle seulement, par carence"],"r":0,"e":"La forme congénitale est rare.","s":1},{"q":"Quels symptômes accompagnent une neutropénie sévère ?","o":["Malaise, frissons, fièvre, fatigue","Douleurs articulaires, sans fièvre","Céphalées isolées, sans autre signe","Prurit isolé, diffus, sans aucune fièvre"],"r":0,"e":"Les manifestations dépendent de la sévérité et de la cause. Une faiblesse s'y associe.","s":1},{"q":"De quelles cellules le lymphome non hodgkinien tire-t-il son origine ?","o":["Des lymphocytes B, T et tueurs naturels","Des cellules souches, myéloïdes","Des granulocytes, neutrophiles et éosinophiles","Des monocytes, puis des macrophages"],"r":0,"e":"Il naît dans des régions extra-ganglionnaires et se propage vers les ganglions contigus.","s":1},{"q":"Quelle proportion des nouvelles néoplasies aux États-Unis les lymphomes non hodgkiniens représentent-ils ?","o":["Environ 4 %","Environ 15 %","Environ 25 %","Moins de 1 %"],"r":0,"e":"Leur cause est inconnue : déficit immunitaire ou infection ?","s":1},{"q":"Comment se manifeste un lymphome non hodgkinien indolent ?","o":["Une adénopathie indolore, isolée ou disséminée","Une fièvre, des sueurs nocturnes","Un prurit intense, généralisé","Une masse médiastinale, douloureuse à la toux et à l'effort"],"r":0,"e":"Les ganglions mésentériques, rétropéritonéaux et pelviens peuvent être atteints.","s":1},{"q":"Quelle est l'évolution des formes indolentes de lymphome non hodgkinien ?","o":["5 à 10 ans","Quelques mois","20 à 30 ans","Moins d'un an"],"r":0,"e":"Ils sont habituellement déjà bien disséminés au moment du diagnostic.","s":1},{"q":"Comment se manifestent les formes agressives de lymphome non hodgkinien ?","o":["Une fièvre, des sueurs, une perte de poids","Une adénopathie indolore, isolée","Une anémie isolée, sans fièvre","Un prurit isolé, sans aucun autre signe général"],"r":0,"e":"Elles sont sensibles à la radiothérapie et à la chimiothérapie. Les sueurs sont nocturnes.","s":1},{"q":"Quelle cellule permet le diagnostic du lymphome de Hodgkin ?","o":["La cellule de Reed-Sternberg","La cellule de Kupffer","Le lymphoblaste immature","Le myéloblaste de la moelle osseuse"],"r":0,"e":"Ce sont des cellules atypiques de grandes dimensions, mononucléées.","s":1},{"q":"Dans quelles tranches d'âge survient le lymphome de Hodgkin ?","o":["15-40 ans ou à partir de 55 ans","Uniquement après 60 ans","Uniquement avant 15 ans","De façon uniforme à tout âge"],"r":0,"e":"Seuls 10 à 15 % des cas surviennent chez l'enfant ou l'adolescent.","s":1},{"q":"Quelle proportion des cas de lymphome de Hodgkin survient chez l'enfant ou l'adolescent ?","o":["10 à 15 %","4 %","50 %","Moins de 1 %"],"r":0,"e":"Les deux pics de fréquence sont 15-40 ans et à partir de 55 ans.","s":1},{"q":"Quelle manifestation ganglionnaire caractérise le lymphome de Hodgkin ?","o":["Des ganglions qui grossissent sans douleur","Une adénopathie douloureuse, inflammatoire","Une splénomégalie isolée, sans ganglion","Une hépatomégalie, avec un ictère associé"],"r":0,"e":"On observe aussi une masse médiastinale à la radiographie thoracique. Ils siègent au-dessus du diaphragme : cou, aisselles.","s":1},{"q":"Quels signes généraux accompagnent le lymphome de Hodgkin ?","o":["Prurit, fièvre, sueurs nocturnes, amaigrissement","Ictère et prurit, sans autre signe","Douleurs osseuses diffuses, fractures, hypercalcémie","Hématurie, douleurs lombaires"],"r":0,"e":"La fatigue et l'anémie sont des indicateurs de progression de la maladie. La fièvre est intermittente, avec des frissons.","s":1},{"q":"Quel examen détecte des altérations ganglionnaires imperceptibles au scanner ?","o":["La lymphangiographie","L'échographie","La radiographie standard","L'électrophorèse"],"r":0,"e":"La biopsie de moelle osseuse détermine l'extension de la maladie.","s":1},{"q":"Quel est le traitement du lymphome de Hodgkin ?","o":["La radiothérapie et la chimiothérapie","La chirurgie seule, par exérèse","La greffe hépatique, en urgence","Les immunosuppresseurs seuls"],"r":0,"e":"Le diagnostic repose sur la mise en évidence des cellules de Reed-Sternberg.","s":1},{"q":"Que caractérise les leucémies lymphocytaires ?","o":["Des leucocytes immatures, qui infiltrent les organes","Des cellules souches pluripotentes, dans la moelle","Un blocage de maturation de toutes les lignées sanguines","Une origine en dehors de la moelle osseuse, toujours"],"r":0,"e":"Les leucémies myéloïdes impliquent les cellules souches pluripotentes. Elles infiltrent la rate, les ganglions, le SNC et d'autres tissus.","s":1},{"q":"Que caractérise les leucémies myéloïdes ?","o":["Elles touchent les cellules souches, toutes lignées","Elles ne touchent que les lymphocytes","Elles infiltrent seulement le système nerveux central","Elles sont toujours chroniques, jamais aiguës"],"r":0,"e":"Cela inclut érythrocytes, granulocytes et thrombocytes. Les cellules souches sont pluripotentes ; la maturation de toutes les cellules sanguines est perturbée.","s":1},{"q":"Quels types de leucémie sont cités dans le cours ?","o":["Aiguës et chroniques, myéloïdes et lymphoïdes","Aiguës seulement, myéloïdes et lymphoïdes, chez l'enfant","Chroniques seulement, myéloïdes et lymphoïdes","Myéloïdes seulement, aiguës et chroniques"],"r":0,"e":"Les causes des leucémies sont inconnues. LAM, LAL, LMC et LLC.","s":1},{"q":"Quel est le premier temps de la chimiothérapie des leucémies ?","o":["L'induction, pour obtenir la rémission","L'entretien, pour garder la rémission","L'intensification, pour réduire les cellules","La greffe de moelle, d'emblée"],"r":0,"e":"Vient ensuite l'intensification puis l'entretien.","s":1},{"q":"À quoi sert le traitement d'intensification ?","o":["À réduire encore les cellules néoplasiques","À induire la rémission, au tout début","À maintenir la rémission, sur la durée","À prévenir les infections, pendant l'aplasie"],"r":0,"e":"Le traitement d'entretien maintient la rémission.","s":1},{"q":"De quoi dépend la probabilité de rémission d'une leucémie ?","o":["Du type, du stade et de l'âge","Du seul type de leucémie, quel que soit l'âge","De l'âge seul, quel que soit le type","Du sexe du patient, et de son poids"],"r":0,"e":"Le traitement dépend lui aussi du type et du stade.","s":1},{"q":"Qu'ont en commun les syndromes myéloprolifératifs ?","o":["Un défaut clonal des cellules progénitrices","Une origine infectieuse, virale","Une carence martiale, en fer","Une atteinte ganglionnaire, exclusive et diffuse"],"r":0,"e":"Ils forment un groupe hétérogène de maladies. Les progénitrices hématopoïétiques sont les cellules souches.","s":1},{"q":"Quelle conséquence peut avoir l'augmentation de la fibrose médullaire dans un syndrome myéloprolifératif ?","o":["Une hématopoïèse extramédullaire","Une aplasie médullaire complète","Une leucopénie isolée, sans anémie","Une hémolyse intravasculaire"],"r":0,"e":"Les formes citées sont la thrombocytémie essentielle, la myélofibrose primitive et la polyglobulie de Vaquez.","s":1},{"q":"Les cellules immatures précurseurs des lignées leucocytaires portent le nom de :","o":["Réticulocytes","Blastes","Myocytes","Plasmocytes"],"r":1,"e":"Elles suivent un processus de maturation avant de devenir monocytes, granulocytes et lymphocytes ; leur accumulation dans le sang signe une leucémie aiguë.","s":1},{"q":"Les lymphocytes dérivent des cellules souches :","o":["Myéloïdes","Lymphoïdes","Mésenchymateuses","Endothéliales"],"r":1,"e":"Ce sont les granulocytes et les monocytes qui dérivent, eux, des cellules souches myéloïdes.","s":1},{"q":"La leucopénie est définie comme :","o":["Une diminution absolue du nombre de leucocytes","Une diminution spécifique des neutrophiles","Une augmentation des leucocytes","Une anomalie de forme des leucocytes"],"r":0,"e":"La neutropénie, elle, désigne la diminution spécifique des neutrophiles — un sous-type de leucopénie.","s":1},{"q":"Les facteurs de croissance intervenant dans la leucopénie sont médiés par :","o":["Les cytokines et les interleukines","L'érythropoïétine et le fer","Les hormones thyroïdiennes et le cortisol","L'insuline et le glucagon"],"r":0,"e":"Une diminution des cellules souches ou de ces facteurs de croissance constitue les deux mécanismes de leucopénie cités.","s":1},{"q":"Les dysfonctions prolifératives des leucocytes se répartissent en formes :","o":["Congénitales et acquises","Réactives et néoplasiques","Aiguës et subaiguës, selon la durée","Centrales et périphériques"],"r":1,"e":"Les formes néoplasiques correspondent aux leucémies et aux lymphomes. Les formes réactives sont par exemple infectieuses.","s":1},{"q":"Lors de leur maturation dans le ganglion, les lymphocytes T se différencient en :","o":["Plasmocytes et mastocytes","Auxiliaires et cytotoxiques","Cellules NK et basophiles","Macrophages et monocytes"],"r":1,"e":"Les lymphocytes B, eux, poursuivent leur prolifération et leur production d'anticorps dans les nodules lymphatiques. Auxiliaires = CD4+, cytotoxiques = CD8+.","s":1},{"q":"La neutropénie augmente le risque infectieux car les neutrophiles :","o":["Produisent les anticorps, avec les plasmocytes","Forment la première défense de la peau et de l'intestin","Transportent l'oxygène et le gaz carbonique dans le sang","Assurent la coagulation, avec les plaquettes"],"r":1,"e":"D'où les lésions cutanées, stomatites, pharyngites et diarrhées observées lors des neutropénies. Ils constituent aussi la majorité des leucocytes.","s":1},{"q":"Les causes acquises de neutropénie citées par le cours sont :","o":["Auto-immunes, infectieuses ou médicamenteuses","Génétiques, héréditaires ou liées à une mutation","Traumatiques, après fracture ou chirurgie","Nutritionnelles, par carence en vitamine C"],"r":0,"e":"Les causes congénitales existent aussi, mais le cours les présente comme rares.","s":1},{"q":"Les symptômes d'une neutropénie sévère comprennent :","o":["Malaise, frissons, fièvre, fatigue","Céphalées isolées, sans fièvre ni frissons","Douleurs articulaires, raideur","Hypertension, palpitations"],"r":0,"e":"Les manifestations dépendent de la sévérité de la neutropénie et de sa cause. Une faiblesse s'y associe.","s":1},{"q":"Le lymphome non hodgkinien prend son origine dans :","o":["Un seul ganglion, dans la région cervicale","Les lymphocytes, hors des ganglions","Les cellules souches, myéloïdes","La rate exclusivement, puis la moelle osseuse"],"r":1,"e":"Il se propage ensuite vers les ganglions anatomiquement contigus, à la différence du lymphome de Hodgkin qui naît dans un ganglion ou une chaîne ganglionnaire. Il s'agit des lymphocytes B, T et NK, dans des régions extra-ganglionnaires.","s":1},{"q":"Les lymphomes non hodgkiniens représentent environ quelle part des nouvelles néoplasies aux États-Unis ?","o":["1 %","4 %","15 %","30 %"],"r":1,"e":"Cette proportion en fait une hémopathie maligne fréquente, bien plus que le lymphome de Hodgkin.","s":1},{"q":"La forme indolente du lymphome non hodgkinien se manifeste par :","o":["Une adénopathie indolore, isolée ou disséminée","Une fièvre élevée, d'emblée","Une douleur ganglionnaire vive, à la palpation","Un ictère, avec des urines foncées et un prurit"],"r":0,"e":"Les ganglions mésentériques, rétropéritonéaux et pelviens peuvent être atteints, et l'atteinte médullaire est fréquente au diagnostic.","s":1},{"q":"L'évolution des formes indolentes de lymphome non hodgkinien s'étend sur :","o":["Quelques semaines","5 à 10 ans","6 mois","20 à 30 ans"],"r":1,"e":"Cette lenteur explique qu'elles soient habituellement déjà bien disséminées au moment du diagnostic.","s":1},{"q":"Les formes agressives de lymphome non hodgkinien se manifestent par :","o":["Fièvre, sueurs nocturnes, perte de poids","Adénopathie isolée, indolore","Asthénie simple, sans fièvre","Aucun symptôme, découverte fortuite"],"r":0,"e":"Elles s'accompagnent d'une susceptibilité accrue aux infections, mais sont sensibles à la radiothérapie et à la chimiothérapie.","s":1},{"q":"Le diagnostic du lymphome de Hodgkin repose sur la mise en évidence :","o":["De blastes circulants, dans le sang","De cellules de Reed-Sternberg, à la biopsie","D'une hyperleucocytose, à la numération","D'une anémie macrocytaire, au frottis"],"r":1,"e":"Elles sont recherchées à la biopsie du tissu lymphatique ; la biopsie médullaire sert, elle, à déterminer l'extension. Ce sont des cellules atypiques, de grande taille et mononucléées.","s":1},{"q":"Le lymphome de Hodgkin survient dans deux tranches d'âge :","o":["0 à 15 ans, puis 40 à 55 ans","15 à 40 ans et après 55 ans","20 à 30 ans uniquement","Après 70 ans uniquement"],"r":1,"e":"Seuls 10 à 15 % des cas surviennent chez l'enfant ou l'adolescent.","s":1},{"q":"L'examen qui détecte des altérations structurelles des ganglions imperceptibles au scanner est :","o":["L'échographie","La lymphangiographie","La radiographie standard","L'électrocardiogramme"],"r":1,"e":"Elle complète la biopsie ganglionnaire et la biopsie médullaire dans le bilan d'extension.","s":1},{"q":"Les leucémies myéloïdes se distinguent par le fait qu'elles :","o":["Touchent uniquement les lymphocytes","Atteignent les cellules souches","Restent confinées aux ganglions et à la rate","Ne touchent que les plaquettes"],"r":1,"e":"Les leucémies lymphocytaires impliquent, elles, les leucocytes immatures et leurs progéniteurs, infiltrant rate, ganglions et système nerveux central. Les cellules souches sont pluripotentes, et la maturation de toutes les cellules sanguines est perturbée.","s":1},{"q":"Le traitement d'intensification d'une leucémie a pour but :","o":["D'induire la rémission, au début","De réduire encore les cellules néoplasiques","De maintenir la rémission obtenue, sur plusieurs années","De prévenir les infections, en aplasie"],"r":1,"e":"Il s'intercale entre l'induction, qui induit la rémission, et l'entretien, qui la maintient.","s":1},{"q":"Les syndromes myéloprolifératifs ont en commun :","o":["Un défaut clonal des cellules progénitrices","Une carence en fer, par saignement digestif chronique","Une infection virale, chronique","Une origine auto-immune, avec des anticorps"],"r":0,"e":"Thrombocytémie essentielle, myélofibrose primitive et polyglobulie de Vaquez en sont les formes citées ; l'augmentation de la fibrose médullaire y entraîne une hématopoïèse extramédullaire. Ces progénitrices sont hématopoïétiques.","s":1},{"q":"Quelle est la durée de vie moyenne des érythrocytes ?","o":["120 jours","7 jours","6 heures","30 jours"],"r":0,"e":"Les plaquettes vivent 7 jours et les neutrophiles 6 heures.","s":2},{"q":"Quelle est la durée de vie moyenne des plaquettes ?","o":["7 jours","120 jours","6 heures","1 an"],"r":0,"e":"Les neutrophiles ne vivent que 6 heures.","s":2},{"q":"Quelle est la durée de vie moyenne des neutrophiles ?","o":["6 heures","7 jours","120 jours","24 heures"],"r":0,"e":"Les lymphocytes peuvent vivre de quelques heures à des années.","s":2},{"q":"Quelles sont les trois fonctions du système hématopoïétique ?","o":["Transport d'oxygène, défense, hémostase","Digestion, absorption, excrétion des déchets","Filtration, sécrétion, réabsorption","Contraction, conduction, automatisme"],"r":0,"e":"Elles justifient le renouvellement constant des cellules sanguines.","s":2},{"q":"Quand débute l'hématopoïèse ?","o":["Au 19ᵉ jour de vie intra-utérine","À la naissance, avec la moelle osseuse","Au 3ᵉ mois de la grossesse","À la puberté, sous l'effet hormonal"],"r":0,"e":"C'est un processus dynamique et permanent.","s":2},{"q":"Quelle est la proportion de cellules souches dans la moelle osseuse ?","o":["1 pour 30 000 cellules nucléées","1 pour 100 cellules nucléées","1 pour 1 000 cellules nucléées","1 pour 1 000 000 cellules nucléées"],"r":0,"e":"Elles résident dans des niches formées par des cellules du stroma.","s":2},{"q":"À partir de quel taux d'hémoglobine parle-t-on d'anémie chez l'homme adulte ?","o":["Moins de 13","Moins de 12","Moins de 11","Moins de 14"],"r":0,"e":"Le seuil est de 12 chez la femme adulte (OMS, 1968).","s":2},{"q":"Quel est le seuil d'anémie chez la femme enceinte ?","o":["Moins de 11","Moins de 12","Moins de 13","Moins de 10"],"r":0,"e":"Le même seuil s'applique aux enfants de 6 mois à 5 ans.","s":2},{"q":"Quel est le seuil d'anémie entre 6 et 14 ans ?","o":["Moins de 12","Moins de 11","Moins de 13","Moins de 10"],"r":0,"e":"Entre 6 mois et 5 ans, le seuil est de 11.","s":2},{"q":"Que mesure le RDW ?","o":["La variation de taille des hématies","Le volume globulaire moyen","La concentration moyenne en hémoglobine","Le nombre de réticulocytes"],"r":0,"e":"C'est un paramètre de l'hémogramme.","s":2},{"q":"Quels symptômes caractérisent une anémie aiguë ?","o":["Dyspnée, palpitations, étourdissements, fatigue","Peu de symptômes, une dyspnée modérée","Angor, insuffisance cardiaque congestive","Aucun symptôme, découverte fortuite au bilan sanguin"],"r":0,"e":"L'anémie chronique donne peu de symptômes, avec dyspnée modérée, fatigabilité, angor et ICC. La fatigue est extrême.","s":2},{"q":"De quoi dépendent les symptômes de l'anémie ?","o":["De la vitesse d'installation et de l'adaptation","Du seul taux d'hémoglobine mesuré","De l'âge seul, quel que soit le taux d'hémoglobine","Du sexe seul, sans autre facteur"],"r":0,"e":"On retrouve céphalées, vertiges, hypotension posturale et faiblesse musculaire.","s":2},{"q":"Quel élément de l'histoire clinique est spécifiquement recherché chez la femme en cas d'anémie ?","o":["Les pertes de sang des menstruations","Le nombre de grossesses antérieures","Le mode de contraception, hormonal ou non","L'âge des premières règles"],"r":0,"e":"On explore aussi comorbidités, traitements, profession, voyages, habitudes de vie et alimentation.","s":2},{"q":"Quels examens spécifiques peut-on demander devant une anémie ?","o":["Bilan martial, folates, électrophorèse, myélogramme","Hémogramme seul, répété à quelques semaines","Radiographie, échographie, scanner thoracique","Électrocardiogramme, épreuve d'effort, Holter"],"r":0,"e":"Le diagnostic repose d'abord sur l'anamnèse, l'examen physique, l'hémoglobine et la morphologie des hématies. On dose aussi la vitamine B12 ; l'électrophorèse est celle de l'hémoglobine, et la biopsie de moelle complète le myélogramme.","s":2},{"q":"Quels sont les trois mécanismes physiopathologiques de l'anémie ?","o":["Défaut de production, destruction, pertes","Carence, infection, inflammation","Aiguë, chronique ou mixte, selon l'évolution","Centrale, périphérique, mixte"],"r":0,"e":"Chaque mécanisme regroupe plusieurs causes. La destruction est excessive.","s":2},{"q":"Quelles causes relèvent d'un envahissement de la moelle osseuse ?","o":["Leucémies, lymphomes, myélomes, métastases","Paludisme, toxines et anticorps hémolysants","Thalassémies, drépanocytose","Hémorragies aiguës, traumatismes"],"r":0,"e":"C'est une cause de défaut de production. La fibrose médullaire en fait aussi partie.","s":2},{"q":"Quelles maladies sont à l'origine d'une anémie des maladies chroniques ?","o":["Inflammatoires, infectieuses, néoplasiques","Hémoglobinopathies, thalassémies","Traumatismes, hémorragies aiguës","Carences alimentaires isolées, en fer ou en folates"],"r":0,"e":"Elle relève du défaut de production.","s":2},{"q":"Quelles causes relèvent d'un défaut de l'érythrocyte lui-même ?","o":["Membrane, enzymes, hémoglobine anormale","Paludisme, toxines, agents infectieux variés","Anticorps, auto-immunité","Traumatismes, microangiopathie"],"r":0,"e":"Les autres relèvent d'une agression de l'érythrocyte. Membranopathies, érythroenzymopathies, hémoglobinopathies et thalassémies.","s":2},{"q":"Quel parasite est cité comme cause d'agression de l'érythrocyte ?","o":["Le paludisme","La toxoplasmose","L'amibiase","La giardiose"],"r":0,"e":"On retient aussi les poisons et toxines, les traumatismes microangiopathiques et les causes immunes.","s":2},{"q":"Que provoquent les pertes hémorragiques chroniques ?","o":["Une perte de fer, puis un défaut de production","Une hémolyse, par destruction des hématies","Une aplasie médullaire, par arrêt de la moelle osseuse","Une thrombocytose, réactionnelle"],"r":0,"e":"Les pertes peuvent être aiguës ou chroniques.","s":2},{"q":"Comment caractérise-t-on l'anémie aplasique ?","o":["Une maladie auto-immune, de cause inconnue","Une carence en fer, d'origine digestive","Une hémoglobinopathie héréditaire, transmise","Une conséquence d'un saignement aigu"],"r":0,"e":"La moelle osseuse cesse de produire la quantité adéquate de sang.","s":2},{"q":"Quels sont les symptômes de l'anémie aplasique ?","o":["Pâleur, ecchymoses spontanées, saignements prolongés","Ictère, urines foncées, douleurs abdominales récidivantes","Douleurs osseuses isolées, sans saignement","Fièvre isolée, sans autre signe"],"r":0,"e":"Elle peut conduire au décès par infections en environ 10 mois.","s":2},{"q":"En combien de temps l'anémie aplasique peut-elle conduire au décès par infections ?","o":["Environ 10 mois","Environ 10 jours","Environ 5 ans","Immédiatement"],"r":0,"e":"Le traitement comprend transfusions, greffe de moelle, antibiotiques et immunosuppresseurs.","s":2},{"q":"Quel traitement de l'anémie aplasique est cité ?","o":["Transfusions, greffe de moelle, immunosuppresseurs","Fer seul, par voie orale","Vitamine B12 seule, en injection","Corticothérapie locale, en pommade appliquée sur la peau"],"r":0,"e":"Le diagnostic repose notamment sur la biopsie de moelle et l'étude cytogénétique. Les antibiotiques complètent le traitement.","s":2},{"q":"D'où vient le terme « falciforme » de la drépanocytose ?","o":["Du latin falci-, la faux, par la forme des hématies","Du grec drepanon, qui désigne une serpe","Du nom du médecin qui l'a décrite en premier","De la forme des leucocytes, en croissant de lune"],"r":0,"e":"C'est une maladie hématologique héréditaire monogénique. La forme la plus fréquente est l'HbS, de l'anglais sickle (faucille).","s":2},{"q":"Quelle conséquence a la production anormale d'hémoglobine dans la drépanocytose ?","o":["Un transport d'oxygène et de gaz carbonique déficient","Une thrombocytose, par excès de plaquettes","Une leucopénie isolée, sans anémie","Une carence en fer, par un saignement digestif chronique"],"r":0,"e":"C'est une maladie héréditaire monogénique. D'autres complications s'y ajoutent.","s":2},{"q":"Comment appelle-t-on les anémies causées par des carences en vitamines ?","o":["Anémies mégaloblastiques","Anémies ferriprives","Anémies aplasiques","Anémies hémolytiques"],"r":0,"e":"Certaines formes par carence en B12 sont appelées anémies pernicieuses.","s":2},{"q":"Quels sont les trois processus de l'hémostase ?","o":["Hémostase primaire, coagulation, puis fibrinolyse","Adhésion, agrégation, sécrétion des plaquettes","Vasoconstriction, thrombose, embolie","Synthèse, stockage, libération des facteurs"],"r":0,"e":"C'est la réponse immédiate à la lésion d'un vaisseau sanguin. La coagulation correspond à l'hémostase secondaire.","s":2},{"q":"En quoi consiste la coagulation sanguine ?","o":["La conversion du fibrinogène en fibrine, par la thrombine","La contraction des plaquettes, dans le caillot","La vasoconstriction réflexe du vaisseau lésé, dès la blessure","La dégradation de la fibrine, par la plasmine"],"r":0,"e":"C'est l'hémostase secondaire. Le fibrinogène est soluble, la fibrine insoluble.","s":2},{"q":"Quelles manifestations évoquent une altération de la coagulation plutôt que de l'hémostase primaire ?","o":["Hématomes, hémarthroses, hémorragies tardives","Pétéchies et ecchymoses multiples, cutanées","Épistaxis, gingivorragies, ménorragies","Hémorragie immédiate, dès le traumatisme"],"r":0,"e":"Les autres propositions caractérisent les altérations de l'hémostase primaire. Les saignements au point de ponction veineuse en font aussi partie.","s":2},{"q":"La durée de vie moyenne des érythrocytes est de :","o":["7 jours","30 jours","120 jours","6 heures"],"r":2,"e":"Les plaquettes vivent environ 7 jours et les neutrophiles seulement 6 heures : ces durées expliquent la rapidité d'apparition de chaque cytopénie en cas d'aplasie.","s":2},{"q":"La durée de vie des plaquettes est d'environ :","o":["6 heures","7 jours","120 jours","1 an"],"r":1,"e":"C'est pourquoi une thrombopénie centrale apparaît en une semaine, bien avant l'anémie qui demande plusieurs mois.","s":2},{"q":"La durée de vie des neutrophiles est d'environ :","o":["6 heures","7 jours","120 jours","24 heures"],"r":0,"e":"Cette durée extrêmement courte fait de la neutropénie la première manifestation d'un arrêt de l'hématopoïèse — d'où le risque infectieux précoce.","s":2},{"q":"L'hématopoïèse débute chez l'embryon :","o":["Au 19ᵉ jour","Au 3ᵉ mois","À la naissance","À la 10ᵉ semaine"],"r":0,"e":"Le site de production migre ensuite du sac vitellin vers le foie et la rate, puis vers la moelle osseuse.","s":2},{"q":"La proportion de cellules souches hématopoïétiques dans la moelle est d'environ :","o":["1 sur 100","1 sur 1 000","1 sur 30 000","1 sur 10"],"r":2,"e":"Cette rareté explique la difficulté technique des greffes et l'importance des facteurs de mobilisation avant prélèvement.","s":2},{"q":"Selon la classification physiopathologique, les anémies se répartissent en :","o":["Microcytaires et macrocytaires","Production, destruction, pertes","Aiguës et chroniques, selon l'évolution","Centrales et périphériques"],"r":1,"e":"La classification morphologique, elle, se fonde sur le VGM : microcytaire, normocytaire, macrocytaire. Défaut de production, excès de destruction et pertes sanguines.","s":2},{"q":"Le RDW mesure :","o":["Le volume globulaire moyen, en femtolitres","La variation de taille des érythrocytes","La concentration en hémoglobine","Le nombre de réticulocytes"],"r":1,"e":"Un RDW élevé oriente vers une carence martiale ou une population érythrocytaire hétérogène, même si le VGM reste normal. Cette variation s'appelle l'anisocytose.","s":2},{"q":"L'anémie aplasique non traitée évolue classiquement vers :","o":["Une guérison spontanée, en quelques mois","Le décès par infections, en une dizaine de mois","Une transformation en polyglobulie","Une simple asthénie chronique, sans complication grave"],"r":1,"e":"La neutropénie profonde est le facteur pronostique dominant, bien avant l'anémie elle-même.","s":2},{"q":"La drépanocytose est liée à :","o":["Un déficit en fer, d'origine alimentaire","Une hémoglobine S, qui déforme l'hématie","Un déficit en vitamine B12, par malabsorption","Une hémolyse auto-immune, par anticorps"],"r":1,"e":"La falciformation obstrue la microcirculation et provoque les crises vaso-occlusives douloureuses caractéristiques. L'hématie prend une forme de faucille.","s":2},{"q":"Les anémies mégaloblastiques sont dues à :","o":["Un défaut de synthèse de l'ADN, par carence","Une carence en fer, par saignement chronique","Une hémorragie aiguë, après un traumatisme","Un déficit en EPO, par insuffisance rénale"],"r":0,"e":"L'anémie pernicieuse en est la forme liée au défaut de facteur intrinsèque, qui empêche l'absorption iléale de la B12. La carence porte sur la vitamine B12 ou les folates.","s":2},{"q":"L'hémostase se décompose en :","o":["Deux processus","Trois processus","Quatre processus","Un processus unique"],"r":1,"e":"Hémostase primaire (vasculo-plaquettaire), coagulation et fibrinolyse se succèdent et se chevauchent dans le temps.","s":2},{"q":"La maladie de von Willebrand se transmet sur un mode :","o":["Récessif lié à l'X","Autosomique","Mitochondrial","Non héréditaire"],"r":1,"e":"À la différence de l'hémophilie, récessive liée à l'X, elle touche donc autant les femmes que les hommes.","s":2},{"q":"L'hémophilie se transmet sur un mode :","o":["Autosomique dominant","Récessif lié au chromosome X","Autosomique récessif","Sporadique exclusivement"],"r":1,"e":"Les femmes sont donc conductrices et les garçons atteints, sauf exception de lyonisation extrême.","s":2},{"q":"Dans le bilan de coagulation, l'INR sert principalement à :","o":["Standardiser le temps de Quick, sous antivitamines K","Mesurer le nombre de plaquettes circulantes","Doser le fibrinogène plasmatique","Évaluer la fibrinolyse, et donc la dissolution du caillot"],"r":0,"e":"Le TCA explore la voie intrinsèque et le TP/TQ la voie extrinsèque ; les PDF témoignent, eux, de la fibrinolyse.","s":2},{"q":"Le TCA (temps de céphaline activée) explore :","o":["La voie extrinsèque de la coagulation, avec le TP","La voie intrinsèque de la coagulation","L'hémostase primaire, les plaquettes","La fibrinolyse, la dissolution du caillot"],"r":1,"e":"Le temps de Quick / TP explore la voie extrinsèque, et le temps de saignement l'hémostase primaire.","s":2},{"q":"La présence de PDF (produits de dégradation de la fibrine) témoigne :","o":["D'une activation de la fibrinolyse","D'une thrombopénie, sévère","D'une carence en vitamine K, par malabsorption","D'une hémolyse intravasculaire"],"r":0,"e":"Leur élévation majeure oriente notamment vers une coagulation intravasculaire disséminée.","s":2},{"q":"Le temps de saignement (TS) explore :","o":["La coagulation plasmatique, voie intrinsèque","L'hémostase primaire, plaquettaire et vasculaire","La fibrinolyse, par la plasmine","La synthèse hépatique des facteurs"],"r":1,"e":"Il est allongé dans la maladie de von Willebrand et les thrombopathies, alors que le TCA et le TP restent normaux.","s":2},{"q":"Les seuils d'anémie utilisés en pratique proviennent des critères :","o":["De l'Organisation mondiale de la santé","De la Société européenne d'hématologie","Des recommandations françaises récentes","Propres à chaque laboratoire d'analyses médicales"],"r":0,"e":"Ces seuils varient selon l'âge, le sexe et l'état de grossesse, ce qui explique qu'un même chiffre d'hémoglobine ne soit pas interprété de la même façon chez tous. Ces critères de l'OMS datent de 1968.","s":2},{"q":"L'excès de destruction des érythrocytes correspond à :","o":["Une anémie hémolytique","Une anémie aplasique","Une anémie ferriprive","Une anémie inflammatoire"],"r":0,"e":"Elle s'accompagne d'une réticulocytose élevée, signant une moelle qui répond — au contraire des anémies par défaut de production.","s":2},{"q":"Le dosage du fibrinogène est utile car ce facteur :","o":["Est le substrat final, transformé en fibrine","Reflète le nombre de plaquettes circulantes, dans le sang","Reflète la fonction rénale, par sa clairance","Évalue l'hémostase primaire, vasculaire"],"r":0,"e":"Son effondrement, associé à des PDF élevés, est très évocateur d'une consommation intravasculaire. La thrombine le transforme en fibrine.","s":2},{"q":"Quelles sont les valves du cœur gauche ?","o":["L'aortique et la mitrale","La tricuspide et la pulmonaire","L'aortique et la pulmonaire","La mitrale et la tricuspide"],"r":0,"e":"La tricuspide et la pulmonaire appartiennent au cœur droit.","s":3},{"q":"De quoi sont constituées les valves cardiaques humaines ?","o":["De cuspides","De cordages seuls","De muscles papillaires","De fibres élastiques uniquement"],"r":0,"e":"Elles s'ouvrent pour laisser passer le sang et se ferment pour empêcher le reflux.","s":3},{"q":"Qu'est-ce qu'une sténose valvulaire ?","o":["Une ouverture trop étroite, qui gêne le flux vers l'avant","Une fermeture incomplète, avec un reflux","Une valve absente, par une malformation congénitale du cœur","Une valve calcifiée, sans aucune conséquence"],"r":0,"e":"La régurgitation correspond à une fermeture incomplète avec fuite.","s":3},{"q":"Qu'est-ce qu'une régurgitation valvulaire ?","o":["Une valve qui ne se ferme pas bien et laisse refluer le sang","Une ouverture trop étroite, qui gêne le passage du sang","Une valve fusionnée, dont les feuillets sont soudés","Une valve rigide et calcifiée, immobile pendant tout le cycle"],"r":0,"e":"On l'appelle aussi insuffisance valvulaire.","s":3},{"q":"Quelle infection peut être à l'origine d'un rhumatisme articulaire aigu ?","o":["Une pharyngite à streptocoque, non traitée","Une infection urinaire, à colibacille","Une pneumonie virale, saisonnière","Une gastro-entérite, à rotavirus chez l'enfant"],"r":0,"e":"C'est l'une des causes les plus fréquentes de valvulopathie acquise. C'est une infection bactérienne.","s":3},{"q":"Qu'est-ce que le rétrécissement aortique calcifié idiopathique ?","o":["Une dégénérescence du sujet âgé, avec cuspides calcifiées","Une infection des valves, par une bactérie du sang circulant","Une maladie congénitale, présente dès la naissance","Une conséquence tardive de la syphilis"],"r":0,"e":"C'est une cause fréquente de valvulopathie acquise. Les cuspides s'épaississent, fusionnent et s'infiltrent de calcium.","s":3},{"q":"Quelle maladie du tissu conjonctif est citée parmi les causes de valvulopathie ?","o":["Le syndrome de Marfan","La polyarthrite rhumatoïde","Le lupus","La sclérodermie"],"r":0,"e":"On retient aussi la syphilis, l'hypertension et l'athérosclérose.","s":3},{"q":"Comment découvre-t-on souvent une valvulopathie légère ?","o":["Par un souffle cardiaque, à l'auscultation","Par une douleur thoracique, à l'effort intense","Par une syncope, en position debout","Par un œdème des membres inférieurs"],"r":0,"e":"Les problèmes valvulaires légers n'ont pas de symptômes.","s":3},{"q":"À partir de quel degré de rétrécissement le rétrécissement aortique devient-il symptomatique ?","o":["Quand l'ouverture tombe à un tiers de la normale","Dès 10 % de rétrécissement de l'ouverture","Quand l'ouverture tombe à la moitié de la normale, environ","Dès l'apparition de la calcification"],"r":0,"e":"Les symptômes sont alors dyspnée d'effort, angor et syncopes.","s":3},{"q":"Quels sont les symptômes du rétrécissement aortique ?","o":["Dyspnée d'effort, angor, syncopes","Hémoptysies, fibrillation","Fatigue, ascite isolée","Cyanose, chez le nouveau-né"],"r":0,"e":"Ils apparaissent lorsque l'ouverture se réduit à environ un tiers de la normale.","s":3},{"q":"Pendant combien de temps l'insuffisance aortique peut-elle rester peu symptomatique ?","o":["10 à 15 ans","1 à 2 ans","30 ans","Quelques mois"],"r":0,"e":"Les premiers symptômes sont palpitations, arythmies, dyspnée d'effort et orthopnée.","s":3},{"q":"Quelle arythmie est particulièrement associée au rétrécissement mitral ?","o":["La fibrillation auriculaire","La tachycardie ventriculaire","Le bloc auriculo-ventriculaire complet","La bradycardie sinusale"],"r":0,"e":"Des thrombus peuvent se former dans l'oreillette gauche.","s":3},{"q":"Quel symptôme respiratoire est caractéristique du rétrécissement mitral ?","o":["Les hémoptysies","La toux productive","Le stridor","L'apnée du sommeil"],"r":0,"e":"On retrouve aussi une dyspnée d'effort et une dyspnée paroxystique nocturne.","s":3},{"q":"Quel risque emboligène présente le rétrécissement mitral ?","o":["Des thrombus de l'oreillette gauche, migrant vers les organes","Une embolie pulmonaire massive, d'origine veineuse","Une thrombose veineuse profonde, au mollet","Aucun risque, la circulation restant rapide dans l'oreillette"],"r":0,"e":"Ce risque est lié à la stase et à la fibrillation auriculaire. Ils peuvent léser le cerveau, la rate ou les reins.","s":3},{"q":"Quels sont les symptômes de l'insuffisance mitrale ?","o":["Fatigue, essoufflement à l'effort, orthopnée","Syncopes d'effort, angor, douleur thoracique serrée","Hémoptysies, toux sanglante","Cyanose isolée, des extrémités"],"r":0,"e":"Le rétrécissement mitral donne plutôt des hémoptysies et une fibrillation auriculaire. L'orthopnée est la difficulté à respirer allongé.","s":3},{"q":"Quelle valvulopathie donne principalement une gêne respiratoire par insuffisance cardiaque ?","o":["L'insuffisance tricuspide","Le rétrécissement aortique","L'insuffisance aortique","Le rétrécissement mitral"],"r":0,"e":"Le rétrécissement tricuspide donne surtout fatigue et symptômes d'insuffisance cardiaque.","s":3},{"q":"Comment prévenir les valvulopathies acquises liées au rhumatisme articulaire aigu ?","o":["Par des antibiotiques bien pris contre l'angine à streptocoque","Par la vaccination de tous les enfants, dès la première année de vie","Par un régime pauvre en sel, au long cours","Par l'exercice physique seul, sans traitement"],"r":0,"e":"Le changement des modes de vie est également recommandé. Il faut prendre les antibiotiques exactement selon la prescription.","s":3},{"q":"En quoi consiste la valvuloplastie percutanée par ballonnet ?","o":["Un ballonnet gonflé puis retiré à travers la valve","Une séparation chirurgicale des feuillets, à cœur ouvert","Un remplacement de la valve par une prothèse","La pose d'un stent dans une artère coronaire"],"r":0,"e":"Elle s'adresse à la sténose. Le ballonnet est monté sur un cathéter et élargit la valve rétrécie.","s":3},{"q":"Quelle conséquence a la pose d'une valve mécanique ?","o":["Un traitement anticoagulant, contre les caillots","Une antibiothérapie à vie, contre l'endocardite infectieuse","Aucune contrainte particulière, à long terme","Une immunosuppression, contre le rejet"],"r":0,"e":"Les valves biologiques proviennent de tissu de porc, de vache ou d'un donneur humain décédé.","s":3},{"q":"Qu'est-ce qu'une myocardiopathie ?","o":["Une atteinte du myocarde, qui se contracte mal","Une atteinte des valves, qui fuient","Une inflammation du péricarde, l'enveloppe","Une atteinte des coronaires, par l'athérome"],"r":0,"e":"On distingue trois types : dilatée, hypertrophique et restrictive. Une partie ou la totalité du cœur ne se contracte plus normalement.","s":3},{"q":"Que se passe-t-il dans la myocardiopathie dilatée ?","o":["Le muscle se distend, le cœur grossit et pompe moins","La paroi s'épaissit, le muscle ne se relâche plus","Les parois deviennent rigides, le cœur se remplit mal et peu","La valve aortique se rétrécit, le flux est gêné"],"r":0,"e":"Cela aboutit à une insuffisance cardiaque.","s":3},{"q":"Que caractérise la myocardiopathie hypertrophique ?","o":["La paroi s'épaissit et ne se relâche pas au remplissage","Le muscle se distend et le cœur augmente de taille","Les parois sont infiltrées de fibrose et rigides","L'oreillette se dilate de façon isolée et chronique"],"r":0,"e":"Ses symptômes sont semblables à ceux de la forme dilatée.","s":3},{"q":"Que caractérise la myocardiopathie restrictive ?","o":["Des parois rigides, qui empêchent le remplissage","Une paroi amincie, qui se distend à chaque contraction","Un ventricule dilaté, qui pompe moins","Une valve incompétente, qui fuit"],"r":0,"e":"Ses symptômes prédominants sont liés à l'œdème, avec ascite. La rigidité vient d'infiltrats ou d'une fibrose.","s":3},{"q":"Quels symptômes prédominent dans la myocardiopathie restrictive ?","o":["Ceux de l'œdème, aux jambes et à l'abdomen","Angor et syncopes, à l'effort","Palpitations isolées, au repos comme à l'effort","Hémoptysies, toux sanglante"],"r":0,"e":"Les formes dilatée et hypertrophique donnent dyspnée d'effort, fatigue, orthopnée, œdèmes, palpitations et angor. L'œdème abdominal est une ascite ; la dyspnée d'effort apparaît ensuite.","s":3},{"q":"Quels systèmes sont impliqués dans l'hypertension artérielle ?","o":["Sympathique, rein, rénine-angiotensine, endothélium","La génétique seule, sans aucun facteur d'environnement","Le système nerveux seul, sans autre facteur","La fonction rénale seule, sans autre facteur"],"r":0,"e":"L'HTA est multifactorielle. L'environnement et la génétique jouent aussi.","s":3},{"q":"Quelles sont les valeurs normales de pression artérielle ?","o":["Systolique inférieure à 120 et diastolique inférieure à 80 mmHg","Systolique inférieure à 140 et diastolique inférieure à 90","Systolique inférieure à 130","Systolique inférieure à 110"],"r":0,"e":"La pré-hypertension correspond à 120-139 de systolique ou 80-89 de diastolique.","s":3},{"q":"Qu'est-ce que la pré-hypertension ?","o":["Systolique de 120 à 139, ou diastolique de 80 à 89","Systolique de 140 à 159, ou diastolique de 90 à 99","Systolique supérieure à 160, ou diastolique à 100","Systolique inférieure à 120, et diastolique à 80"],"r":0,"e":"Les valeurs normales sont < 120 et < 80. Les valeurs sont en mmHg.","s":3},{"q":"Quels organes l'hypertension peut-elle léser ?","o":["Le cerveau, les yeux, le cœur, les reins","Le cœur seul, par l'hypertrophie du ventricule","Les reins seuls, par la néphroangiosclérose","Le cerveau seul, par l'accident vasculaire"],"r":0,"e":"Non traitée, elle peut conduire à un infarctus, un AVC ou une insuffisance rénale. Toutes les artères du corps peuvent être lésées.","s":3},{"q":"Quels symptômes peut donner une hypertension très élevée ?","o":["Maux de tête, étourdissements, fatigue, acouphènes","Une douleur thoracique constrictive, à l'effort","Une claudication intermittente, au mollet, à la marche","Des hémoptysies, avec une toux"],"r":0,"e":"L'HTA est le plus souvent asymptomatique.","s":3},{"q":"Comment se manifeste une AOMI légère ?","o":["Par une claudication, ou aucun symptôme","Par une douleur de repos, la nuit","Par une gangrène sèche des orteils","Par des ulcères ischémiques du pied"],"r":0,"e":"L'AOMI grave donne une douleur de repos, une cyanose, des ulcères ischémiques et une gangrène. La claudication est intermittente.","s":3},{"q":"Les valves du cœur droit sont :","o":["Aortique et mitrale","Tricuspide et pulmonaire","Mitrale et tricuspide","Aortique et pulmonaire"],"r":1,"e":"Les valves aortique et mitrale appartiennent, elles, au cœur gauche.","s":3},{"q":"Les valves cardiaques sont constituées :","o":["De cuspides","De cartilage","De tissu adipeux","De fibres musculaires lisses"],"r":0,"e":"Elles s'ouvrent pour laisser passer le sang vers l'avant et se ferment pour empêcher le reflux.","s":3},{"q":"Une sténose valvulaire correspond à :","o":["Une valve qui ne se ferme pas, avec une fuite","Une ouverture trop étroite, qui gêne le flux","Une valve calcifiée, mais fonctionnelle","Une absence de valve, congénitale"],"r":1,"e":"La régurgitation, à l'inverse, désigne une valve qui fuit et laisse refluer le sang.","s":3},{"q":"Le rhumatisme articulaire aigu peut faire suite à :","o":["Une angine à streptocoque, non traitée","Une grippe saisonnière, virale","Une infection urinaire, basse","Une hépatite virale, de type A ou de type B"],"r":0,"e":"C'est pourquoi la prévention passe par le traitement antibiotique complet de la pharyngite streptococcique.","s":3},{"q":"Le rétrécissement aortique calcifié idiopathique est :","o":["Une malformation congénitale, dès la naissance","Une dégénérescence du sujet âgé, avec calcification","Une conséquence d'une endocardite infectieuse ancienne","Une maladie auto-immune, avec des anticorps"],"r":1,"e":"Il figure parmi les causes acquises de valvulopathie, aux côtés du rhumatisme articulaire aigu et de l'endocardite. Les cuspides s'épaississent, fusionnent et s'infiltrent de calcium.","s":3},{"q":"Une valvulopathie légère est le plus souvent découverte :","o":["Devant une dyspnée d'effort","À l'auscultation d'un souffle cardiaque","Devant un angor, à l'effort","Sur un électrocardiogramme de routine"],"r":1,"e":"Les problèmes valvulaires légers n'ont pas de symptômes ; ceux-ci n'apparaissent que dans les formes plus graves et varient selon la valve concernée.","s":3},{"q":"Le rétrécissement aortique devient symptomatique lorsque l'ouverture se rétrécit jusqu'à environ :","o":["La moitié de la normale","Un tiers de la normale","Les deux tiers de la normale","Un dixième de la normale"],"r":1,"e":"Apparaissent alors dyspnée d'effort, angor et syncopes.","s":3},{"q":"L'insuffisance aortique peut rester peu symptomatique pendant :","o":["1 à 2 ans","10 à 15 ans","6 mois","30 ans"],"r":1,"e":"Les premiers symptômes sont ensuite palpitations, arythmies, dyspnée d'effort, orthopnée, dyspnée paroxystique nocturne, sudation et angor.","s":3},{"q":"Quel symptôme respiratoire caractéristique accompagne le rétrécissement mitral ?","o":["Une toux sèche","Des hémoptysies","Un wheezing","Une apnée du sommeil"],"r":1,"e":"S'y associent dyspnée d'effort, dyspnée paroxystique nocturne et arythmies.","s":3},{"q":"L'insuffisance mitrale se manifeste par :","o":["Fatigue, essoufflement à l'effort, orthopnée","Des syncopes d'effort, brutales","Un angor typique, constrictif, irradiant au bras","Des hémoptysies, avec une toux"],"r":0,"e":"Les syncopes d'effort orientent plutôt vers un rétrécissement aortique serré.","s":3},{"q":"L'insuffisance tricuspide donne principalement :","o":["Une insuffisance cardiaque, avec une gêne respiratoire","Un angor d'effort, constrictif","Des syncopes, à l'effort","Des hémoptysies, avec une toux et des crachats sanglants"],"r":0,"e":"Le rétrécissement tricuspide donne, lui, fatigue et symptômes d'insuffisance cardiaque, souvent associés à ceux d'un rétrécissement mitral.","s":3},{"q":"La valvuloplastie percutanée par ballonnet consiste à :","o":["Remplacer la valve par une prothèse mécanique","Gonfler puis retirer un ballonnet dans la valve","Suturer les feuillets, à cœur ouvert","Poser un stent dans une artère coronaire"],"r":1,"e":"La valvulotomie chirurgicale traditionnelle, plus invasive, sépare les feuillets fusionnés à cœur ouvert. Le ballonnet est monté sur un cathéter et élargit la valve.","s":3},{"q":"La pose d'une valve mécanique impose :","o":["Une antibiothérapie au long cours","Un traitement anticoagulant, à vie","Un régime strictement sans sel","Une immunosuppression, à vie"],"r":1,"e":"Les valves biologiques — tissu de porc, de vache ou de donneur humain décédé — n'imposent pas cette contrainte. Il prévient la formation de caillots.","s":3},{"q":"Dans la myocardiopathie hypertrophique :","o":["Le muscle cardiaque se distend de façon excessive","La paroi s'épaissit et se relâche mal","Les parois sont rigides, infiltrées","Le cœur diminue nettement de volume"],"r":1,"e":"La forme dilatée correspond à une distension excessive, et la forme restrictive à des parois rigidifiées par des facteurs externes comme une fibrose. Le muscle ne se relâche pas lors du remplissage.","s":3},{"q":"Dans la myocardiopathie restrictive, les symptômes prédominants sont liés :","o":["À l'angor, qui survient surtout à l'effort","À l'œdème des jambes et de l'abdomen","Aux syncopes, au lever brutal","Aux palpitations, isolées"],"r":1,"e":"Les formes dilatée et hypertrophique donnent, elles, des tableaux semblables entre eux : dyspnée d'effort, fatigue, orthopnée, œdèmes, palpitations et angor. L'œdème abdominal est une ascite ; la dyspnée s'aggrave ensuite à l'effort.","s":3},{"q":"Les valeurs normales de pression artérielle sont définies par :","o":["Une systolique inférieure à 120 et une diastolique inférieure à 80 mmHg","Une systolique inférieure à 140 et une diastolique inférieure à 90 mmHg","Une systolique inférieure à 130 mmHg uniquement","Une diastolique inférieure à 70 mmHg uniquement"],"r":0,"e":"La pré-hypertension correspond à une systolique entre 120 et 139 ou une diastolique entre 80 et 89 mmHg.","s":3},{"q":"Parmi les systèmes impliqués dans l'hypertension artérielle, le cours cite :","o":["Sympathique, rein, rénine-angiotensine, endothélium","Le seul système rénine-angiotensine","Le système digestif, le foie","Le système lymphatique, la rate, le thymus et les ganglions"],"r":0,"e":"L'environnement et la génétique complètent ce tableau multifactoriel. La dysfonction endothéliale est en cause.","s":3},{"q":"L'AOMI grave se manifeste par :","o":["Une claudication intermittente isolée, à la marche","Une douleur de repos, une cyanose, des ulcères","Un œdème des membres inférieurs","Des varices, sur les deux jambes"],"r":1,"e":"L'AOMI légère peut, elle, être asymptomatique ou se limiter à une claudication intermittente. La gangrène en fait aussi partie ; les ulcères sont ischémiques.","s":3},{"q":"Dans une valvulopathie congénitale, le rétrécissement de la valve entraîne :","o":["Une cyanose, puis une insuffisance cardiaque","Un angor isolé, à l'effort","Une hypertension artérielle, chez le nourrisson","Une fibrillation auriculaire, précoce"],"r":0,"e":"Chez l'adulte, à l'inverse, les valvulopathies acquises se révèlent le plus souvent par un souffle avant tout symptôme.","s":3},{"q":"Une atteinte de la valve pulmonaire se manifeste par :","o":["Un angor typique, constrictif et irradiant","Fatigue, malaises, insuffisance cardiaque","Des hémoptysies, avec une toux sèche","Des syncopes d'effort, sans prodrome"],"r":1,"e":"Les hémoptysies orientent vers un rétrécissement mitral et les syncopes d'effort vers un rétrécissement aortique serré.","s":3},{"q":"Quelles sont les cinq fonctions du système gastro-intestinal ?","o":["Motilité, sécrétion, digestion, absorption, excrétion","Digestion, absorption, défécation, stockage, filtration","Sécrétion, transport, stockage, détoxification","Motilité, filtration, excrétion, immunité"],"r":0,"e":"La motilité est contrôlée par des mécanismes neuraux, myogéniques et hormonaux.","s":4},{"q":"Où sont absorbés le fer, le calcium, les graisses et les glucides ?","o":["Dans l'intestin grêle proximal","Dans l'intestin grêle distal","Dans le côlon","Dans l'estomac"],"r":0,"e":"L'intestin grêle distal absorbe la vitamine B12, les sels biliaires et l'eau.","s":4},{"q":"Où est absorbée la vitamine B12 ?","o":["Dans l'intestin grêle distal","Dans l'intestin grêle proximal","Dans le côlon","Dans l'estomac"],"r":0,"e":"Le côlon absorbe l'eau et les électrolytes.","s":4},{"q":"Quelle est la différence entre vomissement et régurgitation ?","o":["Le vomissement est forcé, la régurgitation douce","La régurgitation est plus violente, avec nausées","Le vomissement est indolore, sans aucune nausée","Ce sont deux synonymes, sans différence réelle"],"r":0,"e":"Les haut-le-cœur sont l'activité respiratoire rythmique forcée qui précède l'émèse. La régurgitation se fait sans nausées ni contraction du diaphragme.","s":4},{"q":"Où se situe le centre du vomissement ?","o":["Dans le tronc cérébral","Dans le quatrième ventricule","Dans l'hypothalamus","Dans le cortex insulaire"],"r":0,"e":"La zone gâchette chémoréceptrice se situe dans le quatrième ventricule.","s":4},{"q":"Où se situe la zone gâchette chémoréceptrice ?","o":["Dans le quatrième ventricule","Dans le tronc cérébral, au niveau du bulbe","Dans le cervelet","Dans le thalamus"],"r":0,"e":"Elle détecte les substances nocives dans le sang et envoie des signaux au centre du vomissement.","s":4},{"q":"Quel nerf est stimulé par les toxines, infections ou obstructions digestives ?","o":["Le nerf vague","Le nerf phrénique","Le nerf splanchnique","Le nerf glossopharyngien"],"r":0,"e":"Il envoie ensuite des signaux au centre du vomissement.","s":4},{"q":"Que se passe-t-il à l'étape 4 du mécanisme du vomissement ?","o":["Le palais mou s'élève, la glotte se ferme","Le sphincter œsophagien inférieur se contracte","La pression intra-abdominale diminue, puis s'annule","Le diaphragme se relâche complètement"],"r":0,"e":"L'expulsion du contenu gastrique constitue la 5ᵉ et dernière étape. La fermeture de la glotte protège les voies aériennes.","s":4},{"q":"Que suggère une émèse fécaloïde ?","o":["Une obstruction intestinale","Une hypertension intracrânienne","Un ulcère peptique","Une cause psychogène"],"r":0,"e":"Un vomissement en jet évoque une pression intracrânienne.","s":4},{"q":"Que suggère un vomissement en jet ?","o":["Une pression intracrânienne","Une obstruction intestinale","Une cause psychogène","Une gastrite"],"r":0,"e":"Les vomissements survenant à la suite du repas évoquent des causes psychogènes ou un ulcère peptique.","s":4},{"q":"Quelle complication respiratoire peut résulter des vomissements ?","o":["La pneumonie d'aspiration","L'asthme","Le pneumothorax","L'embolie pulmonaire"],"r":0,"e":"On retient aussi la rupture de l'œsophage, la déshydratation, la dénutrition et les érosions dentaires.","s":4},{"q":"Quelle proportion d'Américains rapporte des brûlures d'estomac quotidiennes ?","o":["7 %","40 %","15 %","30 %"],"r":0,"e":"40 % en rapportent une fois par mois.","s":4},{"q":"Quelle proportion des cas de maladie ulcéreuse peptique est liée à H. pylori ou aux anti-inflammatoires ?","o":["15 %","7 %","40 %","80 %"],"r":0,"e":"Les brûlures d'estomac concernent 40 % des Américains une fois par mois.","s":4},{"q":"Quelle manifestation extra-œsophagienne du reflux est citée ?","o":["L'asthme, la laryngite, la toux chronique","La céphalée, la migraine ophtalmique","L'arthralgie, la raideur articulaire matinale","La dermatite, l'eczéma des mains"],"r":0,"e":"On retient aussi la pneumonie d'aspiration, les caries dentaires, l'halitose et les hoquets. L'apnée du sommeil en fait aussi partie.","s":4},{"q":"Quel signe d'alarme impose une exploration devant une indigestion ?","o":["Une dysphagie, un amaigrissement, un saignement","Des brûlures d'estomac occasionnelles","Une régurgitation après un repas copieux","Un hoquet, après une boisson gazeuse prise trop vite"],"r":0,"e":"Les masses palpables et les adénopathies en font aussi partie. L'amaigrissement doit être inexpliqué.","s":4},{"q":"Quelle perte de poids impose une évaluation supplémentaire ?","o":["5 % du poids en 6 à 12 mois","1 % du poids, en un seul mois","20 % du poids en 5 ans","Toute perte, même minime"],"r":0,"e":"Les fluctuations rapides en quelques jours traduisent une perte ou une accumulation de liquides.","s":4},{"q":"Quelles causes de perte de poids prédominent chez le sujet âgé ?","o":["Dépression, cancer, maladie digestive","Diabète, hyperthyroïdie, infections","Anorexie mentale, boulimie","Infection par le VIH, tuberculose ancienne"],"r":0,"e":"Chez le sujet jeune : diabète, hyperthyroïdie, anorexie mentale et infections, notamment le VIH. La maladie est gastro-intestinale.","s":4},{"q":"Qu'est-ce que le globus pharyngé ?","o":["Une sensation de masse dans la gorge, sans gêne à avaler","Une douleur à la déglutition, vive et brûlante, à chaque gorgée","Une difficulté de progression du bol alimentaire","Une paralysie de la langue, d'origine centrale"],"r":0,"e":"L'odynophagie est la douleur à la déglutition.","s":4},{"q":"Quelle cause EXTRINSÈQUE d'obstruction mécanique est citée ?","o":["Une spondylite cervicale ou un goitre","Une tumeur de la paroi de l'œsophage","Un corps étranger, avalé par erreur","Une inflammation œsophagienne, par reflux acide"],"r":0,"e":"Les causes intrinsèques sont l'inflammation, les membranes et anneaux étroits et les tumeurs. Une masse médiastinale en est aussi une cause ; le goitre est une thyroïde augmentée de volume.","s":4},{"q":"Quelle maladie neuromusculaire peut causer une dysphagie motrice ?","o":["La myasthénie grave, la poliomyélite","L'achalasie, par défaut du sphincter inférieur","La sclérodermie, avec une fibrose","Le spasme œsophagien diffus"],"r":0,"e":"On retient aussi la polymyosite et la dermatomyosite. La sclérose latérale amyotrophique en fait aussi partie.","s":4},{"q":"Dans quelle proportion des cas l'histoire clinique oriente-t-elle le diagnostic de dysphagie ?","o":["Environ 80 %","Environ 30 %","Environ 50 %","Environ 95 %"],"r":0,"e":"La vidéofluoroscopie de la déglutition permet d'évaluer la suspicion.","s":4},{"q":"Que suggère une difficulté portant seulement sur les solides ?","o":["Une dysphagie mécanique","Une dysphagie motrice","Un globus pharyngé","Une achalasie"],"r":0,"e":"Une difficulté avec les solides ET les liquides oriente vers une dysphagie motrice.","s":4},{"q":"Où l'aliment reste-t-il bloqué dans la dysphagie oropharyngée ?","o":["Dans la zone sus-sternale, avec un risque d'aspiration","Dans la zone sternale moyenne, derrière le sternum","Dans la zone sternale inférieure, près du cardia de l'estomac","Dans l'estomac, au niveau du fundus"],"r":0,"e":"Il existe une difficulté à initier la déglutition. La régurgitation peut aussi être nasopharyngée.","s":4},{"q":"Quelle proportion des douleurs thoraciques non cardiaques est due à une dysfonction œsophagienne ?","o":["30 %","10 %","50 %","80 %"],"r":0,"e":"C'est un point important du diagnostic différentiel.","s":4},{"q":"Qu'est-ce que l'achalasie ?","o":["Une obstruction motrice, par le sphincter inférieur","Un spasme œsophagien diffus, douloureux","Une atrophie du muscle lisse, avec fibrose","Une inflammation à éosinophiles, d'origine allergique"],"r":0,"e":"La sclérodermie rend l'œsophage apéristaltique par atrophie et fibrose. Il s'agit du sphincter œsophagien inférieur.","s":4},{"q":"Quelle bactérie est la principale cause de gastrite ?","o":["Helicobacter pylori","Escherichia coli","Streptococcus pneumoniae","Staphylococcus aureus"],"r":0,"e":"Non traitée, elle peut mener à des ulcères puis à un cancer de l'estomac.","s":4},{"q":"Comment les analgésiques favorisent-ils la gastrite ?","o":["Ils réduisent la substance qui protège l'estomac","Ils augmentent la sécrétion de mucus, qui irrite la paroi","Ils diminuent l'acidité gastrique","Ils détruisent la bactérie H. pylori"],"r":0,"e":"L'alcool irrite quant à lui le revêtement stomacal. C'est leur usage excessif qui compromet cette protection.","s":4},{"q":"Que signifie une hématémèse ?","o":["Un vomissement de sang, ou en marc de café","Des selles noires, poisseuses et nauséabondes","Une douleur épigastrique, à jeun","Une perte d'appétit, prolongée"],"r":0,"e":"Les selles noires correspondent au méléna.","s":4},{"q":"Comment se comporte la douleur de l'ulcère peptique ?","o":["Calmée par les repas, aggravée à jeun ou la nuit","Aggravée par les repas, surtout s'ils sont gras ou épicés","Constante, sans aucun lien avec les repas","Absente la nuit, présente le jour"],"r":0,"e":"Elle est localisée dans la région supérieure et médiane de l'abdomen.","s":4},{"q":"Quelle conséquence a la gastrectomie sur l'absorption ?","o":["La cobalamine n'est plus absorbée","Le fer n'est plus absorbé du tout","L'eau n'est plus absorbée du tout","Les électrolytes ne sont plus absorbés"],"r":0,"e":"Un régime spécial, permanent ou temporaire, est nécessaire. La cobalamine est la vitamine B12.","s":4},{"q":"Le haut-le-cœur se définit comme :","o":["L'expulsion forcée du contenu gastrique, par la bouche","Une respiration rythmée forcée, avant de vomir","L'expulsion douce du contenu gastrique","Le désir intermittent de vomir, sans effort"],"r":1,"e":"La nausée est le désir intermittent de vomir, et la régurgitation une expulsion douce sans nausée ni contraction diaphragmatique.","s":4},{"q":"Les sels biliaires sont absorbés au niveau :","o":["De l'estomac","De l'intestin grêle proximal","De l'intestin grêle distal","Du côlon"],"r":2,"e":"L'intestin grêle distal absorbe vitamine B12, sels biliaires et eau ; le côlon absorbe eau et électrolytes.","s":4},{"q":"La motilité intestinale est contrôlée par des mécanismes :","o":["Neuraux, myogéniques et hormonaux","Uniquement neuraux, par le vague","Uniquement hormonaux, par la gastrine","Purement mécaniques, par la gravité et la pression"],"r":0,"e":"Elle propulse le contenu depuis l'estomac jusqu'à la séparation des composants, pour faciliter l'absorption.","s":4},{"q":"Le mal des transports provoque des vomissements par la voie :","o":["Du nerf vague","Du système vestibulaire","De la zone gâchette chémoréceptrice","Du système nerveux central"],"r":1,"e":"Les médicaments et toxines activent la ZGC, tandis que toxines, infections et obstructions digestives stimulent le nerf vague.","s":4},{"q":"Les opiacés et la chimiothérapie provoquent des vomissements en agissant :","o":["Sur le nerf vague, depuis l'estomac","Sur la zone gâchette chémoréceptrice","Sur le système vestibulaire","Sur la paroi gastrique, irritée"],"r":1,"e":"La ZGC, située dans le quatrième ventricule, détecte les substances nocives circulantes et alerte le centre du vomissement.","s":4},{"q":"La première étape du mécanisme physiopathologique du vomissement est :","o":["La fermeture de la glotte","Le relâchement du fundus et du sphincter","La hausse de la pression intrathoracique","L'expulsion du contenu gastrique, par la bouche"],"r":1,"e":"Suivent l'augmentation des pressions intra-abdominale puis intrathoracique, l'élévation du palais mou avec fermeture de la glotte, et enfin l'expulsion. Il s'agit du sphincter œsophagien inférieur.","s":4},{"q":"Un vomissement survenant à la suite du repas oriente vers :","o":["Une obstruction intestinale, haute","Une hypertension intracrânienne, avec céphalées","Un ulcère, ou une cause psychogène","Une labyrinthite, avec des vertiges"],"r":2,"e":"L'émèse fécaloïde oriente vers une obstruction intestinale et le vomissement en jet vers une hypertension intracrânienne.","s":4},{"q":"Parmi les causes intrapéritonéales de vomissement, le cours cite :","o":["Obstructions, infections entériques, inflammations","La labyrinthite, avec des vertiges","Les tumeurs cérébrales, l'hypertension crânienne","L'anorexie mentale, la boulimie"],"r":0,"e":"Labyrinthite, troubles intracérébraux et maladies psychiatriques relèvent, eux, des causes extrapéritonéales. La cholécystite et la pancréatite sont des exemples d'inflammation.","s":4},{"q":"Parmi les complications des vomissements figurent :","o":["Rupture œsophagienne, déshydratation, dénutrition","Hypertension artérielle, palpitations, céphalées intenses","Anémie ferriprive, pâleur, fatigue","Lithiase rénale, coliques néphrétiques"],"r":0,"e":"La pneumonie d'aspiration en est la complication respiratoire ; le traitement vise la cause, l'efficacité des antiémétiques dépendant de l'étiologie. Les érosions dentaires en font aussi partie.","s":4},{"q":"Quelle proportion d'Américains rapporte des brûlures d'estomac une fois par mois ?","o":["7 %","15 %","40 %","60 %"],"r":2,"e":"7 % en rapportent quotidiennement, et la maladie ulcéreuse peptique liée à H. pylori ou aux anti-inflammatoires représente 15 % des cas.","s":4},{"q":"Parmi les mécanismes physiopathologiques de l'indigestion, le cours cite :","o":["La hernie hiatale et le sphincter inférieur qui lâche","Une hypersécrétion du pancréas exocrine","Un déficit en sels biliaires, par cholestase","Une atrophie gastrique, avec une muqueuse amincie et fragile"],"r":0,"e":"S'y ajoutent l'augmentation du contenu gastrique, la position couchée et l'augmentation de la pression sur l'estomac (vêtements serrés, obésité, grossesse). Le tonus du sphincter œsophagien inférieur se perd par intermittence.","s":4},{"q":"Parmi les signes d'alarme devant une indigestion, le cours cite :","o":["Dysphagie, odynophagie, amaigrissement, saignement","Ballonnements, flatulences, gargouillements après les repas","Éructations, après les boissons gazeuses","Halitose isolée, au réveil, sans autre signe"],"r":0,"e":"Les vomissements récurrents, les masses palpables et les adénopathies complètent cette liste imposant une exploration.","s":4},{"q":"Le traitement de première intention de l'indigestion comprend :","o":["Une antibiothérapie systématique, sur dix jours","Perte de poids, tête du lit surélevée, arrêt du tabac","Une chirurgie anti-reflux, d'emblée","Une corticothérapie, à forte dose"],"r":1,"e":"S'y ajoutent l'évitement des repas copieux, du chocolat, des jus d'agrumes et des anti-inflammatoires, ainsi que les antiacides. On évite aussi la caféine et les aliments gras.","s":4},{"q":"Le terme adénopathie désigne :","o":["Une inflammation de l'œsophage","Un ganglion lymphatique augmenté de volume","Une masse abdominale palpable, de cause inconnue","Un épaississement de la paroi gastrique"],"r":1,"e":"C'est l'un des signes d'alarme imposant une exploration devant une indigestion.","s":4},{"q":"Une perte de poids involontaire significative chez un individu sain évoque :","o":["Une variation alimentaire banale","Une maladie systémique sous-jacente","Une déshydratation isolée","Un effet de l'âge"],"r":1,"e":"Les fluctuations rapides en quelques jours traduisent plutôt des mouvements de liquides ; les changements à long terme, une perte de masse tissulaire.","s":4},{"q":"Chez le sujet jeune, les causes de perte de poids citées sont :","o":["Diabète, hyperthyroïdie, anorexie mentale, infections","Dépression, cancer, maladies gastro-intestinales chroniques","Troubles cardiaques, insuffisance cardiaque","Insuffisance rénale chronique, dialyse"],"r":0,"e":"Dépression, cancer et maladie gastro-intestinale prédominent, eux, chez le sujet âgé. Parmi les infections, le VIH en particulier.","s":4},{"q":"L'odynophagie se définit comme :","o":["Une difficulté à faire progresser le bol","Une douleur ressentie à la déglutition","Une sensation de corps étranger, sans dysphagie","Un reflux acide, après les repas"],"r":1,"e":"Le patient perçoit alors la difficulté de progression du bol alimentaire, ce qui la distingue du globus pharyngé.","s":4},{"q":"Une dysphagie portant sur les solides ET les liquides oriente vers :","o":["Une cause mécanique","Une cause motrice","Un globus pharyngé","Un reflux"],"r":1,"e":"Une difficulté portant seulement sur les solides oriente vers une cause mécanique ; l'histoire clinique oriente le diagnostic dans environ 80 % des cas.","s":4},{"q":"Le globus pharyngé se définit comme :","o":["Une douleur vive et brûlante, à chaque déglutition","Une sensation de boule, sans gêne à avaler","Un blocage alimentaire, au niveau du sternum","Un spasme œsophagien, douloureux"],"r":1,"e":"Il se distingue de la dysphagie vraie, où le bol alimentaire est réellement gêné dans sa progression, et de l'odynophagie, qui est douloureuse.","s":4},{"q":"La gastrectomie empêche l'absorption de la vitamine B12 parce que l'estomac :","o":["Absorbe directement cette vitamine","Produit le facteur intrinsèque nécessaire","Stocke cette vitamine, en réserve","Neutralise cette vitamine, par l'acide"],"r":1,"e":"L'absorption elle-même a lieu dans l'intestin grêle distal, mais elle est impossible sans le facteur intrinsèque d'origine gastrique.","s":4},{"q":"Combien de lobes possède le foie ?","o":["Quatre, dont le carré et le caudé","Deux, un droit et un gauche","Trois, dont un lobe médian","Cinq, dont deux lobes caudés"],"r":0,"e":"Le lobe droit est le plus grand ; le ligament falciforme unit les lobes gauche et droit. Les quatre lobes : droit, gauche, carré et caudé.","s":5},{"q":"Où se situe le foie ?","o":["Dans l'hypochondre droit, sous le diaphragme","Dans l'hypochondre gauche, sous la rate","Dans l'épigastre seul, devant l'estomac","Dans le flanc gauche, en arrière du côlon descendant"],"r":0,"e":"Le bord inférieur de son lobe droit est en contact avec le gros intestin. Il est au-dessus du pancréas et en avant de la vésicule biliaire.","s":5},{"q":"Quelle enzyme la bile active-t-elle ?","o":["La lipase","L'amylase","La pepsine","La trypsine"],"r":0,"e":"La bile est une sécrétion digestive visqueuse vert-jaune produite par le foie.","s":5},{"q":"Sous quelle forme le foie stocke-t-il le glucose ?","o":["Sous forme de glycogène","Sous forme de triglycérides","Sous forme d'albumine","Sous forme de bilirubine"],"r":0,"e":"Il est reconverti en glucose et libéré dans la circulation en cas de besoin.","s":5},{"q":"Dans quels tissus l'AST est-elle présente en fortes concentrations ?","o":["Foie, muscles, cœur, reins, pancréas, hématies","Foie seulement, dans le cytoplasme des hépatocytes","Cœur seulement, dans le myocarde","Pancréas seulement, dans les acini"],"r":0,"e":"C'est pourquoi ce marqueur ne permet pas d'identifier l'origine de l'élévation. Les muscles sont squelettiques et cardiaque.","s":5},{"q":"Pourquoi l'ALT est-elle plus spécifique du foie ?","o":["Elle n'abonde que dans le cytoplasme du foie","Elle est surtout mitochondriale","Elle est absente de tous les muscles","Elle est produite par la bile, puis réabsorbée"],"r":0,"e":"Elle peut néanmoins être augmentée avec l'AST dans les myopathies sévères.","s":5},{"q":"Quelles sont les valeurs de référence de l'ALT ?","o":["Jusqu'à 31 U/L chez la femme, 41 U/L chez l'homme","Jusqu'à 31 U/L chez la femme, 37 U/L chez l'homme","De 24 à 480 U/L, quel que soit le sexe","De 8 à 41 U/L, chez la femme comme chez l'homme adulte"],"r":0,"e":"Pour l'AST : jusqu'à 31 U/L (femmes) et 37 U/L (hommes).","s":5},{"q":"Quel profil enzymatique évoque une hépatite alcoolique ?","o":["Une AST au moins double de l'ALT, sous 300 U/L","Une ALT au moins double de l'AST, au-dessus de 300 U/L","Les deux enzymes au-dessus de 1 000 U/L","Une AST isolée, à 1 500 U/L, ALT normale"],"r":0,"e":"La lésion mitochondriale est plus importante dans l'hépatite alcoolique. La lésion mitochondriale y est plus importante.","s":5},{"q":"Que suggèrent des transaminases au-dessus de 1 000 U/L ?","o":["Une hépatite aiguë, virale ou toxique","Une hépatite alcoolique, sévère","Une hépatite chronique, ancienne","Une stéatose simple, liée au surpoids ancien"],"r":0,"e":"Dans l'hépatite chronique, les élévations sont petites. L'origine toxique correspond à l'ingestion de drogues.","s":5},{"q":"Quel rapport suggère une hépatite virale pour des aminotransférases > 5 fois la normale ?","o":["Un rapport ALT/LDH supérieur à 1,5","Un rapport AST/ALT supérieur à 2","Un rapport LDH/ALT supérieur à 2","Un rapport GGT/PAL supérieur à 1"],"r":0,"e":"La LDH est utile pour différencier hépatite aiguë virale et lésion ischémique ; ses valeurs normales sont 24-480 U/L.","s":5},{"q":"Qu'est-ce que la phosphatase alcaline ?","o":["Des enzymes présentes dans presque tous les tissus","Une enzyme unique, produite seulement par le foie","Une protéine de transport, qui circule dans le plasma","Un facteur de coagulation, synthétisé par les hépatocytes"],"r":0,"e":"Son augmentation hépatique traduit une obstruction biliaire.","s":5},{"q":"Quelles isoenzymes de la phosphatase alcaline peut-on différencier ?","o":["Hépatique, osseuse et intestinale","Cardiaque, rénale et musculaire","Pancréatique et prostatique","Érythrocytaire et plaquettaire"],"r":0,"e":"C'est utile en cas d'élévation sans signes de maladie hépatobiliaire.","s":5},{"q":"Que suggèrent de grandes élévations de la GGT ?","o":["Un cancer du foie ou une obstruction biliaire","Une myopathie, avec des CPK élevées","Une insuffisance rénale, chronique","Une anémie hémolytique, avec un ictère à bilirubine libre"],"r":0,"e":"C'est un marqueur très sensible de maladie hépatique. Le cancer peut être primaire ou secondaire.","s":5},{"q":"Quelle proportion de personnes a une GGT au-dessus des normes sans maladie ?","o":["Environ 15 %","Environ 1 %","Environ 50 %","Environ 30 %"],"r":0,"e":"Cela peut concerner des valeurs supérieures à 100 U/L.","s":5},{"q":"De quoi la bilirubine est-elle le produit final ?","o":["De la destruction de l'hème de l'hémoglobine","De la dégradation des protéines alimentaires","De la synthèse hépatique du cholestérol et des graisses","Du métabolisme du glycogène, dans le foie"],"r":0,"e":"C'est le principal composant des pigments biliaires. D'autres hémoprotéines y contribuent aussi.","s":5},{"q":"Que traduit une augmentation de la bilirubine INDIRECTE ?","o":["Plus d'hème dégradé, ou une conjugaison déficiente","Un défaut d'élimination par la bile","Une obstruction biliaire pure, par un calcul","Une hypoalbuminémie, par dénutrition ou insuffisance du foie"],"r":0,"e":"La bilirubine indirecte est la forme non conjuguée. La conjugaison se fait dans le foie.","s":5},{"q":"Que traduit principalement une augmentation de la bilirubine DIRECTE ?","o":["Un défaut d'élimination par la bile","Une hémolyse, par destruction des hématies","Un défaut de conjugaison, dans le foie","Une dénutrition, avec une perte de poids importante"],"r":0,"e":"L'augmentation des deux évoque une obstruction du flux biliaire ou une lésion hépatocytaire intense.","s":5},{"q":"De quelle vitamine dépend la synthèse de la majorité des facteurs de coagulation ?","o":["La vitamine K","La vitamine B12","La vitamine D","La vitamine C"],"r":0,"e":"Son absorption dépend de la présence de sels biliaires, diminués dans la cirrhose.","s":5},{"q":"Quelles sont les valeurs normales du temps de prothrombine ?","o":["11,1 à 13,2 secondes","5 à 10 secondes","20 à 30 secondes","30 à 40 secondes"],"r":0,"e":"C'est une méthode simple d'évaluation de la fonction de synthèse du foie.","s":5},{"q":"Quel organe produit l'albumine ?","o":["Le foie, et lui seul","Le rein, et lui seul","La rate, et elle seule","La moelle osseuse, et elle seule"],"r":0,"e":"L'hypoalbuminémie traduit une maladie du foie, une carence nutritionnelle ou une destruction accrue.","s":5},{"q":"À partir de quel taux de bilirubine l'ictère apparaît-il ?","o":["Supérieur à 2 mg/dl","Supérieur à 0,5 mg/dl","Supérieur à 10 mg/dl","Supérieur à 5 mg/dl"],"r":0,"e":"Il colore la peau, les muqueuses et les sclérotiques.","s":5},{"q":"Quel traitement est indiqué pour un ictère néonatal modéré ?","o":["La photothérapie, qui dégrade la bilirubine","L'hémodialyse, en service de réanimation","Aucun traitement, la régression étant toujours spontanée","La transfusion, de façon systématique"],"r":0,"e":"Les formes graves relèvent de l'hémodialyse. La bilirubine en excès est dégradée en produits résiduels.","s":5},{"q":"Quels virus se transmettent par voie féco-orale ?","o":["Les virus A et E","Les virus B, C et D","Le virus B uniquement","Le virus C uniquement"],"r":0,"e":"Les virus B, C et D se transmettent par voie sanguine.","s":5},{"q":"Quels virus se transmettent de la mère à l'enfant pendant la grossesse, l'accouchement et l'allaitement ?","o":["Les virus B, C et D","Les virus A et E, par voie fécale","Le virus A, uniquement","Aucun virus, en pratique"],"r":0,"e":"Ils se transmettent aussi par les rapports non protégés et le partage d'objets perforants.","s":5},{"q":"Chez qui la stéatohépatite est-elle commune ?","o":["Chez l'obèse, le diabétique, l'alcoolique","Chez le sportif, en endurance prolongée","Chez l'enfant, avant la puberté","Chez le sujet dénutri, très âgé"],"r":0,"e":"La graisse dans le foie peut provoquer une hépatite.","s":5},{"q":"Quelle est la séquence de la dysfonction graisseuse hépatique ?","o":["Stéatose → stéatohépatite → cirrhose","Cirrhose → stéatose → stéatohépatite","Stéatohépatite → stéatose → cirrhose","Fibrose → stéatose → hépatite → cirrhose"],"r":0,"e":"Les facteurs de risque de stéatose sont l'obésité, le diabète et l'âge > 45-50 ans. La stéatohépatite associe stéatose et mort hépatocytaire ; la cirrhose, nodules de régénération et fibrose.","s":5},{"q":"Comment définit-on la stéatohépatite non alcoolique ?","o":["Une lésion identique à la forme alcoolique, sans alcool","Une stéatose sans inflammation, réversible","Une cirrhose débutante, chez un buveur modéré et régulier","Une hépatite virale, de type B ou C"],"r":0,"e":"Elle est fréquente chez l'obèse et le diabétique. La lésion est histologiquement indiscernable de la forme alcoolique.","s":5},{"q":"Quelles sont les causes principales de cirrhose ?","o":["L'alcool et les hépatites virales chroniques","L'hémochromatose et la maladie de Wilson","La mucoviscidose et les surcharges héréditaires","Le déficit en alpha-1 antitrypsine"],"r":0,"e":"Les autres causes sont plus rares.","s":5},{"q":"Quelle substance s'accumule dans la maladie de Wilson ?","o":["Le cuivre, surtout dans le cerveau et le foie","Le fer, surtout dans le foie et le pancréas","Le calcium, surtout dans les reins et les artères","Le zinc, surtout dans la peau et les ongles"],"r":0,"e":"L'hémochromatose correspond à une absorption exagérée de fer.","s":5},{"q":"Quelles sont les conséquences de l'hypertension portale ?","o":["Hémorragies digestives, splénomégalie, ascite","Encéphalopathie, ictère, angiomes stellaires","Manque de protéines, dénutrition","Altération des hormones sexuelles, gynécomastie"],"r":0,"e":"Les quatre dernières propositions relèvent de l'insuffisance hépatique. Les shunts porto-systémiques en font aussi partie.","s":5},{"q":"Les lobes gauche et droit du foie sont unis par :","o":["Le ligament rond","Le ligament falciforme","Le canal hépatique commun","La capsule de Glisson"],"r":1,"e":"Le foie compte quatre lobes : droit (le plus grand), gauche, carré et caudé.","s":5},{"q":"Les voies biliaires comprennent :","o":["Les canaux hépatiques, le canal commun, le cholédoque","Le cholédoque seul, jusqu'à l'ampoule de Vater et au duodénum","Le canal thoracique, jusqu'à la veine subclavière","Les sinusoïdes hépatiques, et la veine porte"],"r":0,"e":"La vésicule biliaire est, elle, la poche qui contient la bile, sécrétion visqueuse vert-jaune produite par le foie. Les canaux hépatiques droit et gauche forment le canal hépatique commun ; le canal pancréatique en fait aussi partie.","s":5},{"q":"Parmi les marqueurs de LÉSION hépatique, le cours classe :","o":["L'AST, la γ-GT, la phosphatase alcaline","La bilirubine totale, l'albumine","Le temps de prothrombine, le facteur V, l'INR","Le TCA, le fibrinogène plasmatique"],"r":0,"e":"Bilirubine totale, temps de prothrombine, TCA et albumine sont, eux, des examens de FONCTION hépatique.","s":5},{"q":"L'AST ne permet pas d'identifier l'origine d'une élévation car elle est présente :","o":["Dans le foie seulement, en très grande quantité","Dans le foie, les muscles, les reins, le pancréas","Dans les muscles seulement, squelettiques et cardiaque","Dans le seul pancréas, exocrine et endocrine"],"r":1,"e":"L'ALT, concentrée uniquement dans le cytoplasme du foie, est donc plus spécifique d'une lésion hépatique. Elle est aussi présente dans les érythrocytes ; les muscles sont squelettiques et cardiaque.","s":5},{"q":"Les valeurs de référence de l'AST sont :","o":["Jusqu'à 31 U/L chez la femme, 37 U/L chez l'homme","Jusqu'à 41 U/L chez la femme, 31 U/L chez l'homme adulte","De 24 à 480 U/L, quel que soit le sexe","De 8 à 41 U/L, quel que soit le sexe"],"r":0,"e":"Pour l'ALT, les valeurs normales vont jusqu'à 31 U/L chez la femme et 41 U/L chez l'homme.","s":5},{"q":"De petites élévations des deux transaminases, ou de l'ALT seule, se rencontrent dans :","o":["L'hépatite alcoolique, sévère","L'hépatite chronique, C ou non alcoolique","L'hépatite aiguë virale, au début de l'ictère","L'ischémie hépatique, après un choc"],"r":1,"e":"L'hépatite alcoolique donne une AST au moins double de l'ALT, les deux restant généralement sous 300 U/L.","s":5},{"q":"La LDH est utile pour :","o":["Distinguer hépatite virale aiguë et ischémie","Doser la bilirubine conjuguée","Évaluer la synthèse des protéines","Mesurer le degré d'obstruction des voies biliaires"],"r":0,"e":"Pour des aminotransférases élevées à plus de 5 fois la limite supérieure, un rapport ALT/LDH supérieur à 1,5 suggère une hépatite virale ; ses valeurs normales sont de 24 à 480 U/L.","s":5},{"q":"La phosphatase alcaline est :","o":["Une enzyme unique, spécifique du foie et des voies biliaires","Des enzymes présentes dans presque tous les tissus","Une protéine de transport, plasmatique","Un pigment biliaire, issu de l'hème"],"r":1,"e":"Son élévation d'origine hépatique traduit une obstruction biliaire : les sels biliaires la solubilisent et l'obstruction favorise sa régurgitation vers le sang.","s":5},{"q":"En cas d'élévation de la phosphatase alcaline sans signe de maladie hépatobiliaire, on peut :","o":["Séparer les isoenzymes du foie, de l'os et de l'intestin","Conclure à une lithiase biliaire","Doser la GGT seule, sans autre examen","Arrêter les investigations, l'élévation étant toujours bénigne"],"r":0,"e":"Ses valeurs normales varient par ailleurs selon l'âge, ce qui complique l'interprétation chez l'enfant et l'adolescent.","s":5},{"q":"La GGT est décrite dans le cours comme :","o":["Un marqueur très sensible de maladie du foie","Un marqueur très spécifique de l'alcool","Un examen de la fonction de synthèse hépatique","Un pigment biliaire, issu de l'hème"],"r":0,"e":"Environ 15 % des personnes ont une GGT au-dessus des valeurs normales sans aucune maladie, parfois au-delà de 100 U/L.","s":5},{"q":"Les valeurs normales de la GGT sont :","o":["8 à 41 U/L chez la femme, 12 à 73 U/L chez l'homme","24 à 480 U/L, chez l'adulte des deux sexes","Jusqu'à 31 U/L chez la femme, 37 chez l'homme","11,1 à 13,2 U/L, quel que soit le sexe"],"r":0,"e":"Des élévations peuvent aussi être liées à la consommation d'alcool et à certains médicaments, indépendamment de toute maladie du foie.","s":5},{"q":"La bilirubine indirecte devient bilirubine directe par :","o":["Oxydation","Conjugaison","Hydrolyse","Réduction"],"r":1,"e":"La bilirubine indirecte, non conjuguée, est produite en premier lors de la dégradation de l'hème.","s":5},{"q":"Une augmentation simultanée des deux bilirubines peut résulter :","o":["D'une hémolyse isolée, sans atteinte du foie","D'une obstruction biliaire, ou d'une lésion des hépatocytes","D'un déficit isolé de conjugaison, d'origine génétique ou acquise","D'une carence en vitamine K, par malabsorption"],"r":1,"e":"Une élévation isolée de l'indirecte traduit une dégradation accrue de l'hème ou un déficit de conjugaison. En cas d'obstruction, la directe prédomine ; la lésion des hépatocytes doit être intense.","s":5},{"q":"La synthèse des facteurs de coagulation par le foie dépend de :","o":["La vitamine K, d'origine alimentaire","La vitamine C, d'origine alimentaire","La vitamine D, produite par la peau au soleil","Le fer, absorbé dans le duodénum"],"r":0,"e":"Son absorption dépendant des sels biliaires, et la cirrhose diminuant leur production, un déficit est attendu chez le cirrhotique — supplémentable par voie parentérale.","s":5},{"q":"Les valeurs normales du temps de prothrombine sont :","o":["11,1 à 13,2 secondes","24 à 48 secondes","8 à 41 secondes","2 à 4 minutes"],"r":0,"e":"Son allongement chez le cirrhotique traduit à la fois le déficit en vitamine K et la perte de fonction des hépatocytes.","s":5},{"q":"L'albumine est particulière parmi les protéines circulantes car :","o":["Le foie en est le seul organe producteur","Elle est produite par le rein seul","Sa synthèse dépend de la vitamine K","C'est un pigment biliaire, de l'hème"],"r":0,"e":"L'hypoalbuminémie traduit une maladie du foie, une dénutrition protéique ou une augmentation de sa destruction.","s":5},{"q":"L'ictère apparaît pour une bilirubinémie supérieure à :","o":["0,5 mg/dl","1 mg/dl","2 mg/dl","10 mg/dl"],"r":2,"e":"Il colore la peau, les muqueuses et les sclérotiques ; on parle alors d'hyperbilirubinémie.","s":5},{"q":"L'ictère physiologique du nouveau-né est lié :","o":["À une hémolyse pathologique, d'origine immune","À l'immaturité du système hépatique","À une obstruction des voies biliaires","À une infection, bactérienne ou virale"],"r":1,"e":"Il régresse en quelques jours, chez l'enfant à terme comme chez le prématuré.","s":5},{"q":"Parmi les examens complémentaires d'exploration du foie, le cours cite :","o":["La biopsie, l'échographie, le scanner, l'élastographie","L'échographie seule, sans autre examen","La scintigraphie osseuse, la densitométrie, la radiographie","L'endoscopie haute, la coloscopie, la capsule"],"r":0,"e":"Ils complètent le bilan biologique lorsque celui-ci ne suffit pas à trancher entre lésion, obstruction et insuffisance. L'IRM fait aussi partie de ces examens ; le scanner correspond à la TDM.","s":5},{"q":"Les deux grands mécanismes symptomatiques de la cirrhose sont :","o":["L'hypertension portale et l'insuffisance hépatique","L'ictère et l'ascite, par rétention d'eau et de bilirubine","L'hémolyse et la dénutrition protéique","L'obstruction biliaire et l'infection"],"r":0,"e":"La cirrhose correspond à la substitution du tissu hépatique normal par des nodules et du tissu fibreux, principalement du fait de l'alcool et des hépatites virales et chroniques.","s":5},{"q":"Quelles deux pathologies regroupe le terme « maladie inflammatoire intestinale » ?","o":["La rectocolite hémorragique et la maladie de Crohn","La diverticulite et l'occlusion intestinale","Les polypes et le cancer colorectal","La gastrite chronique et l'ulcère peptique du duodénum"],"r":0,"e":"C'est une inflammation chronique de la muqueuse intestinale. La rectocolite est dite ulcéro-hémorragique.","s":6},{"q":"Quelle caractéristique distingue l'inflammation de la maladie de Crohn ?","o":["Transmurale, segmentaire, asymétrique","Limitée à la muqueuse, superficielle","Toujours continue, du rectum vers le haut","Limitée au rectum, sans extension"],"r":0,"e":"Elle peut affecter n'importe quelle partie du tube digestif, de la bouche à l'anus.","s":6},{"q":"Quelles zones sont le plus souvent affectées par la maladie de Crohn ?","o":["L'iléon terminal et le côlon droit","Le rectum seul, sur quelques centimètres","L'estomac, surtout la région de l'antre","L'œsophage, surtout dans son tiers inférieur"],"r":0,"e":"L'inflammation y est segmentaire et asymétrique. L'iléon terminal est la portion distale de l'intestin grêle.","s":6},{"q":"À quel âge la maladie de Crohn se développe-t-elle le plus souvent ?","o":["Surtout avant 30 ans, mais à tout âge","Uniquement après 60 ans, chez l'homme","Uniquement dans l'enfance, avant 10 ans","Uniquement entre 40 et 50 ans, chez la femme"],"r":0,"e":"Les tranches citées sont 20-40 ans avec un pic à 50-60 ans.","s":6},{"q":"Quel argument épidémiologique plaide en faveur du rôle de l'environnement dans la maladie de Crohn ?","o":["Sa hausse chez les enfants et petits-enfants d'immigrés","Sa nette prédominance masculine, à tout âge","L'absence de cas familiaux, même chez les jumeaux","La stabilité de son incidence dans le temps"],"r":0,"e":"Elle est aussi plus fréquente dans les pays industrialisés et les zones urbaines. L'incidence augmente aux 1ʳᵉ et 2ᵉ générations après l'immigration.","s":6},{"q":"Quel est le risque de maladie de Crohn chez les apparentés d'un individu atteint ?","o":["12 %","1 %","50 %","30 %"],"r":0,"e":"Certains gènes augmentent le risque de développement de la maladie.","s":6},{"q":"Quelle hypothèse étiologique implique un agent infectieux dans la maladie de Crohn ?","o":["Un microbe déclencherait une réponse immune qui persiste","Une infection chronique, jamais éliminée par l'hôte infecté","Une carence alimentaire, en vitamines","Un traumatisme abdominal, ancien"],"r":0,"e":"L'étiologie reste inconnue. La réponse persiste après la disparition du virus ou de la bactérie.","s":6},{"q":"Quel rôle le stress joue-t-il dans la maladie de Crohn ?","o":["Il peut aggraver les symptômes","Il guérit la maladie, à terme","Il n'a aucun effet connu","Il la provoque à coup sûr"],"r":0,"e":"Les habitudes alimentaires et les facteurs émotionnels peuvent aussi contribuer à son apparition.","s":6},{"q":"Quelles sont les manifestations les plus communes de la maladie de Crohn ?","o":["Diarrhée, déshydratation, coliques, amaigrissement","Constipation, ballonnement isolés","Ictère, prurit, urines foncées, selles décolorées, fièvre","Fièvre isolée, sans autre signe"],"r":0,"e":"Les lésions périanales (fissures, fistules) et abcès sont des manifestations précoces. La douleur abdominale est de type colique.","s":6},{"q":"Quelles manifestations précoces peuvent révéler une maladie de Crohn ?","o":["Des fissures, des fistules ou des abcès périanaux","Une hématémèse, avec des vomissements de sang rouge","Une dysphagie, aux solides puis aux liquides","Une ascite, avec une prise de poids"],"r":0,"e":"La présentation dépend du segment du tube digestif affecté.","s":6},{"q":"Quel examen endoscopique est spécifiquement cité pour explorer l'intestin grêle dans Crohn ?","o":["L'entéroscopie par capsule","La rectosigmoïdoscopie","La gastroscopie seule","L'échoendoscopie"],"r":0,"e":"On utilise aussi l'endoscopie digestive haute, la coloscopie et l'imagerie (entéro-TDM, entéro-IRM).","s":6},{"q":"Comment se forme une fistule dans la maladie de Crohn ?","o":["Par un ulcère qui traverse la paroi intestinale","Par une compression externe de l'intestin","Par une thrombose des vaisseaux de la paroi","Par un traumatisme abdominal, avec une plaie de l'intestin"],"r":0,"e":"L'occlusion intestinale résulte quant à elle de l'épaississement et des cicatrices. La communication créée est anormale.","s":6},{"q":"Quelle complication extra-digestive de la maladie de Crohn est citée ?","o":["L'ostéoporose, l'atteinte des yeux et des articulations","L'insuffisance rénale aiguë, par déshydratation","La cardiomyopathie dilatée, avec insuffisance cardiaque","L'asthme, avec une hyperréactivité bronchique sévère et précoce"],"r":0,"e":"On retient aussi les altérations neurologiques et l'augmentation du risque de cancer du côlon. La peau, le foie et les voies biliaires peuvent aussi s'enflammer.","s":6},{"q":"Existe-t-il un traitement curatif de la maladie de Crohn ?","o":["Non, on réduit les symptômes et on induit des rémissions","Oui, par une antibiothérapie prolongée","Oui, par l'exérèse chirurgicale de tout le segment atteint","Oui, par un régime sans lactose"],"r":0,"e":"La chirurgie est indiquée en cas d'occlusion, de fistules ou d'épisodes aigus graves.","s":6},{"q":"Quel régime est recommandé pendant les périodes de diarrhée ?","o":["Pauvre en fibres et sans lactose","Riche en fibres, crues et cuites","Riche en protéines, animales","Un jeûne complet, jusqu'à l'arrêt de la diarrhée"],"r":0,"e":"En dehors de ces périodes, l'alimentation est normale et sans restrictions.","s":6},{"q":"Quel est le symptôme le plus caractéristique de la rectocolite hémorragique ?","o":["Une diarrhée avec sang rouge vif","Une constipation opiniâtre","Un ictère","Une dysphagie"],"r":0,"e":"On retrouve aussi une douleur de type colique et une urgence à aller à la selle.","s":6},{"q":"Quelle étendue la rectocolite hémorragique peut-elle atteindre ?","o":["Du rectum seul jusqu'à tout le côlon","Le rectum seul, sans extension","Tout le tube digestif, de la bouche à l'anus","L'intestin grêle seul, sans le côlon"],"r":0,"e":"Elle implique toute la paroi de l'organe. L'atteinte peut se limiter à quelques centimètres du rectum.","s":6},{"q":"Que produit la muqueuse inflammée dans la rectocolite hémorragique ?","o":["Trop de mucus, avec du pus et du sang","Une sécrétion acide, très abondante","Des enzymes pancréatiques, actives","De la bile, en grande quantité"],"r":0,"e":"La muqueuse présente de petites plaies de surface qui peuvent saigner. Il s'agit du lubrifiant intestinal, produit en excès.","s":6},{"q":"Quelle complication redoutable est propre à la rectocolite hémorragique ?","o":["Le mégacôlon toxique, une dilatation soudaine","La fistule périanale, avec un abcès","L'ostéoporose, liée à une corticothérapie prolongée","La péritonite, d'origine diverticulaire"],"r":0,"e":"On retient aussi l'hémorragie grave et la perforation intestinale. La dilatation touche le côlon.","s":6},{"q":"Quelle intervention chirurgicale est citée en cas de crise aiguë grave de rectocolite hémorragique ?","o":["La colostomie","La gastrectomie","La polypectomie","La cholécystectomie"],"r":0,"e":"Il n'existe pas de médicament curatif de la rectocolite hémorragique.","s":6},{"q":"Où les diverticules sont-ils le plus communs ?","o":["Dans le gros intestin, après la quarantaine","Dans l'œsophage, au tiers supérieur, près du pharynx","Dans l'estomac, près du cardia","Dans le duodénum, près de l'ampoule"],"r":0,"e":"Ils peuvent se former dans n'importe quelle partie du tube digestif. Ils deviennent fréquents à partir de 40 ans.","s":6},{"q":"Quelle est la séquence évolutive de la maladie diverticulaire ?","o":["Diverticules → diverticulose → diverticulite","Diverticulite → diverticulose → guérison","Diverticulose → polypes adénomateux → cancer colorectal","Diverticules → adhérences → occlusion"],"r":0,"e":"L'étiologie est inconnue ; l'hypothèse principale est un régime pauvre en fibres.","s":6},{"q":"Quel mécanisme est proposé pour la formation des diverticules ?","o":["Constipation → pression colique → poches → infection","Infection primitive de la paroi → abcès → poches","Thrombose mésentérique → ischémie → poches → perforation","Auto-immunité → inflammation de la paroi → poches"],"r":0,"e":"L'hypothèse principale est un régime pauvre en fibres. Les selles dures augmentent la pression dans le côlon ; les poches retiennent des selles et s'infectent ou s'enflamment.","s":6},{"q":"Quelle complication de la maladie diverticulaire est citée ?","o":["Péritonite, occlusion, saignement, abcès, fistule","Mégacôlon toxique, avec une dilatation brutale","Cancer de l'estomac, par dégénérescence","Cirrhose, par atteinte secondaire du foie"],"r":0,"e":"Le diagnostic repose sur l'examen clinique, la numération des globules blancs et la TDM. La rupture du côlon et la sténose en font aussi partie.","s":6},{"q":"Quelle est la cause la plus fréquente d'obstruction mécanique de l'intestin grêle ?","o":["Les adhérences, après une chirurgie abdominale","Le cancer du côlon, surtout au niveau de l'angle gauche","Le fécalome, chez la personne âgée","L'iléus paralytique, après une chirurgie"],"r":0,"e":"On retient aussi les hernies, les tumeurs et les maladies inflammatoires comme la maladie de Crohn. La chirurgie peut aussi être pelvienne.","s":6},{"q":"Qu'est-ce que l'iléus paralytique ?","o":["Un défaut musculaire ou nerveux des contractions","Une obstruction mécanique, par une tumeur","Une hernie étranglée, dans l'aine","Une sténose cicatricielle, après une maladie de Crohn"],"r":0,"e":"Ses causes incluent la chirurgie, l'infection, certains médicaments et la maladie de Parkinson. Les aliments et les liquides ne progressent plus.","s":6},{"q":"Quelle est la conduite devant une occlusion intestinale COMPLÈTE ?","o":["La chirurgie","Un régime adapté","Une simple surveillance","Des antibiotiques seuls"],"r":0,"e":"Une occlusion partielle peut relever d'un régime ou d'une chirurgie.","s":6},{"q":"Quelle proportion de la population adulte présente des polypes du côlon ?","o":["30 %","10 %","50 %","5 %"],"r":0,"e":"Ce sont des lésions bénignes, retirées à la coloscopie pour éviter la dégénérescence maligne.","s":6},{"q":"Quel type de polype présente le plus grand risque d'évolution maligne ?","o":["L'adénome, avec ses cellules différenciées","Le polype hyperplasique, même s'il reste petit","Aucun, ils sont tous bénins","Les deux, avec un risque égal"],"r":0,"e":"Les polypes hyperplasiques sont petits, terminaux et à faible risque.","s":6},{"q":"À quel âge débute le dépistage du cancer du côlon en cas d'apparenté du 1ᵉʳ degré atteint avant 60 ans ?","o":["40 ans","50 ans","30 ans","60 ans"],"r":0,"e":"Le dépistage standard commence à 50 ans.","s":6},{"q":"L'inflammation de la maladie inflammatoire intestinale peut :","o":["Rester locale ou s'étendre à d'autres organes","Toucher exclusivement le côlon, sans extension","Toucher exclusivement l'intestin grêle","Se limiter au rectum, sans extension"],"r":0,"e":"Ce terme regroupe deux pathologies : la rectocolite ulcéro-hémorragique et la maladie de Crohn.","s":6},{"q":"La maladie de Crohn évolue :","o":["De façon continue, sans rémission","Par poussées, avec des rémissions sans symptôme","Par une poussée unique, sans récidive","Vers une guérison spontanée, à l'âge adulte"],"r":1,"e":"Il n'existe pas de médicament curatif : les traitements réduisent les symptômes et induisent des phases de rémission.","s":6},{"q":"La maladie de Crohn se développe surtout :","o":["Avant 30 ans, mais aussi à tout âge","Après 60 ans, de façon exclusive","Chez l'enfant de moins de 10 ans","Entre 60 et 70 ans, surtout"],"r":0,"e":"Les tranches d'âge citées sont 20 à 40 ans, avec un second pic à 50-60 ans.","s":6},{"q":"Parmi les hypothèses étiologiques de la maladie de Crohn, le microbiote intervient par :","o":["Une prolifération d'une seule bactérie pathogène","Une flore intestinale réduite ou dysfonctionnelle","Une infection parasitaire de l'intestin","Une colonisation fongique du côlon"],"r":1,"e":"L'hypothèse de l'agent déclenchant suppose, elle, qu'un virus ou une bactérie déclenche une réponse immunologique qui se maintient après la disparition de l'agent.","s":6},{"q":"Parmi les altérations immunitaires citées dans la maladie de Crohn figure :","o":["Une allocation chronique de lymphocytes dans la muqueuse","Un déficit isolé en immunoglobulines A, d'origine génétique","Une aplasie médullaire, avec pancytopénie","Une neutropénie, profonde et durable"],"r":0,"e":"S'y ajoutent les altérations des facteurs à fonction de barrière, les altérations neuro-histo-chimiques de médiation inflammatoire et les adaptations cellulaires inflammatoires.","s":6},{"q":"La présentation clinique de la maladie de Crohn est variable parce qu'elle dépend :","o":["De l'âge du patient","Du segment du tube digestif affecté","Du sexe","De la durée d'évolution seulement"],"r":1,"e":"Les symptômes les plus communs restent la diarrhée, la déshydratation, la douleur abdominale de type colique et la perte de poids.","s":6},{"q":"Parmi les examens d'imagerie cités pour la maladie de Crohn figurent :","o":["Le scanner ou l'IRM de l'abdomen, en entérographie","La radiographie du thorax, de face et de profil","L'échographie cardiaque, puis l'ECG d'effort sur tapis","La scintigraphie osseuse, du corps entier"],"r":0,"e":"Le diagnostic repose aussi sur l'endoscopie digestive haute, la coloscopie, l'entéroscopie par capsule et les critères histologiques. Scanner = TDM ; on réalise aussi entéro-TDM et entéro-IRM.","s":6},{"q":"Le mécanisme de l'occlusion intestinale dans la maladie de Crohn est :","o":["Un spasme musculaire, de la paroi","Des cicatrices qui épaississent la paroi","Une paralysie nerveuse, de l'intestin","Une compression externe, par une masse"],"r":1,"e":"Elle peut imposer une intervention chirurgicale, comme les fistules et les épisodes aigus graves. Le passage des aliments est obstrué.","s":6},{"q":"Les ulcères de la maladie de Crohn peuvent siéger :","o":["Uniquement dans l'iléon, en fin d'intestin grêle","N'importe où, de la bouche à l'anus","Uniquement dans le côlon, à droite","Uniquement dans l'estomac, à l'antre"],"r":1,"e":"C'est la conséquence du caractère transmural et segmentaire de l'inflammation, qui peut toucher de la bouche à l'anus. Le périnée peut aussi être atteint.","s":6},{"q":"Le choix du traitement de la maladie de Crohn dépend notamment :","o":["Du nombre et de la gravité des poussées","De l'âge seul, quels que soient les symptômes","Du sexe du patient, surtout","Du poids, et de l'indice de masse"],"r":0,"e":"S'y ajoutent les symptômes, la localisation, la gravité et l'étendue, ainsi que la réponse aux traitements antérieurs. La durée de la rémission compte aussi.","s":6},{"q":"En dehors des périodes de diarrhée, l'alimentation recommandée dans la maladie de Crohn est :","o":["Sans gluten, à vie","Normale, sans restriction","Pauvre en protéines animales","Exclusivement liquide, en continu"],"r":1,"e":"Pendant les périodes de diarrhée, on passe à un régime pauvre en fibres et sans lactose.","s":6},{"q":"Dans la rectocolite hémorragique, la muqueuse inflammée produit :","o":["Trop de mucus, avec du pus et du sang","De l'acide chlorhydrique, en excès","Des sels biliaires, en grande quantité","Un mucus stérile, sans pus ni sang, en petite quantité"],"r":0,"e":"La maladie implique toute la paroi de l'organe, avec de petites plaies de surface susceptibles de saigner. Il s'agit du lubrifiant intestinal, produit en excès.","s":6},{"q":"L'étiologie de la rectocolite hémorragique est :","o":["Bactérienne","Inconnue","Auto-immune démontrée","Génétique exclusive"],"r":1,"e":"Comme pour la maladie de Crohn, seules des hypothèses étiologiques sont avancées.","s":6},{"q":"Dans les formes graves de rectocolite hémorragique, s'ajoutent aux symptômes digestifs :","o":["Fatigue, perte de poids et fièvre","Un ictère, avec un prurit","Des céphalées, avec des vertiges intenses","Une dysphagie, aux solides"],"r":0,"e":"Les symptômes varient avec la gravité et l'étendue du côlon affecté, avec des périodes actives et de rémission.","s":6},{"q":"Parmi les complications non digestives de la rectocolite hémorragique, le cours cite :","o":["L'ostéoporose, la lithiase rénale, l'atteinte de la peau","L'insuffisance cardiaque, par surcharge, avec des arythmies","Le diabète, de type insulinodépendant","L'hypothyroïdie, d'origine auto-immune"],"r":0,"e":"S'y ajoutent l'hémorragie grave, la perforation, le mégacôlon toxique et l'augmentation du risque de cancer du côlon. Les articulations peuvent aussi être atteintes.","s":6},{"q":"Le diagnostic de la rectocolite hémorragique repose sur :","o":["La coloscopie, la biopsie, le sang et les selles","La radiographie seule, de l'abdomen","L'échographie abdominale, sans autre examen","Le scanner thoracique, avec une injection de contraste"],"r":0,"e":"Le régime suit par ailleurs les mêmes règles que dans la maladie de Crohn.","s":6},{"q":"Les diverticules peuvent se former :","o":["Uniquement dans le côlon, sigmoïde","N'importe où, mais surtout dans le gros intestin","Uniquement dans l'œsophage, au tiers supérieur","Uniquement dans l'intestin grêle, près du duodénum"],"r":1,"e":"Leur fréquence augmente à partir de 40 ans, et l'évolution se fait de la diverticulose vers la diverticulite. Ils peuvent toucher l'œsophage, l'estomac ou l'intestin grêle.","s":6},{"q":"La maladie diverticulaire se définit comme :","o":["Une inflammation de la paroi, avec des poches infectées","Une tumeur bénigne, qui pousse dans la lumière de l'intestin","Une malformation congénitale, de la paroi","Une infection parasitaire, chronique et récidivante"],"r":0,"e":"La simple présence de diverticules constitue la diverticulose, stade qui précède la diverticulite. Les poches, ou kystes, s'enflamment ou s'infectent ; l'inflammation touche la paroi interne.","s":6},{"q":"Les polypes du côlon concernent environ quelle proportion de la population adulte ?","o":["5 %","15 %","30 %","60 %"],"r":2,"e":"Les polypes hyperplasiques comportent un faible risque malin, alors que les adénomes présentent un risque élevé d'évolution maligne.","s":6},{"q":"Le dépistage du cancer du côlon débute habituellement à :","o":["40 ans","50 ans","60 ans","30 ans"],"r":1,"e":"Il est avancé à 40 ans lorsqu'un apparenté du premier degré a été atteint avant 60 ans.","s":6},{"q":"Où se situent anatomiquement les reins ?","o":["En intrapéritonéal au niveau de L4-L5","En rétropéritonéal au niveau de T12-L3","Dans le pelvis, en arrière de la vessie","En sous-diaphragmatique gauche uniquement"],"r":1,"e":"Les reins sont des organes rétropéritonéaux situés au niveau de T12-L3, entourés de graisse assurant leur protection.","s":7},{"q":"Quel pourcentage du débit cardiaque les reins reçoivent-ils ?","o":["5 %","12 %","21 %","40 %"],"r":2,"e":"Le flux sanguin rénal représente 21 % du débit cardiaque, ce qui explique la sensibilité du rein à toute chute de perfusion.","s":7},{"q":"Quelles structures se trouvent dans le cortex rénal ?","o":["Les anses de Henle, les tubules collecteurs","Les glomérules, les tubules proximaux et distaux","Les pyramides, les papilles seulement","Les grands et les petits calices, puis le bassinet"],"r":1,"e":"Le cortex, région la plus externe, contient les glomérules et les tubules proximaux et distaux : ultrafiltration, réabsorption et sécrétion d'hormones.","s":7},{"q":"Quelle est la fonction principale de la médulla rénale ?","o":["L'ultrafiltration du plasma sanguin","La sécrétion de rénine et d'hormones","La concentration et la dilution de l'urine","Le stockage de l'urine, avant la miction vésicale"],"r":2,"e":"La médulla, la plus interne, contient les anses de Henle et les tubules collecteurs et assure la concentration/dilution de l'urine.","s":7},{"q":"Combien de néphrons possède chaque rein selon le cours ?","o":["Environ 10 000","1 à 4 millions","100 à 200 millions","Environ 50 000"],"r":1,"e":"Chaque rein possède 1 à 4 millions de néphrons et ceux-ci ne peuvent pas être régénérés.","s":7},{"q":"Quelle est la composition du filtrat glomérulaire ?","o":["Identique au plasma","Identique au plasma moins les protéines","Identique à l'urine définitive","Uniquement de l'eau et des électrolytes"],"r":1,"e":"Le passage libre des substances du plasma forme un filtrat de composition identique à celle du plasma, moins les protéines.","s":7},{"q":"Quel type de néphron rend l'urine concentrée ?","o":["Les néphrons corticaux","Les néphrons juxtamédullaires","Les deux de façon égale","Aucun : c'est le rôle de la vessie"],"r":1,"e":"Les néphrons juxtamédullaires rendent l'urine concentrée, tandis que les néphrons corticaux rendent l'urine diluée.","s":7},{"q":"Quel élément vasculaire régule la pression hydrostatique élevée dans les capillaires glomérulaires ?","o":["L'artériole afférente seule","L'artériole efférente","Les capillaires péritubulaires","La veine rénale"],"r":1,"e":"Ce sont les artérioles efférentes qui régulent la pression hydrostatique élevée régnant dans les capillaires glomérulaires.","s":7},{"q":"Parmi ces hormones, laquelle N'EST PAS produite par le rein ?","o":["Rénine","Érythropoïétine","Calcitriol","Insuline"],"r":3,"e":"Le rein produit rénine, érythropoïétine, calcitriol et prostaglandines. L'insuline est pancréatique.","s":7},{"q":"Quelle substance n'est ni réabsorbée ni sécrétée par le tubule ?","o":["Le glucose","Les acides aminés","La créatinine","Le sodium"],"r":2,"e":"La créatinine n'est ni réabsorbée ni sécrétée, ce qui en fait un bon marqueur de la filtration glomérulaire.","s":7},{"q":"Pourquoi le taux d'urée sanguine est-il un marqueur imparfait de la fonction rénale ?","o":["Il dépend en partie de l'alimentation","Il n'est mesurable que sur urines de 24 h","Il est produit exclusivement par le rein","Il varie avec la température corporelle"],"r":0,"e":"L'urée est un produit du métabolisme protéique qui dépend en partie de l'alimentation ; la créatinine, elle, dépend de la composition corporelle.","s":7},{"q":"À quoi sert principalement le débit de filtration glomérulaire (DFG) ?","o":["À poser le diagnostic histologique d'une néphropathie","À classer la sévérité, prévoir les complications","À mesurer la pression artérielle dans le rein","À localiser un calcul dans l'uretère, avant son extraction"],"r":1,"e":"Calculé à partir de la créatinine, le DFG permet de classer la sévérité, de prévoir les complications et de définir des mesures de prévention/contrôle. Il permet aussi de définir la prévention.","s":7},{"q":"Au-delà de quelle valeur la protéinurie devient-elle anormale selon le cours ?","o":["15 mg/jour","150 mg/jour","1,5 g/jour","3,5 g/jour"],"r":1,"e":"Des protéines dans l'urine ne sont physiologiques qu'à dose minime, moins de 150 mg/jour. Le seuil de 3,5 g/j définit, lui, le syndrome néphrotique.","s":7},{"q":"Que peut-on dire de l'échographie rénale ?","o":["Elle mesure précisément le DFG, rein par rein","Elle montre l'anatomie, sans évaluer la fonction","Elle exige une injection de radio-isotopes","Elle est contre-indiquée si le rein est malade"],"r":1,"e":"L'échographie n'évalue pas la fonction rénale : elle montre les altérations anatomiques.","s":7},{"q":"Pourquoi l'uro-scanner est-il déconseillé chez un patient avec une maladie rénale connue ?","o":["L'irradiation y est beaucoup trop forte","Le produit de contraste risque d'aggraver la maladie","Il ne montre pas les reins, seulement l'uretère","Il exige toujours une anesthésie générale, avec intubation"],"r":1,"e":"Les patients porteurs d'une maladie rénale connue ne doivent pas subir cet examen en raison du risque d'aggravation dû à l'usage du produit de contraste.","s":7},{"q":"Quel examen fournit la valeur approximative de la fonction de chaque rein séparément ?","o":["L'échographie rénale","La biopsie rénale, percutanée","La scintigraphie rénale","La radiographie de l'abdomen"],"r":2,"e":"La scintigraphie rénale, examen de médecine nucléaire, informe sur le DFG approximatif de chaque rein (ml/min et pourcentage) et localise l'arbre excréteur. La radiographie est celle de l'abdomen sans préparation.","s":7},{"q":"Quelle est la définition de l'insuffisance rénale aiguë ?","o":["Une perte lente et irréversible, sur des années","Une chute rapide de la filtration, parfois réversible","Une obstruction définitive de l'urètre, chez l'homme","Une baisse isolée de la production d'EPO"],"r":1,"e":"L'IRA est une diminution rapide (jours ou semaines) de la capacité des reins à filtrer les déchets ; la fonction peut être récupérée en quelques semaines. La chute se fait en jours ou en semaines.","s":7},{"q":"Quelle cause d'IRA correspond au mécanisme pré-rénal ?","o":["Une nécrose tubulaire, d'origine toxique","Une déshydratation, qui réduit le flux sanguin rénal","Un calcul qui obstrue l'uretère, avec une dilatation en amont","Une hypertrophie de la prostate, bénigne"],"r":1,"e":"Les causes pré-rénales sont les troubles qui diminuent le flux sanguin vers les reins, comme la déshydratation.","s":7},{"q":"Quelles sont les complications graves de l'insuffisance rénale aiguë citées dans le cours ?","o":["Insuffisance cardiaque et hyperkaliémie","Hypoglycémie sévère et hypothermie","Ostéoporose et fractures du col","Cirrhose et ascite, avec un ictère franc"],"r":0,"e":"Les complications graves sont l'insuffisance cardiaque et des taux élevés de potassium dans le sang.","s":7},{"q":"Quelle mesure diététique fait partie du traitement de l'IRA ?","o":["Augmenter fortement le potassium et le phosphore, chaque jour","Restreindre les liquides, le sel, le phosphore, le potassium","Supprimer tous les apports, en protéines comme en calories","Boire au moins quatre litres d'eau, chaque jour"],"r":1,"e":"Le traitement associe restriction des liquides, du sodium, du phosphore et du potassium, tout en maintenant une bonne alimentation. Une bonne alimentation doit être maintenue.","s":7},{"q":"Quelle est la cause principale d'insuffisance rénale chronique atteignant le stade terminal ?","o":["La polykystose rénale","Le diabète sucré","Les infections urinaires","La lithiase urinaire"],"r":1,"e":"Le diabète est la cause principale ; la maladie rénale peut apparaître comme conséquence d'un diabète de type 1 comme de type 2.","s":7},{"q":"Quel est l'accès vasculaire habituel pour l'hémodialyse ?","o":["Un cathéter fémoral permanent","Une fistule artério-veineuse","Une voie dans la veine porte","Une voie veineuse au dos de la main"],"r":1,"e":"L'accès habituel des thérapies de suppléance est une fistule artério-veineuse.","s":7},{"q":"Quel avantage la transplantation rénale a-t-elle sur la dialyse ?","o":["Elle supprime tout traitement médicamenteux, à vie","Le greffon produit les hormones utiles au sang et à l'os","Elle ne comporte aucun risque d'infection, même tardif","Elle ne demande aucune compatibilité avec le donneur"],"r":1,"e":"Le greffon régule le métabolisme par des moyens naturels et produit les hormones qui régulent la formation des globules rouges et la régénération des os. Ces hormones régulent la formation des globules rouges et la régénération osseuse.","s":7},{"q":"Quel signe doit faire évoquer un rejet ou une infection chez un transplanté rénal ?","o":["Une bradycardie isolée, au repos, sans autre signe","Une fièvre, avec œdème, hyperurie et douleur","Une perte de poids progressive, isolée","Une hypotension orthostatique, au lever"],"r":1,"e":"Les signes à surveiller sont : fièvre supérieure à 38 °C, œdème, hyperurie, HTA, douleur locale ou généralisée. La fièvre dépasse 38 °C ; une HTA s'y associe.","s":7},{"q":"Quel est le mécanisme lésionnel des glomérulonéphrites ?","o":["Une obstruction mécanique des tubules","Des complexes immuns, qui activent le complément","Une ischémie, par thrombose de la veine rénale","Une carence en érythropoïétine"],"r":1,"e":"Les complexes immuns (circulants ou formés in situ) activent le complément et les neutrophiles, produisant la lésion cellulaire puis glomérulaire. Les neutrophiles sont aussi activés.","s":7},{"q":"Quel examen permet le diagnostic d'une glomérulonéphrite ?","o":["L'échographie rénale","La biopsie rénale","La scintigraphie","Le dosage isolé de la créatinine"],"r":1,"e":"Le diagnostic des glomérulonéphrites se fait par biopsie.","s":7},{"q":"Quel est le délai d'apparition d'une glomérulonéphrite proliférative aiguë post-streptococcique ?","o":["Dans les 24 heures, après une angine non traitée","1 à 4 semaines après l'infection","6 à 12 mois après l'infection","Plusieurs années après l'infection"],"r":1,"e":"Elle se manifeste dans les 1 à 4 semaines suivant une infection streptococcique de la gorge ou de la peau, avec un tableau de syndrome néphritique aigu. L'infection touche la gorge ou la peau.","s":7},{"q":"Quel type de glomérulonéphrite rapidement progressive est le plus commun ?","o":["Le type I, à AC anti-membrane basale","Le type II, à complexes immuns","Le type III, avec présence d'ANCA","Aucun n'est prédominant"],"r":2,"e":"La GNRP de type III est la plus commune : ni AC anti-MBG ni complexes immuns, mais présence d'anticorps anticytoplasmiques des neutrophiles (ANCA).","s":7},{"q":"Quel seuil de protéinurie définit le syndrome néphrotique ?","o":["Supérieure à 150 mg/jour","Supérieure à 1 g/jour","Supérieure à 3,5 g/jour","Supérieure à 10 g/jour"],"r":2,"e":"Le syndrome néphrotique se définit par une protéinurie supérieure à 3,5 g/jour, surtout d'albumine et de transferrine.","s":7},{"q":"Quelle maladie glomérulaire montre des glomérules normaux en microscopie optique mais un effacement diffus des pédicelles en microscopie électronique ?","o":["La glomérulonéphrite membraneuse","La maladie à lésions minimes","L'hyalinose segmentaire et focale","La GN membranoproliférative"],"r":1,"e":"C'est la maladie à lésions minimes, cause importante de syndrome néphrotique chez l'enfant, sans dépôts immuns et de bon pronostic sous corticoïdes.","s":7},{"q":"Le rein adulte mesure en longueur :","o":["5 à 7,5 cm","11 à 13 cm","15 à 18 cm","20 cm"],"r":1,"e":"Sa largeur est de 5 à 7,5 cm ; il pèse 125 à 170 g chez l'homme et 115 à 155 g chez la femme.","s":7},{"q":"Le hile rénal livre passage :","o":["Aux vaisseaux, aux nerfs et à l'uretère","Aux seules artères rénales, droite et gauche","Au seul uretère, vers la vessie","Aux anses de Henle, vers la médulla"],"r":0,"e":"Il se situe sur la face médiale du rein ; calices et bassinet occupent, eux, le sinus rénal. Les vaisseaux sont artères, veines et lymphatiques.","s":7},{"q":"Les pyramides et la papille rénales assurent :","o":["La filtration du plasma","Le drainage de l'urine vers les calices","La sécrétion d'hormones rénales","La réabsorption du glucose filtré"],"r":1,"e":"Les calices et le bassinet collectent ensuite l'urine vers l'uretère. Les tubes collecteurs y convergent.","s":7},{"q":"Le néphron se compose :","o":["Du corpuscule, des tubules et de l'anse de Henle","Du seul glomérule, avec sa capsule","Du glomérule et de l'uretère, réunis","Du bassinet, des grands et des petits calices du rein"],"r":0,"e":"Le corpuscule rénal réunit le glomérule et la capsule de Bowman. Les tubules sont proximal, distal et collecteur.","s":7},{"q":"Les néphrons ont pour particularité :","o":["De se régénérer après une lésion","De ne pas pouvoir se régénérer","De se multiplier chez l'adulte","D'être remplacés chaque année"],"r":1,"e":"C'est ce qui rend irréversible la perte de fonction dans l'insuffisance rénale chronique.","s":7},{"q":"Le néphron cortical produit :","o":["Une urine concentrée","Une urine diluée","Aucun filtrat","Uniquement des hormones"],"r":1,"e":"Le néphron juxtamédullaire, à longue anse, rend l'urine concentrée.","s":7},{"q":"Les nutriments comme les acides aminés et le glucose sont, au niveau tubulaire :","o":["Totalement réabsorbés","Partiellement réabsorbés","Ni réabsorbés ni sécrétés","Sécrétés"],"r":0,"e":"Les électrolytes sont partiellement réabsorbés, la créatinine n'est ni réabsorbée ni sécrétée, et certains déchets et médicaments sont sécrétés.","s":7},{"q":"Parmi les fonctions biochimiques du rein, le cours cite la synthèse :","o":["De glucose, d'angiotensinogène et d'ammoniac","D'insuline, de glucagon et de somatostatine","De bile, d'acides biliaires et de bilirubine conjuguée","De facteurs de coagulation, d'albumine"],"r":0,"e":"Le rein produit aussi rénine, érythropoïétine, calcitriol et prostaglandines.","s":7},{"q":"Le calcitriol produit par le rein correspond :","o":["À la forme active de la vitamine D","À la vitamine K, activée","À la parathormone, sécrétée","À la calcitonine, thyroïdienne"],"r":0,"e":"Son défaut explique l'atteinte osseuse de l'insuffisant rénal, comme le défaut d'EPO en explique l'anémie.","s":7},{"q":"Parmi les fonctions homéostatiques du rein figurent :","o":["Le volume plasmatique, l'osmolalité, les électrolytes","La digestion des lipides, par la bile","La production d'anticorps, par les reins","Le stockage du fer, de la ferritine et de la vitamine B12"],"r":0,"e":"Le rein n'est donc pas qu'un filtre : sa perte entraîne aussi anémie et atteinte osseuse. L'équilibre acido-basique et l'excrétion en font aussi partie.","s":7},{"q":"La créatinine provient :","o":["Du métabolisme des protéines alimentaires","De la dégradation de la créatine du muscle","De l'hémoglobine des hématies","Du métabolisme hépatique, des graisses"],"r":1,"e":"Son taux dépend donc en partie de la masse musculaire, tandis que l'urée dépend en partie de l'alimentation. La créatine est phosphorylée.","s":7},{"q":"La protéinurie physiologique est inférieure à :","o":["50 mg/jour","150 mg/jour","500 mg/jour","1 g/jour"],"r":1,"e":"L'analyse d'urine recherche par ailleurs des érythrocytes, également signe d'altération de la fonction rénale.","s":7},{"q":"La biopsie rénale est indispensable :","o":["Pour toute insuffisance rénale","Pour le diagnostic des glomérulonéphrites","Pour évaluer le DFG, rein par rein, en ml/min","Pour détecter une lithiase urinaire"],"r":1,"e":"Elle est utilisée lorsque les examens non invasifs — échographie, uro-scanner, scintigraphie — ne sont pas concluants.","s":7},{"q":"La scintigraphie rénale exige :","o":["L'injection de produit de contraste iodé","L'injection de radio-isotopes","Une anesthésie générale","Un jeûne de 48 heures"],"r":1,"e":"Elle fournit le DFG approximatif de chaque rein en ml/min et en pourcentage, ainsi que la localisation de l'arbre excréteur.","s":7},{"q":"L'insuffisance rénale chronique se définit par une perte :","o":["Rapide, souvent réversible","Lente, progressive, irréversible","Intermittente, par poussées successives","Silencieuse, découverte tard"],"r":1,"e":"L'insuffisance rénale aiguë est, elle, une chute rapide de la filtration en jours ou semaines, potentiellement réversible.","s":7},{"q":"Parmi les causes citées d'insuffisance rénale chronique figurent :","o":["La glomérulonéphrite, la polykystose, le diabète","Les seules infections urinaires, basses","Les traumatismes, du rein ou de l'uretère","Les seules lithiases, quelle que soit leur taille"],"r":0,"e":"Le diabète en est la première cause. La pyélonéphrite et l'HTA en font aussi partie.","s":7},{"q":"Parmi les techniques de suppléance rénale, le cours cite :","o":["L'hémodialyse, l'hémofiltration, la dialyse péritonéale","La seule dialyse péritonéale, à domicile","La plasmaphérèse et les échanges plasmatiques","L'oxygénothérapie, l'hyperbarie et la ventilation non invasive"],"r":0,"e":"L'accès vasculaire habituel de l'hémodialyse est la fistule artério-veineuse. L'hémodialyse peut être intermittente ou continue.","s":7},{"q":"Le mécanisme lésionnel des glomérulonéphrites repose sur :","o":["Des complexes immuns, qui activent le complément","Une infection bactérienne directe du glomérule","Une ischémie, par baisse du débit rénal","Une toxicité médicamenteuse, par les anti-inflammatoires"],"r":0,"e":"Les conséquences en sont une diminution du débit urinaire, une protéinurie et une hématurie. Ils sont circulants ou formés in situ, et activent aussi les neutrophiles.","s":7},{"q":"Le syndrome néphritique associe :","o":["Hématurie, protéinurie modérée, œdème","Protéinurie massive, au-delà de 3,5 g/j","Hyperlipidémie isolée, sans protéinurie ni œdème","Polyurie, soif intense, nycturie"],"r":0,"e":"Le syndrome néphrotique se définit, lui, par une protéinurie > 3,5 g/j, une hypoalbuminémie, un œdème, une hyperlipidémie et une lipidurie. Une HTA peut s'y associer.","s":7},{"q":"Dans les infections du tractus urinaire, Escherichia coli est en cause dans environ :","o":["50 % des cas","85 % des cas","30 % des cas","100 % des cas"],"r":1,"e":"La voie ascendante prédomine, et le diagnostic associe bactériurie et pyurie.","s":7},{"q":"Qu'est-ce qui stimule la contraction de la vésicule biliaire ?","o":["La cholécystokinine, venue de l'intestin","La gastrine, venue de l'estomac","L'insuline, venue du pancréas","La somatostatine, venue du pancréas"],"r":0,"e":"Elle stimule aussi la sécrétion d'enzymes par le pancréas. Les cellules entériques la produisent devant un contenu duodénal riche en lipides et en protéines.","s":8},{"q":"Quels sont les acides biliaires primaires ?","o":["Les acides cholique et chénodésoxycholique","Les acides désoxycholique et lithocholique","Les acides urique et lactique, du sang","L'acide chlorhydrique de l'estomac"],"r":0,"e":"Les acides désoxycholique et lithocholique sont les acides biliaires secondaires formés dans l'intestin. Ils sont conjugués à la glycine et à la taurine.","s":8},{"q":"Quelle est la fonction des sels biliaires ?","o":["Faciliter la digestion des lipides","Neutraliser l'acidité gastrique","Activer les protéases pancréatiques","Absorber le fer alimentaire"],"r":0,"e":"Ils dérivent du cholestérol, d'origine alimentaire ou hépatocytaire. Ils facilitent aussi l'absorption des lipides.","s":8},{"q":"Quelle proportion de l'urobilinogène retourne dans la circulation hépatique ?","o":["20 %","50 %","80 %","5 %"],"r":0,"e":"La bilirubine libre se lie d'abord à l'albumine, puis la forme conjuguée devient hydrosoluble.","s":8},{"q":"Quelle est la composition d'un calcul de cholestérol ?","o":["Surtout du cholestérol, sous forme cristalline","Surtout du bilirubinate de calcium, pigmenté","Surtout du carbonate de calcium, très dur","Surtout de l'oxalate de calcium, en aiguilles"],"r":0,"e":"Les calculs pigmentaires sont faits de bilirubinate de calcium. Le cholestérol, monohydraté, dépasse 50 % du calcul.","s":8},{"q":"Quel est l'aspect radiologique des calculs de cholestérol ?","o":["Radiotransparents","Radio-opaques","Toujours invisibles","Hyperdenses au scanner uniquement"],"r":0,"e":"Ils sont jaunes, durs et se forment exclusivement dans la vésicule biliaire.","s":8},{"q":"Quelle est la particularité des calculs pigmentaires BRUNS ?","o":["Ils naissent dans des canaux biliaires infectés","Ils naissent dans une vésicule stérile","Ils sont radiotransparents, invisibles à la radiographie","Ils sont durs et jaunes, comme le cholestérol"],"r":0,"e":"Les calculs pigmentaires noirs se forment dans une vésicule biliaire stérile. Les canaux sont intra- ou extra-hépatiques.","s":8},{"q":"Quel est le rapport homme/femme dans la cholélithiase ?","o":["1:2","2:1","1:1","1:5"],"r":0,"e":"La prévalence augmente avec l'âge.","s":8},{"q":"Quel facteur de risque de cholélithiase est cité en lien avec le poids ?","o":["L'obésité et la perte de poids rapide","La dénutrition chronique, sévère","Un poids stable, sur plusieurs années de suite","L'activité physique, régulière"],"r":0,"e":"On retient aussi les œstrogènes, la stase vésiculaire et les syndromes hypercholestérolémiques.","s":8},{"q":"Quel facteur de risque est spécifique des calculs pigmentaires ?","o":["Les syndromes hémolytiques chroniques","L'obésité, surtout abdominale","Les œstrogènes, de la pilule ou de la grossesse","La perte de poids, rapide"],"r":0,"e":"On retient aussi l'origine asiatique, l'infection biliaire et la maladie iléale ou la mucoviscidose.","s":8},{"q":"Quel est le mécanisme de formation des calculs pigmentaires ?","o":["La bilirubine libre précipite en sels de calcium","La sursaturation de la bile en cholestérol","L'hypersécrétion de mucus, par la vésicule","L'hypomotilité de la vésicule, qui se vide très mal"],"r":0,"e":"La maladie hémolytique chronique en est un exemple. La bilirubine non conjuguée précipite en bilirubinate de calcium.","s":8},{"q":"Quel rôle joue le mucus dans la formation des calculs de cholestérol ?","o":["Il piège les cristaux, qui s'agglomèrent","Il dissout les cristaux de cholestérol","Il neutralise le cholestérol en excès","Il n'a aucun rôle, il protège la paroi"],"r":0,"e":"Il faut aussi une bile sursaturée, une hypomotilité et une nucléation augmentée. C'est son hypersécrétion qui permet l'agglomération en calculs.","s":8},{"q":"Quelle proportion des cholélithiases est asymptomatique ?","o":["70 à 80 %","10 à 20 %","50 %","95 %"],"r":0,"e":"La douleur, quand elle existe, est une colique spasmodique du quadrant supérieur droit.","s":8},{"q":"Qu'est-ce que l'iléus biliaire ?","o":["Un calcul qui érode la paroi vers l'intestin voisin","Une paralysie intestinale, après une opération","Une obstruction du canal cystique, par un calcul enclavé","Une infection des voies biliaires, aiguë"],"r":0,"e":"C'est une complication de la cholélithiase.","s":8},{"q":"Quelle est la cause de 90 % des cholécystites aiguës ?","o":["L'obstruction du col ou du canal cystique","Une infection bactérienne primitive","Un traumatisme","Une ischémie mésentérique"],"r":0,"e":"La contamination bactérienne y est tardive.","s":8},{"q":"Quel est le mécanisme initial de la cholécystite aiguë ?","o":["Une irritation chimique par les acides biliaires","Une infection bactérienne, d'emblée","Une thrombose de l'artère cystique","Une réaction auto-immune, contre la paroi de la vésicule"],"r":0,"e":"Suivent la dysmotilité, la distension, l'ischémie et une contamination bactérienne tardive. Des médiateurs de l'inflammation sont alors libérés.","s":8},{"q":"Comment recherche-t-on le signe de Murphy ?","o":["En palpant l'hypochondre droit pendant l'inspiration","En percutant l'abdomen, dans les quatre cadrans","En comprimant l'ombilic, puis en relâchant","En palpant le flanc gauche, pendant l'expiration forcée"],"r":0,"e":"Il est positif si la douleur interrompt l'inspiration ; la manœuvre est indolore au QSG. On palpe avec deux doigts le quadrant supérieur droit (QSD), puis on demande au patient d'inspirer.","s":8},{"q":"Quel est l'aspect morphologique de la vésicule dans la cholécystite aiguë ?","o":["Grosse et tendue, rouge vif ou vert foncé","Atrophique et pâle, avec une paroi fine et rétractée","Normale, sans aucune anomalie visible","Calcifiée, avec une paroi en porcelaine"],"r":0,"e":"La cholécystite chronique donne une vésicule augmentée, diminuée ou normale. Elle est recouverte de fibrine, avec un contenu trouble ou purulent.","s":8},{"q":"Quel traitement chirurgical est indiqué dans la cholécystite aiguë ?","o":["La cholécystectomie, par laparoscopie","La CPRE seule, sans aucune chirurgie associée","La gastrectomie partielle","La pancréatectomie, céphalique"],"r":0,"e":"On associe diète stricte, antalgiques IV et antibiotiques IV. On passe en chirurgie ouverte en cas de perforation.","s":8},{"q":"Quels symptômes évoquent une cholécystite chronique ?","o":["Ballonnement, nausées, intolérance aux graisses","Fièvre élevée, frissons, douleur intense de l'hypochondre","Ictère franc, urines foncées, prurit","Choc, avec une hypotension sévère"],"r":0,"e":"La muqueuse y est généralement préservée. L'inconfort abdominal est mal défini, avec des flatulences.","s":8},{"q":"Dans quelle proportion des cholélithiases survient la cholédocolithiase ?","o":["Environ 10 %","Environ 50 %","Environ 80 %","Moins de 1 %"],"r":0,"e":"En Asie ce sont des calculs pigmentaires, en Europe des calculs de cholestérol.","s":8},{"q":"En quoi consiste la triade de Charcot ?","o":["Douleur de l'hypochondre droit, ictère, fièvre","Douleur abdominale, vomissements, diarrhée","Ictère, ascite, encéphalopathie hépatique","Fièvre, tachycardie, hypotension, marbrures cutanées"],"r":0,"e":"Elle caractérise l'angiocholite, dont les germes sont E. coli et Klebsiella. La fièvre s'accompagne de frissons ; la douleur siège au QSD.","s":8},{"q":"Quelles cellules des îlots de Langerhans produisent l'insuline ?","o":["Les cellules bêta","Les cellules alpha","Les cellules delta","Les cellules PP"],"r":0,"e":"Les cellules alpha produisent le glucagon, les delta la somatostatine.","s":8},{"q":"Combien d'enzymes le pancréas sécrète-t-il ?","o":["22","10","5","50"],"r":0,"e":"Les protéases, lipases et élastases sont des proenzymes activées par la trypsine dans le duodénum.","s":8},{"q":"Quelles enzymes pancréatiques sont sécrétées sous forme active ?","o":["L'amylase et la lipase","Les protéases","Les élastases","Toutes les enzymes"],"r":0,"e":"Les autres sont des proenzymes nécessitant l'activation par la trypsine.","s":8},{"q":"Quelle est la forme la plus grave de pancréatite aiguë ?","o":["La pancréatite hémorragique aiguë","La pancréatite interstitielle aiguë","La pancréatite nécrosante aiguë","La pancréatite chronique"],"r":0,"e":"La forme interstitielle est la forme légère.","s":8},{"q":"Que désigne le signe de Grey Turner ?","o":["Des ecchymoses des flancs","Des ecchymoses péri-ombilicales","Un ictère","Une douleur à l'inspiration"],"r":0,"e":"Le signe de Cullen correspond aux ecchymoses péri-ombilicales.","s":8},{"q":"Quel marqueur biologique est le plus sensible et spécifique de la pancréatite ?","o":["La lipase","L'amylase","La GGT","La phosphatase alcaline"],"r":0,"e":"L'amylasémie doit être 3 fois supérieure à la valeur normale.","s":8},{"q":"Quelles sont les manifestations de la pancréatite chronique ?","o":["Malabsorption, stéatorrhée, diabète, pseudokyste","Ictère, fièvre, frissons, douleur de l'hypochondre droit","Ecchymoses des flancs, de l'ombilic","Hémorragie digestive, haute"],"r":0,"e":"Elle résulte d'épisodes répétés d'inflammation avec fibrose et perte progressive de fonction. La diarrhée vient de la malabsorption.","s":8},{"q":"Où siège le plus souvent le carcinome du pancréas ?","o":["Dans la tête, dans 60 % des cas","Dans le corps, dans 60 %","Dans la queue, dans 60 %","De façon diffuse dans 60 %"],"r":0,"e":"Corps 15 %, queue 5 % et forme diffuse ou disséminée 20 %.","s":8},{"q":"La sécrétion biliaire débute dans :","o":["La vésicule biliaire","Les hépatocytes","Le duodénum","Le pancréas"],"r":1,"e":"Elle comprend cholestérol, sels biliaires issus de la décomposition de l'hémoglobine, et phospholipides.","s":8},{"q":"La cholécystokinine est produite par :","o":["Les hépatocytes, dans le lobule du foie","Les cellules entériques, devant des graisses","Les cellules bêta des îlots du pancréas","Les macrophages, dans le sang circulant"],"r":1,"e":"Elle stimule à la fois la contraction de la vésicule biliaire et la sécrétion d'enzymes par le pancréas. Le contenu duodénal est alors riche en lipides et en protéines.","s":8},{"q":"La composition de la bile comprend :","o":["Eau, sels biliaires, bilirubine, cholestérol, lécithine","Eau et cholestérol seulement, sans aucun autre composé dissous","Enzymes protéolytiques, trypsine, élastase","Bicarbonate seulement, sans sels biliaires"],"r":0,"e":"L'acétylcholine, libérée par le système nerveux central, intervient comme neurotransmetteur dans cette régulation. Elle contient aussi des acides gras, des ions et des IgA.","s":8},{"q":"Les acides biliaires secondaires formés dans l'intestin sont :","o":["L'acide cholique et l'acide chénodésoxycholique","L'acide désoxycholique et l'acide lithocholique","La glycine et la taurine","La lécithine et le cholestérol"],"r":1,"e":"Les acides biliaires primaires sont l'acide cholique et l'acide chénodésoxycholique, conjugués à la glycine et à la taurine.","s":8},{"q":"La bilirubine résulte de la dégradation du groupe hème :","o":["Par les hépatocytes directement","Après phagocytose par les macrophages","Dans la rate uniquement","Dans le rein"],"r":1,"e":"La bilirubine libre se lie ensuite à l'albumine, puis la bilirubine conjuguée devient hydrosoluble.","s":8},{"q":"Les calculs pigmentaires NOIRS se forment :","o":["Dans une vésicule stérile","Dans des canaux biliaires infectés","Dans le duodénum","Dans le canal pancréatique"],"r":0,"e":"Les calculs pigmentaires bruns se forment, eux, dans des canaux biliaires intra- ou extra-hépatiques infectés.","s":8},{"q":"Les calculs de cholestérol se caractérisent par un aspect :","o":["Mou, multiple et radio-opaque","Jaune, dur et radiotransparent","Noir et friable","Blanc et lisse"],"r":1,"e":"Les calculs pigmentaires sont généralement mous, multiples et radio-opaques.","s":8},{"q":"Parmi les facteurs de risque de cholélithiase citant le poids, le cours mentionne :","o":["L'obésité et la perte de poids rapide","La maigreur constitutionnelle","Le poids de naissance, faible","La sarcopénie du sujet âgé, avec dénutrition"],"r":0,"e":"S'y ajoutent les œstrogènes, la stase vésiculaire et les syndromes hypercholestérolémiques.","s":8},{"q":"Parmi les facteurs de risque spécifiques des calculs pigmentaires figurent :","o":["L'hémolyse chronique et l'infection biliaire","L'obésité, surtout abdominale, chez la femme jeune","Les œstrogènes, de la pilule ou de la grossesse","L'hypercholestérolémie familiale"],"r":0,"e":"S'y ajoutent l'origine asiatique et la maladie iléale ou mucoviscidose avec insuffisance pancréatique. Les syndromes hémolytiques sont chroniques ; l'infection touche le tractus biliaire.","s":8},{"q":"Dans la pathogénie des calculs de cholestérol, l'hypersécrétion de mucus :","o":["Dissout les cristaux de cholestérol","Emprisonne les cristaux, qui s'agglomèrent","Empêche la nucléation des cristaux","Neutralise le cholestérol, en excès dans la bile"],"r":1,"e":"Il faut de plus une bile sursaturée en cholestérol, une hypomotilité vésiculaire et une nucléation augmentée. Les cristaux s'agglomèrent alors en calculs.","s":8},{"q":"La douleur de la cholélithiase est décrite comme :","o":["Une colique spasmodique de l'hypochondre droit","Une douleur épigastrique, permanente","Une douleur lombaire, à la mobilisation","Une douleur thoracique, rétro-sternale et constrictive"],"r":0,"e":"70 à 80 % des cholélithiases restent toutefois asymptomatiques. Elle est liée à l'obstruction des canaux biliaires.","s":8},{"q":"Parmi les complications de la cholélithiase, le cours cite :","o":["L'empyème, la perforation, les fistules","L'insuffisance rénale, chronique","L'infarctus du myocarde, par athérome","L'hépatite virale, chronique ou aiguë"],"r":0,"e":"S'y ajoutent la cholécystite, la cholestase obstructive, la pancréatite et l'iléus biliaire par érosion d'un calcul dans l'intestin adjacent. L'angiocholite en fait aussi partie.","s":8},{"q":"Dans la cholécystite aiguë, la contamination bactérienne est :","o":["Le mécanisme initial, dès le début","Tardive, après l'irritation chimique","Absente, la bile restant stérile","Toujours à E. coli, d'emblée"],"r":1,"e":"S'y associent dysmotilité vésiculaire, distension et ischémie. L'irritation chimique par les acides biliaires est première.","s":8},{"q":"Les symptômes de la cholécystite aiguë comprennent :","o":["Douleur de l'hypochondre droit, fièvre, nausées","Ictère isolé, sans douleur ni fièvre","Diarrhée profuse, crampes abdominales, déshydratation","Dysphagie, aux solides et aux liquides"],"r":0,"e":"Le signe de Murphy — douleur interrompant l'inspiration à la palpation du QSD — complète l'examen. La douleur peut être épigastrique ; s'y ajoutent anorexie, tachycardie et vomissements ; la fièvre est modérée.","s":8},{"q":"Le bilan de la cholécystite aiguë comprend :","o":["Hémogramme, bilan hépatique et rénal, échographie","Une IRM cérébrale, avec injection","Un électrocardiogramme seul, puis une épreuve d'effort","Une coloscopie, avec des biopsies étagées"],"r":0,"e":"Le traitement associe diète stricte, antalgiques et antibiotiques intraveineux, puis cholécystectomie laparoscopique. Le bilan rénal comprend créatinine, urée et ionogramme ; l'échographie est abdominale.","s":8},{"q":"Dans la cholécystite chronique, la vésicule :","o":["Est toujours augmentée de volume, tendue et rouge","Peut être grosse, petite ou normale","Est toujours atrophique, scléreuse","Est toujours purulente, infectée"],"r":1,"e":"Elle se traduit par un inconfort abdominal mal défini, un ballonnement, des nausées, des flatulences et une intolérance aux graisses. La paroi s'épaissit de façon variable et la muqueuse est généralement préservée.","s":8},{"q":"Les germes cités dans l'angiocholite sont :","o":["E. coli et Klebsiella","Staphylococcus aureus","Helicobacter pylori","Streptococcus pyogenes"],"r":0,"e":"La triade de Charcot associe douleur du quadrant supérieur droit, ictère et fièvre avec frissons.","s":8},{"q":"Les cellules delta des îlots de Langerhans produisent :","o":["L'insuline","Le glucagon","La somatostatine","Le polypeptide pancréatique"],"r":2,"e":"Les cellules alpha produisent le glucagon, les bêta l'insuline et les cellules PP le polypeptide pancréatique.","s":8},{"q":"Le pancréas exocrine sécrète dans le duodénum :","o":["Des enzymes, du bicarbonate et de l'eau","De la bile, des sels biliaires et de la bilirubine","De l'insuline, du glucagon et de la somatostatine","Des sels biliaires, de la lécithine"],"r":0,"e":"Cette sécrétion répond à des stimuli à la fois neuronaux et humoraux.","s":8},{"q":"Les protéases, lipases et élastases pancréatiques sont sécrétées :","o":["Sous forme active, d'emblée","En proenzymes, activées dans le duodénum","En précurseurs inactifs, jamais activés","Par la vésicule biliaire, avec la bile"],"r":1,"e":"L'amylase et la lipase sont, elles, sécrétées sous forme active ; l'activation intrapancréatique provoque protéolyse, lipolyse et hémorragie. C'est la trypsine qui les active dans le duodénum.","s":8},{"q":"Comment le cours définit-il le diabète sucré ?","o":["Une maladie auto-immune, exclusive de l'enfant","Un désordre métabolique, avec hyperglycémie chronique","Une insuffisance du pancréas exocrine, avec stéatorrhée","Une maladie vasculaire primitive de la rétine"],"r":1,"e":"Le diabète sucré est un désordre métabolique d'étiologie multiple, caractérisé par une hyperglycémie chronique avec troubles du métabolisme des glucides, lipides et protéines. Son étiologie est multiple.","s":9},{"q":"De quelles déficiences résulte le diabète sucré ?","o":["De la sécrétion ou de l'action de l'insuline","Du seul défaut de sécrétion du glucagon","D'un déficit en hormones thyroïdiennes, ou en iode","D'une carence en cortisol, surrénalienne"],"r":0,"e":"Il résulte de déficiences dans la sécrétion ou l'action de l'insuline, ou des deux. Les deux déficiences peuvent s'associer.","s":9},{"q":"Quels métabolismes sont perturbés dans le diabète sucré ?","o":["Celui des glucides seulement","Ceux des glucides, des lipides, des protéines","Celui des lipides seulement, avec une dyslipidémie","Celui de l'eau et du sodium, seulement"],"r":1,"e":"L'hyperglycémie chronique s'accompagne de troubles du métabolisme des glucides, des lipides et des protéines.","s":9},{"q":"Quel est le mécanisme du diabète de type 1 ?","o":["Une résistance périphérique à l'insuline, dans le muscle","La destruction des cellules du pancréas à insuline","Un excès isolé de glucagon, par une tumeur","Une obstruction des canaux pancréatiques"],"r":1,"e":"Le type 1 correspond à la destruction des cellules pancréatiques productrices d'insuline.","s":9},{"q":"Quelle population est typiquement touchée par le diabète de type 1 ?","o":["Les adultes de plus de 60 ans, souvent sédentaires","Les enfants, adolescents et jeunes adultes","Les femmes enceintes, exclusivement","Les personnes obèses, de plus de 50 ans"],"r":1,"e":"Le type 1 se produit de façon rapide chez les enfants, les adolescents et les jeunes adultes.","s":9},{"q":"Quelle est l'évolution possible d'un diabète de type 1 non traité en quelques jours ?","o":["Une hypoglycémie chronique","Un coma hyperglycémique","Une insuffisance rénale terminale","Une cécité complète"],"r":1,"e":"Le début des symptômes est soudain et l'évolution clinique rapide, pouvant conduire au coma hyperglycémique en quelques jours.","s":9},{"q":"Pourquoi le type 1 est-il appelé diabète insulino-dépendant ?","o":["Il apparaît après un traitement par insuline","Son traitement exige toujours de l'insuline","L'insuline y est produite en excès","Il ne répond jamais à l'insuline, même à forte dose"],"r":1,"e":"Il est connu comme diabète insulino-dépendant car il requiert l'usage continu d'insuline dans son traitement.","s":9},{"q":"Quel est le type de diabète le plus commun ?","o":["Le type 1","Le type 2","Le diabète gestationnel","Le diabète néonatal"],"r":1,"e":"Le diabète de type 2 est le type le plus commun.","s":9},{"q":"Quel est le double mécanisme du diabète de type 2 ?","o":["Une destruction auto-immune et un défaut de glucagon","Moins d'insuline produite, ou une insuline mal utilisée","Un excès d'insuline, avec des hypoglycémies répétées","Un défaut de filtration du glucose par les reins, à l'effort"],"r":1,"e":"Dans le type 2, le pancréas diminue la production d'insuline et/ou l'insuline produite n'est pas bien utilisée par l'organisme.","s":9},{"q":"À partir de quel âge le diabète de type 2 survient-il généralement selon le cours ?","o":["Après 18 ans","Après 25 ans","Après 35 ans","Après 65 ans"],"r":2,"e":"Il survient généralement chez les adultes après 35 ans ; il est donc généralement acquis, bien qu'il présente des facteurs de prédisposition génétique.","s":9},{"q":"Pourquoi le diagnostic du diabète de type 2 est-il souvent tardif ?","o":["Les symptômes débutent lentement et passent inaperçus","La glycémie reste normale pendant des années, même à jeun","Il n'existe aucun test diagnostique fiable","Il ne donne jamais aucun symptôme, à aucun stade"],"r":0,"e":"Le début des symptômes est lent et ils peuvent passer inaperçus pendant de longues périodes, rendant difficiles le diagnostic et le traitement.","s":9},{"q":"Comment le diabète de type 2 est-il majoritairement traité ?","o":["Par l'insuline, exclusivement et à vie","Par comprimés, parfois par insuline","Par une chirurgie du pancréas","Sans aucun traitement, à vie"],"r":1,"e":"Appelé diabète insulino-non-dépendant, il est majoritairement traité par comprimés, bien qu'il puisse aussi parfois être traité par insuline.","s":9},{"q":"Qu'est-ce que le diabète gestationnel ?","o":["Un diabète de type 1, révélé à l'accouchement","Une hyperglycémie de grossesse, sans diabète antérieur","Une hypoglycémie du nouveau-né, dans ses premières heures","Un diabète transmis par le père, génétique"],"r":1,"e":"Le diabète gestationnel est la condition dans laquelle une femme sans diabète présente des taux élevés de glucose dans le sang pendant la grossesse ; il manifeste généralement peu de symptômes. Il donne généralement peu de symptômes.","s":9},{"q":"Quels sont les symptômes cardinaux du diabète cités en premier dans le cours ?","o":["Soif, polyurie, vision trouble, perte de poids","Fièvre, frissons, douleurs lombaires, brûlures urinaires","Constipation, frilosité, bradycardie","Vergetures, acné, dépôts de graisse"],"r":0,"e":"Les symptômes sont la soif, la polyurie, la vision trouble et la perte de poids.","s":9},{"q":"À quoi peut conduire un diabète grave non traité de façon adéquate ?","o":["À une simple fatigue passagère, sans gravité","À la léthargie, au coma, à la mort","À une hyperthyroïdie, avec un goitre","À une lithiase rénale, avec des coliques"],"r":1,"e":"Dans les cas les plus graves, le tableau peut évoluer vers la léthargie, le coma et, sans traitement adéquat, la mort.","s":9},{"q":"Sur quoi repose principalement le diagnostic du diabète ?","o":["Sur une biopsie du pancréas, sous scanner","Sur la glycémie à jeun, dans le sang ou le plasma","Sur l'échographie abdominale, du pancréas","Sur le dosage de la TSH et des hormones thyroïdiennes"],"r":1,"e":"Le diagnostic repose sur les concentrations de glucose dans le sang/plasma à jeun, dont les valeurs diagnostiques ont été modifiées.","s":9},{"q":"Quel antidiabétique oral est cité nommément dans le cours ?","o":["La lévothyroxine","La metformine","La dexaméthasone","L'atorvastatine"],"r":1,"e":"Parmi les antidiabétiques oraux, la metformine est citée, aux côtés de l'insuline pour la médication.","s":9},{"q":"Quels sont les quatre axes du traitement du diabète ?","o":["Régime, exercice physique, médication et insuline","Repos strict, régime hyperglucidique et chirurgie","Corticoïdes, radiothérapie et diététique","Dialyse, greffe et immunosuppression"],"r":0,"e":"Le traitement dépend du type et associe régime, exercice physique, médication (antidiabétiques oraux comme la metformine) et insuline.","s":9},{"q":"Laquelle de ces complications est une complication AIGUË du diabète ?","o":["La rétinopathie diabétique","L'acidocétose diabétique","La néphropathie diabétique","Le pied diabétique"],"r":1,"e":"Les complications aiguës sont l'hypoglycémie, l'acidocétose diabétique, le syndrome hyperglycémique hyperosmolaire et l'acidose lactique.","s":9},{"q":"Quelle complication aiguë associe hyperglycémie majeure et déshydratation ?","o":["L'hypoglycémie sévère, avec un coma","Le syndrome hyperosmolaire","L'acidose lactique, sous metformine","La rétinopathie proliférante"],"r":1,"e":"Le syndrome hyperglycémique hyperosmolaire figure parmi les quatre complications aiguës citées, avec l'hypoglycémie, l'acidocétose et l'acidose lactique. Il s'agit du syndrome hyperglycémique hyperosmolaire.","s":9},{"q":"À quoi sont associées, dans la majorité des cas, les complications aiguës du diabète ?","o":["À une maladie intercurrente ou à un échec du traitement","À une activité physique excessive, chez le sportif d'endurance","À une cause génétique isolée, héréditaire","À un excès de sommeil, prolongé et répété"],"r":0,"e":"Elles sont cause de recours aux urgences et d'hospitalisation, et sont associées le plus souvent à des intercurrences médicales et/ou des échecs thérapeutiques.","s":9},{"q":"Qu'est-ce que la rétinopathie diabétique ?","o":["Une infection de la conjonctive, d'origine bactérienne","Des lésions des vaisseaux de la rétine, avec perte de vision","Un décollement de la rétine, après un traumatisme","Une cataracte congénitale, dès la naissance"],"r":1,"e":"La rétinopathie diabétique correspond à des altérations vasculaires de la rétine, qui peuvent conduire à une perte partielle ou totale de la vision. La perte de vision peut être partielle ou totale.","s":9},{"q":"Quelle conséquence tensionnelle la néphropathie diabétique peut-elle entraîner ?","o":["Une hypotension chronique","Une hypertension","Une bradycardie","Une hypothermie"],"r":1,"e":"La néphropathie diabétique correspond à des altérations des vaisseaux des reins qui compromettent l'élimination de substances, pouvant conduire à l'hypertension.","s":9},{"q":"Quel enchaînement décrit le pied diabétique ?","o":["Sensibilité altérée, plaies, infection, risque d'amputation","Douleur intense à la marche, puis guérison spontanée","Œdème isolé du pied, sans aucune conséquence durable","Fracture de fatigue, puis consolidation rapide et complète"],"r":0,"e":"Les altérations de la sensibilité conduisent à des plaies ; les altérations de la cicatrisation augmentent les infections ; inflammation, infection et plaie ouverte peuvent conduire à l'amputation. La cicatrisation est aussi altérée.","s":9},{"q":"Par quel mécanisme le diabète favorise-t-il l'infarctus du myocarde et les AVC ?","o":["Par une hypercoagulabilité isolée","Parce qu'il favorise l'athérosclérose","Par une hypotension chronique, de repos","Par une carence en fer, avec une anémie chronique"],"r":1,"e":"Le cours indique que le diabète est à l'origine de l'athérosclérose, elle-même cause d'infarctus du myocarde et d'accidents vasculaires cérébraux.","s":9},{"q":"Pourquoi le diabétique est-il plus sujet aux infections ?","o":["Le glucose sanguin en excès déprime l'immunité","Il produit trop d'anticorps inefficaces","Son pH sanguin est trop élevé en permanence","Il a une hyperthermie permanente, modérée"],"r":0,"e":"L'augmentation du glucose sanguin peut déprimer le système immunitaire ; il faut prêter attention notamment à la bouche et aux infections vaginales.","s":9},{"q":"À quels sièges d'infection le cours demande-t-il de prêter une attention particulière ?","o":["Aux oreilles et aux sinus de la face","À la bouche et aux infections vaginales","Aux articulations et aux tendons des membres","Aux voies biliaires et au pancréas"],"r":1,"e":"Le cours précise qu'il faut prêter attention à la bouche et aux infections vaginales.","s":9},{"q":"Quelle atteinte du système nerveux le diabète provoque-t-il ?","o":["Une sclérose en plaques, avec des poussées successives","La neuropathie diabétique, sensitive et motrice","Une myasthénie, avec une fatigabilité musculaire","Une méningite chronique, d'origine infectieuse"],"r":1,"e":"La neuropathie diabétique correspond à des altérations du système nerveux, responsable des mouvements, du toucher, de la parole et du raisonnement. Elle altère le système nerveux responsable des mouvements, du toucher, de la parole et du raisonnement.","s":9},{"q":"Quel élément différencie le début clinique du type 1 et du type 2 ?","o":["Le type 1 débute vite, le type 2 lentement et en silence","Les deux débutent de la même façon, lentement et sans symptôme","Le type 2 débute par un coma, le type 1 lentement","Le type 1 reste asymptomatique, le type 2 débute vite"],"r":0,"e":"Le type 1 a un début soudain et une évolution rapide ; dans le type 2, le début est lent et les symptômes peuvent passer inaperçus pendant de longues périodes.","s":9},{"q":"Quelle est la conséquence à long terme du diabète sucré rappelée par la définition du cours ?","o":["Une guérison spontanée, après dix ans d'évolution","La défaillance de plusieurs organes","Une simple intolérance alimentaire","Une hypertrophie musculaire, généralisée"],"r":1,"e":"Les effets du diabète sucré à long terme incluent la dysfonction et la défaillance de plusieurs organes. On parle de dysfonction puis de défaillance des organes.","s":9},{"q":"L'insuline et le glucagon forment un couple hormonal :","o":["Synergique : les deux hormones font baisser la glycémie","Antagoniste : l'une baisse et l'autre élève la glycémie","Sans interaction : chacune agit sur son propre organe","Hépatique : les deux sont produites par le foie"],"r":1,"e":"L'insuline fait entrer le glucose dans les cellules et le met en réserve ; le glucagon mobilise les réserves hépatiques. L'insuline est hypoglycémiante, le glucagon hyperglycémiant.","s":9},{"q":"Le diabète sucré est décrit comme un désordre métabolique :","o":["D'étiologie unique","D'étiologie multiple","Toujours génétique","Toujours acquis"],"r":1,"e":"Il se caractérise par une hyperglycémie chronique avec troubles du métabolisme des glucides, lipides et protéines.","s":9},{"q":"Le diabète de type 1 touche typiquement :","o":["Les enfants, adolescents et jeunes adultes","Les adultes, après 35 ans, en surpoids","Les femmes enceintes, au troisième trimestre surtout","Les personnes âgées, exclusivement"],"r":0,"e":"Le type 2 survient généralement après 35 ans, avec un début lent, alors que le type 1 a une survenue rapide.","s":9},{"q":"Le diabète de type 2 est qualifié d'acquis :","o":["Sans aucune composante héréditaire, chez quiconque","Mais avec une prédisposition génétique","Uniquement chez l'enfant, avant 10 ans","Uniquement après 60 ans, chez l'obèse"],"r":1,"e":"Le type 1 résulte, lui, de la destruction des cellules pancréatiques productrices d'insuline.","s":9},{"q":"Le diabète gestationnel se caractérise par :","o":["Une hyperglycémie de grossesse, sans diabète antérieur","Un coma hyperglycémique, au troisième trimestre de grossesse","Une insulino-dépendance définitive, après l'accouchement","Une hypoglycémie chronique, à jeun, chez la mère"],"r":0,"e":"Sa pauvreté symptomatique explique le recours au dépistage systématique pendant la grossesse. Il donne généralement peu de symptômes.","s":9},{"q":"Parmi les symptômes cardinaux du diabète, le cours cite en premier :","o":["Soif, polyurie, vision trouble, perte de poids","Fièvre, frissons, sueurs nocturnes, douleurs diffuses","Douleur abdominale, nausées, vomissements","Céphalées, vertiges, acouphènes"],"r":0,"e":"La liste complète ajoute bouche sèche, malaise, fatigue, augmentation de l'appétit et augmentation des mictions et de leur volume.","s":9},{"q":"Dans les cas les plus graves de diabète non traité, le tableau peut évoluer vers :","o":["Une simple fatigue, passagère","La léthargie, le coma et la mort","Une hypoglycémie chronique, avec des malaises","Une rémission spontanée, durable"],"r":1,"e":"Dans le type 1, le coma hyperglycémique peut survenir en quelques jours.","s":9},{"q":"Le diagnostic du diabète repose principalement sur :","o":["La glycémie à jeun, dans le sang ou le plasma","L'hémogramme, avec la formule leucocytaire complète","L'échographie du pancréas, à jeun","Le dosage du glucagon et du peptide C"],"r":0,"e":"Les valeurs seuils ont été modifiées au fil des recommandations successives.","s":9},{"q":"L'exercice physique intervient dans le traitement du diabète parce qu'il :","o":["Diminue l'appétit, surtout le soir","Améliore la sensibilité à l'insuline","Augmente la production d'insuline","Réduit la soif, en hydratant mieux"],"r":1,"e":"C'est le levier direct du kinésithérapeute, à côté du régime, des antidiabétiques oraux et de l'insuline. Il augmente aussi la dépense énergétique.","s":9},{"q":"Dans le diabète de type 1, l'insulinothérapie est :","o":["Optionnelle","Instaurée d'emblée et à vie","Réservée aux complications","Remplacée par la metformine"],"r":1,"e":"Dans le type 2, on débute par des mesures hygiéno-diététiques puis des comprimés, l'insuline n'étant parfois que secondairement nécessaire.","s":9},{"q":"L'acidocétose diabétique résulte :","o":["D'une carence profonde en insuline, avec cétose","D'un excès d'insuline, après une injection mal dosée","D'une déshydratation isolée, à la chaleur","D'une accumulation de lactate, à l'effort"],"r":0,"e":"Elle est typique du type 1 ; le syndrome hyperglycémique hyperosmolaire concerne plutôt le type 2 du sujet âgé. Des corps cétoniques sont produits.","s":9},{"q":"Quelle complication aiguë est la plus fréquente en séance de rééducation ?","o":["L'acidocétose","L'hypoglycémie","Le syndrome hyperosmolaire","L'acidose lactique"],"r":1,"e":"Elle résulte d'un excès de traitement, d'un repas sauté ou d'un effort imprévu — d'où la nécessité de disposer d'un resucrage.","s":9},{"q":"L'acidose lactique correspond à :","o":["Une accumulation de lactate","Une production de corps cétoniques","Une hyperosmolarité","Une hypoglycémie profonde"],"r":0,"e":"Elle figure parmi les quatre complications aiguës motivant un recours aux urgences et une hospitalisation.","s":9},{"q":"La rétinopathie diabétique résulte :","o":["D'altérations vasculaires de la rétine","D'une cataracte, du cristallin","D'une compression du nerf optique","D'une infection de l'œil, chronique"],"r":0,"e":"Elle peut conduire à une perte partielle ou totale de la vision.","s":9},{"q":"La néphropathie diabétique résulte :","o":["D'une infection urinaire chronique","D'une atteinte des vaisseaux des reins","D'une lithiase, avec obstruction des voies urinaires","D'une obstruction de l'uretère"],"r":1,"e":"Elle peut conduire à l'hypertension artérielle et, à terme, à l'insuffisance rénale. L'élimination des substances est alors compromise.","s":9},{"q":"Le pied diabétique combine :","o":["Une sensibilité altérée et une cicatrisation altérée","Une simple sécheresse cutanée, sans plaie","Une atteinte purement vasculaire, sans aucune atteinte nerveuse","Une déformation osseuse isolée, du médio-pied"],"r":0,"e":"L'inflammation, l'infection et la plaie ouverte peuvent conduire à l'amputation — d'où l'inspection des pieds à chaque prise en charge. Les plaies s'infectent plus facilement.","s":9},{"q":"Le diabète favorise l'infarctus du myocarde et l'AVC parce qu'il :","o":["Provoque une hypertension isolée","Est à l'origine de l'athérosclérose","Augmente la viscosité sanguine seule","Déprime l'immunité"],"r":1,"e":"Ces atteintes sont regroupées sous le terme de complications macrovasculaires, avec l'artériopathie.","s":9},{"q":"Les complications microvasculaires du diabète regroupent :","o":["Rétinopathie, néphropathie, neuropathie","Infarctus, accident vasculaire, artériopathie","Artériopathie, claudication, ulcère","Infections, mycoses, abcès cutanés"],"r":0,"e":"Infarctus du myocarde, AVC et artériopathie constituent, eux, les complications macrovasculaires. Le pied diabétique découle de la neuropathie.","s":9},{"q":"Le diabétique est plus sujet aux infections car :","o":["L'excès de glucose sanguin déprime l'immunité","Il consulte moins, et plus tard","Son alimentation est déséquilibrée","Ses vaisseaux sont dilatés, avec une stase cutanée"],"r":0,"e":"Une attention particulière est demandée à la bouche et aux infections vaginales.","s":9},{"q":"La neuropathie diabétique touche un système nerveux responsable :","o":["Des mouvements, du toucher, de la parole, du raisonnement","De la seule sensibilité tactile, superficielle","De la seule motricité, volontaire et automatique, du tronc","De la vision, des couleurs et du relief"],"r":0,"e":"Elle se traduit par des troubles à la fois sensitifs et moteurs, et sous-tend le pied diabétique.","s":9},{"q":"Quels types de neurotransmetteurs assurent le traitement de l'information selon le cours ?","o":["Uniquement les excitateurs","Les excitateurs et les inhibiteurs","Uniquement les inhibiteurs","Aucun : le traitement est purement électrique"],"r":1,"e":"Le traitement de l'information repose sur des neurotransmetteurs excitateurs et inhibiteurs.","s":10},{"q":"Que pose la théorie stress-diathèse ?","o":["La pathologie mentale serait purement génétique","Génétique et environnement agissent ensemble","Seul l'environnement compterait, dès l'enfance","La mémoire ne jouerait aucun rôle, à aucun âge"],"r":1,"e":"La Stress–Diathesis Theory repose sur l'interaction entre génétique, environnement interne et externe et mémoire, déterminant la perception de la réalité et le phénomène d'apprentissage. Cette interaction détermine la perception de la réalité et l'apprentissage.","s":10},{"q":"Quel élément module la consolidation de la mémoire selon le cours ?","o":["Les émotions","La température corporelle","La glycémie","La pression artérielle"],"r":0,"e":"Le cours relie explicitement la consolidation de la mémoire aux émotions.","s":10},{"q":"Quelles pathologies relèvent des altérations cognitivo-comportementales ?","o":["Dépression, trouble bipolaire, cyclothymie, dysthymie","Schizophrénie, psychose, tableaux démentiels","Attaques de panique, phobies, anxiété","Le trouble obsessionnel, uniquement"],"r":1,"e":"Les altérations cognitivo-comportementales regroupent la schizophrénie, la psychose et les tableaux démentiels.","s":10},{"q":"Qu'affectent les altérations cognitivo-comportementales ?","o":["Les pensées, émotions, perceptions et comportements","La seule motricité fine, des doigts et des mains","Le seul sommeil, et son rythme circadien","Le seul appétit, avec une prise de poids"],"r":0,"e":"Elles affectent le traitement par la personne des pensées, émotions, perceptions et comportements, en interférant avec le filtre du stimulus de l'environnement. Elles interfèrent avec le filtre du stimulus de l'environnement.","s":10},{"q":"À quel état du système nerveux autonome la dépression majeure est-elle associée dans le cours ?","o":["Au fight","Au flight","Au freeze","À aucun état particulier"],"r":2,"e":"La dépression majeure est associée au SNA en freeze ; le trouble bipolaire fluctue entre freeze et flight.","s":10},{"q":"Comment le cours caractérise-t-il le trouble bipolaire sur le plan neurovégétatif ?","o":["Un freeze permanent, sans fluctuation","Une fluctuation entre freeze et flight","Un fight continu, avec une agressivité constante","Une absence de toute réponse autonome"],"r":1,"e":"Le trouble bipolaire correspond à une fluctuation entre freeze et flight.","s":10},{"q":"Comment définit-on la psychose ?","o":["Une simple baisse de l'humeur, passagère, sans aucun délire","Des délires, des hallucinations, une perception altérée","Une perte de mémoire isolée, sans délire","Une peur irrationnelle des lieux publics"],"r":1,"e":"La psychose associe délires et hallucinations à des altérations comportementales et du discours, avec désorganisation et distorsions dans l'évaluation ou la perception de la réalité. S'y ajoutent des altérations du comportement et du discours, avec désorganisation.","s":10},{"q":"Quels traits caractérisent la psychose paranoïde ?","o":["Ralentissement et apathie, sans hostilité","Projections fictives, hostilité, confiance excessive","Désorientation dans le temps et l'espace, confusion fluctuante","Auto-punition et culpabilité, sans délire"],"r":1,"e":"La psychose paranoïde associe projections fictives, hostilité et excès de confiance en soi.","s":10},{"q":"Quels traits caractérisent la psychose dépressive ?","o":["Excès de confiance en soi, euphorie","Ralentissement, apathie, culpabilité","Hostilité, projections fictives","Désorganisation conceptuelle, discours incohérent"],"r":1,"e":"La psychose dépressive associe ralentissement et apathie, auto-punition et culpabilité. L'auto-punition s'y associe.","s":10},{"q":"Que signifie étymologiquement le mot schizophrénie ?","o":["Perte de la mémoire, récente","Division de l'esprit","Excès de pensée, accélérée et désordonnée","Absence de parole, mutisme"],"r":1,"e":"Schizo signifie division et phrénie signifie esprit. Schizo = division, phrénie = esprit.","s":10},{"q":"À quel moment de la vie la schizophrénie se manifeste-t-elle ?","o":["Dans la petite enfance, uniquement","À l'adolescence ou au début de l'âge adulte","Après 65 ans, avec le déclin cognitif lié à l'âge","À la naissance, dès les premiers jours"],"r":1,"e":"C'est une pathologie mentale chronique qui se manifeste à l'adolescence ou au début de l'âge adulte, d'étiologie inconnue.","s":10},{"q":"Que reflètent les symptômes positifs de la schizophrénie ?","o":["Une perte de fonctions psychiques normales","Un excès ou un dérèglement de fonctions normales","Une amélioration clinique, sous traitement","Un effet secondaire du traitement, transitoire"],"r":1,"e":"Les symptômes positifs reflètent un excès ou un dysfonctionnement de fonctions psychiques normales : hallucinations, délires, trouble de la pensée.","s":10},{"q":"Lequel de ces éléments est un symptôme NÉGATIF de la schizophrénie ?","o":["Les hallucinations","Le délire de persécution","L'apathie et l'isolement social","Les troubles de la pensée"],"r":2,"e":"Les symptômes négatifs reflètent une perte de fonctions : manque de motivation, isolement social, difficulté à exprimer les émotions, apathie.","s":10},{"q":"Lequel de ces types de schizophrénie N'EST PAS cité dans le cours ?","o":["Catatonique","Résiduelle","Indifférenciée","Hypomaniaque"],"r":3,"e":"Les types cités sont : paranoïde, désorganisée, catatonique, indifférenciée, résiduelle et infantile.","s":10},{"q":"Sur quoi repose le diagnostic de la schizophrénie ?","o":["Sur une IRM cérébrale spécifique, avec spectroscopie","Sur l'entretien, avec le patient et ses proches","Sur une prise de sang, avec dosage hormonal","Sur une biopsie cérébrale, stéréotaxique"],"r":1,"e":"Il n'existe pas d'examen complémentaire qui aide au diagnostic ; celui-ci repose sur un ensemble de symptômes via l'entretien psychiatrique, les autres examens servant au diagnostic différentiel. Le diagnostic repose sur un ensemble de symptômes ; l'entretien est psychiatrique.","s":10},{"q":"Quelle est la durée du traitement de la schizophrénie ?","o":["Quelques semaines, en hospitalisation","Jusqu'à la disparition complète des symptômes","Toute la vie, même sans symptômes","Pendant les crises, uniquement"],"r":2,"e":"La schizophrénie nécessite un traitement tout au long de la vie, même après la disparition des symptômes.","s":10},{"q":"Quelle est la cause la plus fréquente de démence ?","o":["La démence vasculaire","La démence d'Alzheimer","La démence à corps de Lewy","La démence fronto-temporale"],"r":1,"e":"La démence d'Alzheimer est la cause la plus fréquente, représentant 50 % des cas chez les plus de 65 ans.","s":10},{"q":"Quels neurotransmetteurs diminuent dans la maladie d'Alzheimer ?","o":["La dopamine et la sérotonine","L'acétylcholine et la noradrénaline","Le GABA et le glutamate cortical","L'histamine, l'orexine et la mélatonine"],"r":1,"e":"On observe une diminution de l'acétylcholine et de la noradrénaline.","s":10},{"q":"Quelles altérations cérébrales caractérisent la maladie d'Alzheimer ?","o":["Plaques séniles, dégénérescence neurofibrillaire","Lésions démyélinisantes, multiples et périventriculaires","Infarctus lacunaires multiples, sous-corticaux","Hydrocéphalie obstructive, avec ventricules dilatés"],"r":0,"e":"Les altérations décrites sont les plaques séniles, les dégénérescences neurofibrillaires et l'atrophie du cortex frontal. S'y ajoute une atrophie du cortex frontal.","s":10},{"q":"Quels sont les symptômes les plus fréquemment inauguraux d'une démence ?","o":["Une incontinence, puis des troubles moteurs","Des oublis, une gêne au quotidien, un comportement changé","Un langage restreint, une dépendance totale pour la toilette","Des hallucinations visuelles, très précoces"],"r":1,"e":"Les symptômes inauguraux sont la difficulté de mémoire, l'incapacité dans le fonctionnement habituel et les changements de comportement. La gêne au quotidien correspond à l'incapacité dans le fonctionnement habituel.","s":10},{"q":"Quel signe caractérise la phase modérée de la démence ?","o":["L'incontinence sphinctérienne, urinaire et fécale","Une agitation vespérale, avec un manque du mot","Une perte d'initiative, isolée et discrète","Une difficulté à se reconnaître soi-même"],"r":1,"e":"Le deuxième stade associe aggravation de la mémoire, agitation surtout l'après-midi ou nocturne, manque du mot, difficulté à reconnaître les personnes et altérations de la perception. L'agitation survient l'après-midi ou la nuit.","s":10},{"q":"Quels signes appartiennent à la phase sévère de la démence ?","o":["Une perte de mémoire récente et une désorientation légère","Un langage restreint, une incontinence, une dépendance","Une baisse d'initiative isolée, discrète","De simples oublis, occasionnels et bénins"],"r":1,"e":"Le troisième stade associe difficulté d'auto-reconnaissance, langage restreint, incontinence sphinctérienne, altérations motrices et dépendance pour les activités de base quotidiennes. S'y ajoutent la difficulté d'auto-reconnaissance et des altérations motrices ; la dépendance concerne les activités de base.","s":10},{"q":"Quel est le seul moyen d'obtenir un diagnostic DÉFINITIF de démence d'Alzheimer ?","o":["L'IRM cérébrale","Le Mini-mental state","L'anatomopathologie","Le dosage sanguin de marqueurs"],"r":2,"e":"Le diagnostic définitif est anatomopathologique ; les marqueurs récents ne sont pas définitifs.","s":10},{"q":"Quel médicament spécifique est indiqué dans la phase SÉVÈRE de la démence ?","o":["La rivastigmine","La mémantine","La paroxétine","Le lithium"],"r":1,"e":"Les anticholinestérasiques comme la rivastigmine concernent les phases légère et modérée ; la mémantine est indiquée en phase sévère.","s":10},{"q":"Quelles disciplines participent à la rééducation non médicamenteuse de la démence ?","o":["Kinésithérapie, ergothérapie, orthophonie","Chirurgie, radiologie, anesthésie","Cardiologie, pneumologie, néphrologie, endocrinologie","Aucune, le traitement restant médicamenteux"],"r":0,"e":"La rééducation cognitive et physique mobilise la neuropsychologie, la kinésithérapie, l'ergothérapie et l'orthophonie, avec une approche sociale auprès des aidants. La neuropsychologie y participe aussi, avec une approche sociale auprès des aidants.","s":10},{"q":"Quelle est l'étiologie de la dépression selon le cours ?","o":["Une cause génétique unique, bien identifiée","Une cause inconnue, avec des facteurs déclenchants","Une infection virale, du système nerveux","Une carence en vitamines, d'origine alimentaire"],"r":1,"e":"L'étiologie causale directe est inconnue ; la dépression est associée à des facteurs déclenchants qui mettent en danger la sécurité et le contrôle de l'individu.","s":10},{"q":"Quelle classe médicamenteuse correspond à la paroxétine ?","o":["Les thymorégulateurs, comme le lithium","Les inhibiteurs de la recapture de la sérotonine","Les anticholinestérasiques, comme le donépézil","Les benzodiazépines, anxiolytiques"],"r":1,"e":"La paroxétine est citée comme exemple d'ISRS ; le lithium est l'exemple de thymorégulateur. Ce sont les ISRS, inhibiteurs sélectifs.","s":10},{"q":"Quel mécanisme est déclenché lors d'une attaque de panique ?","o":["La réponse sympathique de fight or flight","Un freeze parasympathique, prolongé","Une hypoglycémie brutale, par jeûne","Une élévation brutale de la mélatonine, en journée"],"r":0,"e":"Les attaques de panique sont des crises accompagnées de signes cliniques effectifs, avec déclenchement de la réponse sympathique de fight or flight.","s":10},{"q":"Comment le cours définit-il l'agoraphobie ?","o":["La peur des animaux, même inoffensifs","La peur des lieux publics, où fuir est difficile","La peur des situations sociales, de la critique","La peur des petits espaces, fermés"],"r":1,"e":"L'agoraphobie est la peur des lieux publics, où la fuite semble difficile ; les phobies sociales concernent les situations de critique ou d'exposition et les phobies spécifiques toutes les autres peurs irrationnelles.","s":10},{"q":"Quelle structure cérébrale le cours met-il en avant pour la pensée ?","o":["Le lobe occipital, siège de la vision et de la lecture","Le lobe frontal, siège du jugement et du contrôle","Le cervelet, siège de la coordination","Le tronc cérébral, siège de la vigilance"],"r":1,"e":"La complexité cérébrale repose aussi sur la connectivité intra- et interhémisphérique et sur une double division structurelle et fonctionnelle. Il assure aussi la planification.","s":10},{"q":"C'est le déséquilibre de quel élément qui sous-tend la pathologie psychiatrique ?","o":["Les neurotransmetteurs, excitateurs et inhibiteurs","Le débit sanguin cérébral, global","Les électrolytes du sang, sodium et potassium","Les hormones thyroïdiennes, en particulier la T3 et la T4"],"r":0,"e":"Ce sont eux qui assurent le traitement de l'information entre les aires spécialisées.","s":10},{"q":"Dans le modèle stress-diathèse, la « diathèse » désigne :","o":["L'environnement perçu, interne et externe","La vulnérabilité constitutionnelle, génétique","La mémoire à long terme, émotionnelle","Le stress aigu, déclenché par un événement de vie"],"r":1,"e":"Les trois pôles du modèle sont la génétique, l'environnement interne et externe, et la mémoire.","s":10},{"q":"Dans la séquence du modèle stress-diathèse, la mémoire de travail assure :","o":["La captation des stimuli, sensoriels","Le traitement immédiat de l'information","L'apprentissage durable, à long terme","La consolidation émotionnelle des souvenirs"],"r":1,"e":"Elle alimente ensuite la mémoire à long terme, dont la consolidation est modulée par les émotions.","s":10},{"q":"Les troubles anxieux atteignent principalement :","o":["Les fonctions cognitives globales, comme la mémoire","Le niveau d'alerte et la réponse d'anticipation","L'humeur et la régulation des émotions","La perception de la réalité, avec des hallucinations"],"r":1,"e":"Les altérations de l'humeur touchent la régulation émotionnelle, et les troubles neurocomportementaux les fonctions cognitives globales.","s":10},{"q":"La psychose paranoïde se caractérise par :","o":["Des projections, une hostilité, une confiance excessive","Un ralentissement, une apathie, une culpabilité","Une désorientation, dans le temps et l'espace","Une catatonie, avec des postures figées et un mutisme total"],"r":0,"e":"La psychose dépressive associe ralentissement, apathie, auto-punition et culpabilité ; la forme désorganisée/excitée associe désorganisation et désorientation. Les projections sont fictives.","s":10},{"q":"La psychose désorganisée/excitée se caractérise par :","o":["Une hostilité, avec des projections fictives sur autrui","Une désorganisation, avec une désorientation","Une culpabilité, avec une auto-punition","Un isolement social, sans autre signe"],"r":1,"e":"C'est la troisième des formes de psychose citées, aux côtés des formes paranoïde et dépressive. La désorientation est spatio-temporelle et conceptuelle.","s":10},{"q":"L'étiologie de la schizophrénie est :","o":["Purement génétique","Inconnue","Infectieuse","Toxique"],"r":1,"e":"Il s'agit d'une pathologie mentale chronique débutant à l'adolescence ou au début de l'âge adulte.","s":10},{"q":"Le délire de persécution appartient aux symptômes :","o":["Positifs de la schizophrénie","Négatifs de la schizophrénie","Cognitifs","Dépressifs"],"r":0,"e":"Les symptômes positifs reflètent un excès ou un dysfonctionnement de fonctions psychiques normales : hallucinations, délires, troubles de la pensée.","s":10},{"q":"Le manque de motivation et l'isolement social appartiennent aux symptômes :","o":["Positifs, par excès de fonctions normales","Négatifs, par perte de fonctions","Cognitifs, par trouble de l'attention","Agressifs, par hostilité envers autrui"],"r":1,"e":"S'y ajoutent la difficulté à exprimer les émotions et l'apathie. Ils reflètent une diminution ou une perte de fonctions psychiques normales.","s":10},{"q":"Outre les symptômes positifs et négatifs, la schizophrénie comporte des symptômes :","o":["Cognitifs, agressifs, dépressifs et anxieux","Uniquement moteurs, avec des tics et une catatonie","Uniquement sensoriels, visuels et auditifs","Uniquement végétatifs, digestifs"],"r":0,"e":"Cette pluralité explique que le diagnostic repose sur un ensemble de symptômes plutôt que sur un signe isolé. Les symptômes agressifs s'accompagnent d'hostilité.","s":10},{"q":"Parmi les types de schizophrénie cités figurent :","o":["Paranoïde, désorganisée, catatonique, résiduelle","Aiguë et chronique, sans autre forme","Positive, négative et mixte, selon les symptômes dominants","Primaire et secondaire, selon la cause"],"r":0,"e":"Le diagnostic repose sur l'entretien psychiatrique avec le patient et ses proches, aucun examen complémentaire n'étant contributif. S'y ajoutent les formes indifférenciée et infantile.","s":10},{"q":"Pourquoi demande-t-on d'autres examens cliniques dans la schizophrénie ?","o":["Pour confirmer le diagnostic","Pour le diagnostic différentiel","Pour évaluer le pronostic","Pour choisir le dosage"],"r":1,"e":"Aucun examen complémentaire n'aide au diagnostic positif, même si quelques avancées neuroscientifiques sont à l'étude.","s":10},{"q":"La démence d'Alzheimer représente environ quelle proportion des démences chez les plus de 65 ans ?","o":["10 %","25 %","50 %","90 %"],"r":2,"e":"C'est la cause la plus fréquente de démence.","s":10},{"q":"Dans la maladie d'Alzheimer, on observe une diminution :","o":["De l'acétylcholine et de la noradrénaline","De la dopamine et de la sérotonine, au cortex","Du GABA et de la glycine, inhibiteurs","Du glutamate, dans l'hippocampe"],"r":0,"e":"S'y associent plaques séniles, dégénérescences neurofibrillaires et atrophie du cortex frontal.","s":10},{"q":"Les altérations cérébrales caractéristiques de la maladie d'Alzheimer sont :","o":["Des plaques séniles, une dégénérescence neurofibrillaire","Des infarctus lacunaires multiples, sous-corticaux et diffus","Une démyélinisation, en plaques périventriculaires","Une hydrocéphalie, à pression normale, avec dilatation"],"r":0,"e":"Le diagnostic définitif reste anatomopathologique. S'y ajoute une atrophie du cortex frontal.","s":10},{"q":"La phase LÉGÈRE de la démence se caractérise par :","o":["Une atteinte de la mémoire récente, une désorientation","Une agitation vespérale, avec un manque du mot","Une incontinence, urinaire et fécale","Une dépendance totale, pour toutes les activités de base"],"r":0,"e":"La phase modérée ajoute agitation vespérale ou nocturne, manque du mot et non-reconnaissance ; la phase sévère, langage restreint, incontinence et altérations motrices. La perte d'initiative en fait aussi partie.","s":10},{"q":"La phase SÉVÈRE de la démence associe :","o":["Un langage restreint, une incontinence, une dépendance","Une simple perte d'initiative, avec une apathie et un repli","Un manque du mot isolé, sans autre trouble","Une désorientation légère, dans un lieu nouveau"],"r":0,"e":"Elle succède aux phases légère et modérée dans l'évolution en trois stades décrite par le cours. Des altérations motrices s'y ajoutent ; la dépendance est totale.","s":10},{"q":"Le diagnostic DÉFINITIF de démence d'Alzheimer s'obtient :","o":["Par l'IRM","Par l'examen anatomopathologique","Par le test neuropsychologique","Par la ponction lombaire"],"r":1,"e":"Les autres examens permettent une forte présomption mais non une certitude du vivant du patient.","s":10},{"q":"Une attaque de panique correspond au déclenchement :","o":["De la réponse sympathique de fight or flight","D'un état de freeze, parasympathique","D'une hypoglycémie, par jeûne prolongé ou par insuline","D'une crise d'épilepsie, partielle"],"r":0,"e":"La dépression majeure correspond, elle, à un système nerveux autonome en freeze, et le trouble bipolaire à une fluctuation entre freeze et flight.","s":10},{"q":"Comment le cours définit-il le stress ?","o":["Une maladie psychiatrique, bien caractérisée","Une réponse physiologique et comportementale normale","Un trouble exclusivement hormonal, lié au cortisol en excès","Une conséquence directe de l'insomnie chronique"],"r":1,"e":"Le stress est une réponse physiologique et comportementale normale ; c'est son caractère chronique et négatif qui le rend pathologique.","s":11},{"q":"Quelle branche du système nerveux autonome est impliquée dans la réponse au stress ?","o":["Le système parasympathique","Le système sympathique","Le système entérique exclusivement","Aucune : la réponse est purement hormonale"],"r":1,"e":"La physiologie du stress repose sur le SNA sympathique et le rapport adrénaline/cortisol.","s":11},{"q":"Quel rapport hormonal caractérise la physiologie du stress selon le cours ?","o":["Insuline / glucagon","Adrénaline / cortisol","TSH / T4","Leptine / ghréline"],"r":1,"e":"Le cours met en avant le rapport adrénaline/cortisol : l'adrénaline pour la réponse immédiate, le cortisol pour la réponse prolongée.","s":11},{"q":"Quelle particularité présente la sécrétion de cortisol ?","o":["Elle est constante sur 24 heures","Elle suit une courbe circadienne","Elle n'existe que la nuit","Elle dépend uniquement des repas"],"r":1,"e":"Le cours présente la « courbe du cortisol », c'est-à-dire son profil de sécrétion circadien.","s":11},{"q":"Quelle situation crée la dysfonction liée au stress ?","o":["Un stress aigu, isolé et bref","Un stress chronique et négatif","Un stress positif, ponctuel","L'absence totale de stress"],"r":1,"e":"La dysfonction résulte de l'exposition à un stress chronique et négatif.","s":11},{"q":"Où la leptine est-elle produite ?","o":["Dans le pancréas endocrine","Dans les cellules graisseuses","Dans la thyroïde, sous l'effet de la TSH","Dans l'hypophyse antérieure"],"r":1,"e":"La leptine est une hormone qui régule l'appétit et le métabolisme énergétique, produite dans les cellules graisseuses.","s":11},{"q":"Quel est le rôle de la leptine ?","o":["Réguler l'appétit et le métabolisme énergétique","Réguler la glycémie en abaissant le glucose","Stimuler la thyroïde","Déclencher le sommeil"],"r":0,"e":"La leptine régule l'appétit et le métabolisme énergétique.","s":11},{"q":"Quel enchaînement décrit le cercle vicieux de la leptine ?","o":["Plus de leptine, résistance, faim, prise de poids","Moins de leptine, plus de satiété, perte de poids","Plus de leptine, plus de sensibilité, perte d'appétit","La leptine n'a aucun effet, ni sur la faim ni sur le poids"],"r":0,"e":"L'augmentation des cellules graisseuses augmente la leptine, ce qui entraîne une résistance cérébrale, une sensibilité diminuée, un appétit accru et une prise de poids. Le cercle part de l'augmentation des cellules graisseuses ; la résistance est cérébrale et la sensibilité diminue.","s":11},{"q":"Quel symptôme physique du stress concerne directement le kinésithérapeute ?","o":["La douleur dorsale et la douleur musculaire","La cécité brutale, d'un seul œil","La surdité progressive, avec des acouphènes aigus","L'anosmie, la perte de l'odorat"],"r":0,"e":"Le cours liste explicitement la douleur dorsale et la douleur musculaire parmi les symptômes physiques du stress.","s":11},{"q":"Quel trouble digestif figure parmi les symptômes du stress ?","o":["Une cirrhose, avec une ascite et un ictère","Des brûlures d'estomac, une diarrhée","Une hépatite virale, chronique","Une lithiase biliaire, avec des coliques"],"r":1,"e":"Les troubles gastro-intestinaux du stress incluent brûlures d'estomac, gastralgie, diarrhée ou constipation. La gastralgie et la constipation en font aussi partie.","s":11},{"q":"Quel effet le stress a-t-il sur le système immunitaire ?","o":["Il le renforce","Il le fragilise","Il n'a aucun effet","Il le supprime totalement"],"r":1,"e":"La fragilité du système immunitaire fait partie des symptômes du stress.","s":11},{"q":"Quel comportement de tentative de détente est cité parmi les symptômes du stress ?","o":["La lecture prolongée, le soir","Le café, l'alcool, le tabac ou les drogues","La pratique du yoga, de la méditation guidée","Les siestes courtes, en journée"],"r":1,"e":"Le cours cite l'usage de café, d'alcool, de tabac ou de drogues pour tenter de se détendre.","s":11},{"q":"Quelles sont les trois composantes du traitement du stress ?","o":["Chirurgie, radiothérapie, repos complet en milieu hospitalier","Hygiène de vie, gestion du stress, médicaments si besoin","Isolement, jeûne, méditation obligatoire","Antibiotiques, corticoïdes, arrêt de travail"],"r":1,"e":"Le traitement associe modes de vie sains, techniques de gestion du stress et médicaments selon l'expression pathologique. Les médicaments sont adaptés à l'expression pathologique.","s":11},{"q":"Que signifie NREM ?","o":["New Rapid Eye Movement","Non Rapid Eye Movement","Nocturnal Restorative Eye Motion","Neural Rest and Eye Movement Modulation"],"r":1,"e":"NREM signifie Non Rapid Eye Movement, soit mouvement non rapide des yeux ; l'autre grand type est le REM. Soit mouvement non rapide des yeux.","s":11},{"q":"Quel effet l'obscurité a-t-elle sur la mélatonine ?","o":["Elle en diminue la production, la nuit","Elle augmente sa production, avant le sommeil","Elle n'a aucun effet, la sécrétion restant constante","Elle la transforme en cortisol, au réveil"],"r":1,"e":"L'obscurité fait que le corps produit plus de mélatonine ; les taux augmentent en fin de journée après le coucher du soleil et restent élevés la nuit. Elle signale au corps de se préparer au sommeil.","s":11},{"q":"Pourquoi nous réveillons-nous naturellement au lever du soleil ?","o":["La lumière fait chuter la mélatonine","Le cortisol s'effondre au matin","La température corporelle baisse","La leptine augmente, avec la faim du matin"],"r":0,"e":"La lumière diminue la production de mélatonine ; en début de matinée, quand le soleil se lève, les taux chutent, ce qui provoque le réveil naturel.","s":11},{"q":"À quels niveaux le sommeil agit-il selon le cours ?","o":["Cérébral, musculaire et cellulaire","Cérébral seulement, au cortex","Musculaire seulement, au repos","Digestif seulement, par le jeûne nocturne"],"r":0,"e":"Le sommeil agit à plusieurs niveaux : cérébral, musculaire et cellulaire.","s":11},{"q":"Quelle fonction du sommeil concerne l'apprentissage ?","o":["La régulation de la température corporelle","La formation et la consolidation de la mémoire","La conservation de l'énergie","La régulation du métabolisme"],"r":1,"e":"La formation et la consolidation de la mémoire font partie des fonctions du sommeil, avec le développement et la maturation cérébrale.","s":11},{"q":"Quelle fonction du sommeil est liée à la récupération tissulaire ?","o":["L'optimisation de l'immunité et de la régénération","Le maintien de la veille, en journée","La régulation du métabolisme et de l'appétit, la nuit","Le développement cérébral, chez l'enfant"],"r":0,"e":"Le sommeil optimise le système immunitaire et le processus de régénération.","s":11},{"q":"Quels troubles relèvent de l'hypersomnie diurne ?","o":["Le somnambulisme, les cauchemars, les terreurs nocturnes","L'apnée du sommeil, la narcolepsie, les jambes sans repos","Le jet-lag, le travail posté, le retard de phase du sommeil","L'insomnie d'endormissement, de maintien"],"r":1,"e":"L'hypersomnie diurne regroupe l'apnée obstructive du sommeil, la narcolepsie et le syndrome des jambes sans repos. L'apnée est obstructive.","s":11},{"q":"Quel neuropeptide est en cause dans la narcolepsie ?","o":["La mélatonine, à taux élevés","L'orexine, à faibles taux","La leptine, à taux élevés","La sérotonine, en excès"],"r":1,"e":"La narcolepsie est liée à de faibles taux du neuropeptide orexine.","s":11},{"q":"Lequel de ces éléments est un trouble circadien ?","o":["Le somnambulisme","Le jet-lag","Les terreurs nocturnes","L'apnée obstructive du sommeil"],"r":1,"e":"Les troubles circadiens comprennent le jet-lag, le travail posté et la privation de sommeil.","s":11},{"q":"Quels troubles sont classés parmi les parasomnies ?","o":["Cauchemars, terreurs nocturnes, somnambulisme","Apnée du sommeil, narcolepsie, jambes sans repos","Jet-lag, travail posté, avance de phase","Insomnie, hypersomnie, somnolence diurne"],"r":0,"e":"Les parasomnies comprennent les troubles du sommeil NREM, les cauchemars, les terreurs nocturnes et le somnambulisme.","s":11},{"q":"Quel type de mémoire est principalement touché dans les troubles du sommeil ?","o":["La mémoire procédurale, ancienne","La mémoire à court terme et de travail","La mémoire autobiographique, lointaine","La mémoire sémantique, des mots"],"r":1,"e":"Les troubles de la mémoire concernent principalement la mémoire à court terme et la mémoire de travail.","s":11},{"q":"Quel symptôme psychique accompagne fréquemment les troubles du sommeil ?","o":["Des hallucinations visuelles constantes","L'anxiété et la dépression","Une euphorie permanente","Une amnésie totale"],"r":1,"e":"Les symptômes incluent irritabilité, déficit de concentration, troubles de la mémoire, asthénie, modifications de l'humeur, anxiété et dépression.","s":11},{"q":"Quelle mesure non médicamenteuse fait partie du traitement des troubles du sommeil ?","o":["L'activité physique","L'alitement complet","La privation volontaire de sommeil","L'augmentation des stimulants le soir"],"r":0,"e":"Le traitement associe médicaments pour la régulation du sommeil, activité physique, adaptation de l'alimentation et action sur les facteurs déclenchants.","s":11},{"q":"Que recommande le cours concernant l'alimentation dans les troubles du sommeil ?","o":["Supprimer tout aliment solide le soir, après 18 heures","Adapter les stimulants au moment de la journée","Jeûner vingt-quatre heures, chaque semaine","Augmenter les apports en caféine, le soir"],"r":1,"e":"Il s'agit de contextualiser les aliments, notamment les stimulants, selon le moment de la journée. Le cours parle de contextualiser les aliments.","s":11},{"q":"Quel symptôme endocrinien féminin peut apparaître sous stress chronique ?","o":["Une ménopause précoce systématique","Des modifications des règles","Une grossesse extra-utérine","Une hypertrophie ovarienne"],"r":1,"e":"Les modifications des règles figurent parmi les symptômes du stress, avec la chute de cheveux et les modifications du cholestérol et des triglycérides.","s":11},{"q":"Quelle modification biologique le stress peut-il entraîner ?","o":["Une modification du cholestérol et des triglycérides","Une augmentation de l'hémoglobine, avec polyglobulie","Une baisse de la créatinine, par fonte musculaire","Une élévation de la bilirubine, avec un ictère cutané franc"],"r":0,"e":"Le cours cite la modification des taux de cholestérol et de triglycérides parmi les symptômes du stress.","s":11},{"q":"Quelle affirmation sur la mélatonine et le vieillissement est exacte selon le cours ?","o":["La mélatonine reste identique, tout au long de la vie","Sa sécrétion se modifie avec le vieillissement","La mélatonine n'existe que chez l'enfant","Le vieillissement l'augmente fortement"],"r":1,"e":"Le cours consacre une section « Sommeil et vieillissement — Mélatonine », soulignant la modification de sa sécrétion avec l'âge.","s":11},{"q":"Le cours distingue un stress positif et un stress négatif : le stress positif est :","o":["Toujours pathologique","Mobilisateur et adaptatif","Absent chez l'adulte","Synonyme d'anxiété"],"r":1,"e":"C'est l'exposition à un stress chronique et négatif qui crée la dysfonction.","s":11},{"q":"Dans la réponse au stress, l'adrénaline assure :","o":["La réponse immédiate","La réponse prolongée","La régulation circadienne","Le feedback négatif"],"r":0,"e":"Le cortisol assure la réponse prolongée ; c'est leur rapport qui caractérise l'état de stress.","s":11},{"q":"Le dérèglement des boucles de feedback de l'axe du stress a pour conséquence :","o":["D'éteindre la réponse","De pérenniser la réponse au stress","D'augmenter la leptine seule","De supprimer le cortisol"],"r":1,"e":"Le système nerveux autonome sympathique constitue par ailleurs le bras rapide de cette réponse.","s":11},{"q":"La courbe circadienne du cortisol se caractérise par :","o":["Un pic nocturne, vers trois heures du matin","Un pic matinal, puis une baisse dans la journée","Une sécrétion constante, sur vingt-quatre heures","Deux pics identiques, le matin et en fin d'après-midi"],"r":1,"e":"Cette rythmicité explique que le dosage isolé de cortisol doive tenir compte de l'heure du prélèvement.","s":11},{"q":"La leptine est produite :","o":["Par le foie, après les repas","Dans les cellules graisseuses","Par l'hypophyse antérieure","Par le pancréas endocrine"],"r":1,"e":"Elle régule l'appétit et le métabolisme énergétique.","s":11},{"q":"Dans le cercle vicieux de la leptine, des taux chroniquement élevés entraînent :","o":["Une sensibilité accrue au signal","Une résistance cérébrale à la leptine","Une diminution des cellules graisseuses","Une satiété renforcée"],"r":1,"e":"Le signal de satiété n'est alors plus entendu, d'où un appétit augmenté et une prise de poids qui entretiennent le cycle.","s":11},{"q":"Parmi les symptômes COMPORTEMENTAUX du stress, le cours cite :","o":["Négliger ses tâches, éviter, se ronger les ongles","Les céphalées de tension, en fin de journée","La tachycardie, les palpitations","La chute de cheveux, par plaques, sur le cuir chevelu"],"r":0,"e":"L'usage de café, alcool, tabac ou drogues pour tenter de se détendre en fait également partie. Il s'agit de négliger ses responsabilités, d'éviter des situations et de tics nerveux.","s":11},{"q":"Parmi les symptômes PHYSIQUES du stress, le cours cite :","o":["La douleur dorsale, la douleur musculaire","L'irritabilité, avec des colères","La chute de cheveux, par plaques","La perte de mémoire, des faits récents"],"r":0,"e":"Une rachialgie chronique résistante doit donc faire chercher la composante de stress ; l'activité physique fait partie du traitement.","s":11},{"q":"Parmi les troubles gastro-intestinaux liés au stress, le cours cite :","o":["Brûlures d'estomac, gastralgie, diarrhée","Ictère, urines foncées, prurit","Dysphagie, odynophagie, régurgitations acides","Hématémèse, méléna, anémie"],"r":0,"e":"Ils figurent dans la sphère physique, aux côtés de l'hypertension, des céphalées et de la tachycardie. La constipation en fait aussi partie.","s":11},{"q":"Parmi les symptômes SYSTÉMIQUES et endocriniens du stress figurent :","o":["Fragilité immunitaire, chute de cheveux, dyslipidémie","Angor d'effort, palpitations, syncope","Dysphagie, régurgitations, hoquet","Polyurie, polydipsie, amaigrissement, soif nocturne intense"],"r":0,"e":"S'y ajoutent les modifications de l'appétit et les troubles du sommeil, par excès ou par insomnie. Les troubles des règles et la sudation en font aussi partie.","s":11},{"q":"Les trois composantes du traitement du stress sont :","o":["Hygiène de vie, gestion du stress, médicaments si besoin","Repos, arrêt de travail prolongé, anxiolytiques au long cours","Psychothérapie exclusive, sans autre mesure","Régime, exercice intensif et chirurgie"],"r":0,"e":"L'activité physique s'inscrit dans les modes de vie sains, ce qui en fait un levier direct du kinésithérapeute. Les médicaments sont adaptés à l'expression pathologique.","s":11},{"q":"Le sigle REM signifie :","o":["Rapid Eye Movement","Reduced Energy Metabolism","Rest and Energy Mode","Rapid Emotional Memory"],"r":0,"e":"NREM signifie Non Rapid Eye Movement : ce sont les deux grands types de sommeil.","s":11},{"q":"Les taux de mélatonine commencent à augmenter :","o":["Au lever du soleil, le matin","En fin de journée, après le coucher du soleil","À midi, quand la lumière est maximale","Au milieu de la nuit seulement, vers trois heures"],"r":1,"e":"Ils restent élevés pendant la nuit et chutent en début de matinée quand le soleil se lève, ce qui provoque le réveil naturel.","s":11},{"q":"Le vieillissement s'accompagne :","o":["D'une augmentation constante de la mélatonine","D'une mélatonine modifiée, qui altère le sommeil","D'une disparition complète du sommeil REM","D'une avance de phase, sans conséquence sur le sommeil"],"r":1,"e":"C'est l'un des mécanismes expliquant les plaintes de sommeil chez la personne âgée.","s":11},{"q":"Le sommeil agit, selon le cours, aux niveaux :","o":["Cérébral, musculaire et cellulaire","Cérébral seulement, au cortex","Musculaire seulement, au repos","Digestif et rénal, par le jeûne de la nuit"],"r":0,"e":"Ses fonctions vont de la qualité de la veille à la régulation du métabolisme, en passant par la consolidation de la mémoire.","s":11},{"q":"Parmi les fonctions du sommeil, le cours cite :","o":["L'économie d'énergie et la régulation thermique","La digestion des repas, du soir surtout","La production d'insuline, par le pancréas","La filtration rénale, du plasma sanguin"],"r":0,"e":"S'y ajoutent l'optimisation du système immunitaire et du processus de régénération, ainsi que le développement et la maturation cérébrale. La température régulée est la température corporelle.","s":11},{"q":"La narcolepsie est associée à :","o":["Des taux élevés de mélatonine","De faibles taux d'orexine","Un excès de cortisol","Une carence en leptine"],"r":1,"e":"Elle appartient, avec l'apnée obstructive et le syndrome des jambes sans repos, aux hypersomnies diurnes.","s":11},{"q":"Le travail posté et le jet-lag relèvent :","o":["Des parasomnies","Des troubles circadiens","De l'insomnie","De l'hypersomnie diurne"],"r":1,"e":"La privation de sommeil complète cette catégorie ; cauchemars, terreurs nocturnes et somnambulisme relèvent des parasomnies.","s":11},{"q":"Les troubles du sommeil altèrent principalement :","o":["La mémoire à court terme et de travail","La mémoire procédurale, des gestes anciens","La mémoire sémantique, ancienne","La reconnaissance des visages"],"r":0,"e":"S'y associent irritabilité, déficit de concentration, asthénie, modifications de l'humeur, anxiété et dépression.","s":11},{"q":"L'insomnie se définit comme :","o":["Une somnolence diurne, excessive","Une difficulté à s'endormir ou à rester endormi","Un décalage du rythme circadien, par le travail de nuit","Un comportement anormal pendant le sommeil"],"r":1,"e":"C'est le trouble du sommeil le plus fréquent, distinct des hypersomnies, des troubles circadiens et des parasomnies.","s":11},{"q":"Quel mode d'action hormonale désigne une hormone agissant sur la cellule qui l'a produite ?","o":["Endocrine","Paracrine","Autocrine","Neurocrine"],"r":2,"e":"L'action autocrine s'exerce sur la cellule sécrétrice elle-même ; l'action paracrine touche les cellules voisines et l'action endocrine se fait à distance par le sang.","s":12},{"q":"Quel est le mécanisme de régulation principal du système endocrinien ?","o":["Une rétroaction négative, qui freine la sécrétion","Une stimulation en cascade, sans aucun frein en retour","Un contrôle nerveux, purement volontaire","Une régulation par le seul débit sanguin"],"r":0,"e":"Les hormones sont réglées par un système de rétroaction d'inhibition : l'hormone périphérique freine sa propre stimulation en amont. C'est un système de rétroaction d'inhibition (feedback négatif).","s":12},{"q":"Selon le cours, l'étude des maladies endocriniennes requiert :","o":["Le dosage isolé d'une seule hormone, le matin","L'intégration de la morphologie et des dosages","L'imagerie seule, scanner ou IRM, sans dosage","L'examen clinique seul, sans aucun examen"],"r":1,"e":"Le cours insiste sur l'intégration des données morphologiques avec les taux hormonaux, leurs régulateurs et les autres métabolites. Les dosages portent sur les hormones, leurs régulateurs et d'autres métabolites.","s":12},{"q":"Quelle est la cause la plus commune d'hyperthyroïdie ?","o":["Le goitre multinodulaire toxique","La maladie de Basedow","L'adénome thyroïdien","La thyroïdite post-partum"],"r":1,"e":"La maladie de Basedow est la cause la plus commune : c'est une maladie du système immunitaire où des anticorps font produire et libérer trop d'hormones thyroïdiennes.","s":12},{"q":"Qu'est-ce qui caractérise le goitre multinodulaire toxique ?","o":["Une glande atrophique, sans aucun nodule, qui sécrète peu","Une glande grosse, aux nodules qui sécrètent trop","Une destruction auto-immune de la thyroïde","Une absence congénitale de la thyroïde"],"r":1,"e":"Dans le goitre multinodulaire toxique, la thyroïde est augmentée de volume avec de multiples nodules sécrétant des quantités excessives d'hormones. Les nodules sécrètent des hormones en quantité excessive.","s":12},{"q":"Quel signe appartient à l'hyperthyroïdie ?","o":["Une constipation et une frilosité","Une tachycardie et des tremblements","Une bradycardie et une voix rauque, avec une fatigue","Une prise de poids, malgré peu d'appétit"],"r":1,"e":"L'hyperthyroïdie accélère les fonctions vitales : tachycardie, tremblements, sudation, insomnies, selles fréquentes.","s":12},{"q":"Pourquoi l'hyperthyroïdie provoque-t-elle un amaigrissement et une accélération des fonctions ?","o":["Ses hormones, qui règlent l'énergie, sont en excès","La thyroïde grossie comprime l'œsophage","Le cortisol s'effondre, par une insuffisance surrénale","L'insuline est détruite, par des anticorps"],"r":0,"e":"Les hormones thyroïdiennes régulent l'énergie du corps ; à des taux excessifs, le corps consomme l'énergie plus rapidement et de nombreuses fonctions vitales s'accélèrent.","s":12},{"q":"Quels examens d'imagerie sont utilisés dans le diagnostic de l'hyperthyroïdie ?","o":["Une IRM cérébrale et un électroencéphalogramme","L'échographie et la scintigraphie thyroïdiennes","Une radiographie du thorax, de face et de profil","Un scanner abdominal, avec injection"],"r":1,"e":"Le diagnostic associe examen clinique, dosages d'anticorps et imagerie : échographie et scintigraphie thyroïdiennes.","s":12},{"q":"Quelle option thérapeutique de l'hyperthyroïdie est décrite comme permanente car elle détruit la glande ?","o":["Les antithyroïdiens de synthèse","L'iode radioactif","La lévothyroxine","La corticothérapie"],"r":1,"e":"L'iode radioactif détruit la glande thyroïde et constitue une option de traitement permanente, notamment pour la maladie de Basedow ou les nodules hypersécrétants.","s":12},{"q":"Quelle conséquence suit presque toujours une chirurgie thyroïdienne ?","o":["Une hyperthyroïdie définitive, difficile à traiter","Un traitement substitutif hormonal, à vie","Une guérison, sans aucun traitement","Une insuffisance surrénalienne, aiguë"],"r":1,"e":"La chirurgie, rarement utilisée, retire une partie de la glande et nécessite presque toujours une substitution hormonale à vie. La substitution se fait par comprimés d'hormones thyroïdiennes.","s":12},{"q":"Où est située la glande thyroïde ?","o":["À la partie postérieure et supérieure du cou","À la partie antérieure et inférieure du cou","Dans le médiastin postérieur","Au-dessus des reins"],"r":1,"e":"La thyroïde se situe à la partie antérieure et inférieure du cou.","s":12},{"q":"Dans quel pourcentage de cas l'hypothyroïdie est-elle due à un problème hypothalamique ou hypophysaire ?","o":["Moins de 5 %","Environ 25 %","Environ 50 %","Plus de 80 %"],"r":0,"e":"Dans moins de 5 % des cas, l'hypothyroïdie provient d'un problème de l'hypothalamus ou de l'hypophyse et non de la thyroïde elle-même.","s":12},{"q":"Quelle hormone hypophysaire stimule la production d'hormones thyroïdiennes ?","o":["L'ACTH","La TSH","La FSH","La prolactine"],"r":1,"e":"L'hypothalamus stimule l'hypophyse à produire la TSH, qui induit la thyroïde à produire les hormones thyroïdiennes.","s":12},{"q":"Quel signe évoque une hypothyroïdie de l'adulte ?","o":["Une sudation excessive et des insomnies, chaque nuit","Une prise de poids sans appétit, avec frilosité","Des selles fréquentes et une tachycardie","Une perte de poids rapide, avec des tremblements"],"r":1,"e":"L'hypothyroïdie ralentit le métabolisme : fatigue, frilosité, constipation, prise de poids malgré le manque d'appétit, bradycardie, dépression. La constipation s'y associe.","s":12},{"q":"Quel signe musculo-squelettique est décrit dans l'hypothyroïdie ?","o":["Une hyperlaxité généralisée","Des crampes et une raideur musculaire","Une hypertrophie musculaire diffuse","Des fasciculations permanentes, au repos"],"r":1,"e":"Les crampes et la raideur musculaire font partie des manifestations cliniques de l'hypothyroïdie chez l'adulte.","s":12},{"q":"À quoi sert le « test du talon » réalisé en période néonatale ?","o":["À dépister le diabète de type 1","À dépister l'hypothyroïdie congénitale","À mesurer le cortisol du nouveau-né","À évaluer la fonction rénale, dès la naissance"],"r":1,"e":"Le test du talon néonatal sert à diagnostiquer les cas d'hypothyroïdie congénitale.","s":12},{"q":"Quel médicament est la forme synthétique la plus utilisée pour traiter l'hypothyroïdie ?","o":["La dexaméthasone","La lévothyroxine","La metformine","Le propranolol"],"r":1,"e":"L'hypothyroïdie se traite par des doses de substitution d'hormones thyroïdiennes, la lévothyroxine étant la forme synthétique la plus utilisée.","s":12},{"q":"Quelle hormone est en excès dans le syndrome de Cushing ?","o":["La thyroxine","Le cortisol","L'insuline","L'aldostérone"],"r":1,"e":"Le syndrome de Cushing est provoqué par une forte concentration de cortisol, également appelée hormone du stress.","s":12},{"q":"Quelle glande produit le cortisol ?","o":["La thyroïde, sous l'effet de la TSH","L'hypophyse antérieure","Les glandes surrénales","Le pancréas endocrine"],"r":2,"e":"Le cortisol est produit par les glandes surrénales, sous stimulation de l'ACTH hypophysaire. Elles sont stimulées par l'ACTH hypophysaire.","s":12},{"q":"Quel facteur est directement lié à la survenue du syndrome de Cushing ?","o":["L'usage de médicaments corticoïdes","Une carence en iode, d'origine alimentaire","L'excès d'exercice physique intense","Le tabagisme passif, chronique"],"r":0,"e":"L'usage de médicaments corticoïdes, prescrits par exemple dans l'arthrite et la polyarthrite rhumatoïde, est directement lié à la survenue du syndrome ; l'exposition chronique au stress est aussi citée.","s":12},{"q":"Quel symptôme cutané est caractéristique du syndrome de Cushing ?","o":["Un vitiligo diffus, sur le visage et les mains","Des vergetures sur l'abdomen et les cuisses","Un érythème noueux, sur les deux jambes","Un psoriasis en plaques, aux coudes"],"r":1,"e":"Les vergetures, associées à une peau fragile, une cicatrisation lente et de l'acné, font partie des symptômes du syndrome de Cushing. Les seins et les bras peuvent aussi être touchés.","s":12},{"q":"Quel test dynamique est utilisé dans le diagnostic du syndrome de Cushing ?","o":["Le test de freinage à la dexaméthasone","Le test à la metformine","L'hyperglycémie provoquée par voie orale","Le test du talon"],"r":0,"e":"Le test de freinage à la dexaméthasone, corticostéroïde semblable à celui produit par les surrénales, fait partie du bilan, avec le cortisol urinaire des 24 h, plasmatique ou salivaire et le dosage de l'ACTH.","s":12},{"q":"Que dose-t-on avec l'ACTH dans le bilan d'un syndrome de Cushing ?","o":["Une hormone rénale, qui règle la volémie et la tension","L'hormone hypophysaire qui stimule le cortisol","Une hormone thyroïdienne, libre","Une enzyme hépatique, de cytolyse"],"r":1,"e":"L'ACTH, hormone adrénocorticotrope produite par la glande pituitaire, stimule la production de cortisol ; son dosage sanguin fait partie du diagnostic. C'est l'hormone adrénocorticotrope.","s":12},{"q":"Quel est l'objectif principal du traitement du syndrome de Cushing ?","o":["Augmenter la production de cortisol","Diminuer et stabiliser le cortisol","Substituer les hormones thyroïdiennes, à vie","Réduire l'insulinorésistance"],"r":1,"e":"L'objectif est de diminuer et de stabiliser les taux de cortisol ; le traitement décrit dans le cours est uniquement médicamenteux.","s":12},{"q":"Quelle est la définition de l'obésité selon le cours ?","o":["Un IMC supérieur à 22, quel que soit le contexte","Une graisse accumulée car l'apport dépasse la dépense","Une maladie exclusivement génétique, héréditaire","Une conséquence directe de l'hypothyroïdie"],"r":1,"e":"L'obésité est l'accumulation de graisse causée presque toujours par une consommation calorique supérieure à la dépense énergétique de l'organisme.","s":12},{"q":"Comment se calcule l'Indice de Masse Corporelle ?","o":["Poids (kg) divisé par la taille (m)","Poids (kg) divisé par le carré de la taille (m)","Taille (m) divisée par le poids (kg)","Tour de taille divisé par tour de hanches"],"r":1,"e":"L'IMC se calcule en divisant le poids en kilogrammes par le carré de la taille en mètres.","s":12},{"q":"Quel type de graisse est particulièrement mis en avant dans le risque lié à l'obésité ?","o":["La graisse sous-cutanée des membres","La graisse viscérale","La graisse brune interscapulaire","La graisse péri-articulaire"],"r":1,"e":"Le cours souligne le rôle de la graisse viscérale dans les complications de l'obésité.","s":12},{"q":"Quelle technique NE fait PAS partie de la chirurgie bariatrique citée dans le cours ?","o":["L'anneau gastrique ajustable","La gastrectomie verticale","Le bypass gastrique","La cholécystectomie"],"r":3,"e":"Les techniques citées sont l'anneau gastrique ajustable, la gastrectomie verticale, le bypass gastrique et la dérivation biliopancréatique. La cholécystectomie concerne la vésicule biliaire.","s":12},{"q":"Quels sont les grands mécanismes des pathologies endocriniennes ?","o":["L'hypersécrétion seule, d'origine tumorale","Hypo ou hypersécrétion, dysfonctions diverses","Les tumeurs seules, bénignes ou malignes","Les maladies auto-immunes seules"],"r":1,"e":"Le cours classe les pathologies endocriniennes en hyposécrétion ou hypersécrétion, avec des dysfonctions métaboliques et des dysfonctions structurelles. Les dysfonctions sont métaboliques et structurelles.","s":12},{"q":"Quelle association est correcte pour l'hypothyroïdie ?","o":["Bradycardie, constipation, frilosité, peau sèche","Tachycardie, diarrhée, sudation, insomnie, agitation","Hypertension, hyperthermie, agitation","Polyurie, polydipsie, amaigrissement rapide"],"r":0,"e":"L'hypothyroïdie ralentit l'organisme : fréquence cardiaque lente, constipation, sensibilité au froid, peau et cheveux secs avec chute des cheveux. Les cheveux sont aussi secs.","s":12},{"q":"Une hormone agissant sur les cellules voisines par diffusion locale a un mode d'action :","o":["Autocrine","Paracrine","Endocrine","Neurocrine"],"r":1,"e":"Le mode autocrine agit sur la cellule sécrétrice elle-même, et le mode endocrine à distance par la circulation sanguine.","s":12},{"q":"Le rétrocontrôle négatif explique par exemple :","o":["Une TSH élevée en cas d'hypothyroïdie périphérique","Une TSH basse en cas d'hypothyroïdie périphérique","L'absence de variation de la TSH","Une TSH toujours normale"],"r":0,"e":"L'hormone périphérique freine normalement la production de son hormone stimulante en amont ; son défaut lève ce frein.","s":12},{"q":"Le goitre et l'adénome relèvent du mécanisme :","o":["D'hyposécrétion","D'hypersécrétion","De dysfonction métabolique","De dysfonction structurelle"],"r":3,"e":"L'hypothyroïdie relève de l'hyposécrétion, le syndrome de Cushing de l'hypersécrétion, et le diabète ou l'obésité d'une dysfonction métabolique.","s":12},{"q":"La maladie de Basedow résulte :","o":["D'une tumeur bénigne, sécrétante","D'anticorps qui stimulent la thyroïde","D'une carence en iode, alimentaire","D'une atteinte de l'hypophyse"],"r":1,"e":"C'est la cause la plus commune d'hyperthyroïdie ; un antécédent familial augmente le risque. La thyroïde libère alors trop d'hormones.","s":12},{"q":"Le goitre multinodulaire toxique se caractérise par :","o":["Une glande grosse, aux multiples nodules sécrétants","Un nodule unique, bénin, qui ne sécrète pas","Une atrophie de toute la glande, fibreuse","Une thyroïde normale, de volume et de structure normaux"],"r":0,"e":"L'adénome correspond, lui, à une tumeur non cancéreuse unique produisant des hormones en excès. Les nodules sécrètent en excès.","s":12},{"q":"Parmi les signes d'hyperthyroïdie, le cours cite :","o":["Insomnies, sudation, tremblements, tachycardie","Constipation, frilosité, fatigue","Bradycardie, voix rauque, peau sèche et épaissie","Prise de poids, crampes musculaires"],"r":0,"e":"S'y ajoutent oscillations émotionnelles, selles fréquentes, faiblesse musculaire, essoufflement, palpitations et chute des cheveux.","s":12},{"q":"L'accélération des fonctions vitales dans l'hyperthyroïdie s'explique par :","o":["Une dépense d'énergie accélérée par les hormones","Une vasoconstriction généralisée, par le froid ressenti","Une rétention d'eau, dans les tissus","Une hypoglycémie, chronique et sévère"],"r":0,"e":"À l'inverse, l'hypothyroïdie entraîne fatigue, frilosité et prise de poids malgré le manque d'appétit. Les hormones thyroïdiennes régulent l'énergie du corps.","s":12},{"q":"L'imagerie utilisée dans le diagnostic de l'hyperthyroïdie comprend :","o":["L'échographie et la scintigraphie thyroïdiennes","L'IRM cérébrale et hypophysaire, avec injection","La radiographie cervicale, de profil","Le scanner thoracique, sans injection"],"r":0,"e":"S'y ajoutent la palpation de la thyroïde et le dosage de certains anticorps.","s":12},{"q":"L'iode radioactif dans le traitement de l'hyperthyroïdie :","o":["Freine la glande, de façon temporaire","Détruit la glande, de façon définitive","Stimule la glande, de façon durable","Remplace les hormones, à vie"],"r":1,"e":"Il est utilisé pour la maladie de Basedow ou les nodules hypersécrétants ; la chirurgie reste rare.","s":12},{"q":"Après une chirurgie thyroïdienne, il faut presque toujours :","o":["Une substitution hormonale à vie","Une antibiothérapie prolongée","Un traitement par iode radioactif","Une immunosuppression"],"r":0,"e":"L'ablation d'une partie de la glande prive en effet l'organisme de sa production hormonale.","s":12},{"q":"La thyroïde est située :","o":["À l'avant et en bas du cou","Dans le médiastin, derrière le sternum","Au-dessus du larynx, juste sous la mandibule","En arrière de la trachée, seulement"],"r":0,"e":"Sa palpation recherche une augmentation de volume ou des nodules. Elle occupe la partie antérieure et inférieure du cou.","s":12},{"q":"Moins de 5 % des hypothyroïdies sont dues :","o":["À une maladie auto-immune, thyroïdienne","À une atteinte hypothalamique ou hypophysaire","À une chirurgie de la thyroïde","À un défaut congénital de la glande, dès la naissance"],"r":1,"e":"L'axe va de l'hypothalamus à l'hypophyse, qui produit la TSH, laquelle induit la thyroïde à produire les hormones thyroïdiennes.","s":12},{"q":"Parmi les causes d'hypothyroïdie citées figure :","o":["La chirurgie ou l'iode radioactif","La maladie de Basedow, auto-immune","Le goitre multinodulaire toxique","L'adénome thyroïdien sécrétant, toxique"],"r":0,"e":"S'y ajoutent le défaut congénital de la glande et la maladie auto-immune.","s":12},{"q":"Parmi les signes d'hypothyroïdie de l'adulte, le cours cite :","o":["Frilosité progressive, constipation, fatigue","Sudation excessive, tremblements","Tachycardie, palpitations, perte de poids rapide","Selles fréquentes, diarrhée chronique"],"r":0,"e":"S'y ajoutent crampes et raideur musculaire, prise de poids malgré le manque d'appétit, peau et cheveux secs, voix rauque, bradycardie et dépression. La sensibilité au froid s'installe progressivement, la fatigue est permanente.","s":12},{"q":"Le cortisol est produit par :","o":["L'hypophyse, directement","Les glandes surrénales","La thyroïde, par la TSH","Le pancréas endocrine"],"r":1,"e":"C'est l'hormone du stress ; son excès définit le syndrome de Cushing.","s":12},{"q":"Le facteur directement lié à la survenue du syndrome de Cushing est :","o":["L'excès de corticoïdes médicamenteux","L'alimentation, trop riche en sel","Le tabagisme, actif ou passif","L'âge avancé, après 70 ans"],"r":0,"e":"L'autre mécanisme est une production excessive endogène, d'origine tumorale.","s":12},{"q":"Parmi les signes cutanés du syndrome de Cushing figurent :","o":["Des vergetures, une peau fragile qui cicatrise mal","Un vitiligo, sur les mains et le visage","Un psoriasis en plaques, aux coudes et aux genoux, épais","Une hyperpigmentation des ongles et des plis"],"r":0,"e":"S'y ajoutent les dépôts de graisse et l'acné. Les vergetures touchent l'abdomen, les cuisses, les seins et les bras.","s":12},{"q":"Le test dynamique utilisé dans le diagnostic du syndrome de Cushing est :","o":["Le test au synacthène, de stimulation surrénale","Le test de freinage à la dexaméthasone","L'hyperglycémie provoquée par voie orale","Le test de stimulation au TRH"],"r":1,"e":"Le bilan comprend aussi le cortisol urinaire des 24 heures, le cortisol plasmatique ou salivaire et le dosage de l'ACTH.","s":12},{"q":"L'obésité est définie comme :","o":["Un IMC supérieur à 25, chez l'adulte","Une graisse accumulée car l'apport dépasse la dépense","Un excès de masse musculaire, chez le sportif de force","Une rétention d'eau, dans les tissus"],"r":1,"e":"Son diagnostic passe par l'IMC, calculé en divisant le poids en kilogrammes par le carré de la taille en mètres.","s":12},{"q":"Parmi les techniques de chirurgie bariatrique citées figurent :","o":["L'anneau, la gastrectomie verticale, le bypass","La cholécystectomie, par cœlioscopie première","La gastrostomie d'alimentation, percutanée","La fundoplicature, contre le reflux"],"r":0,"e":"Elles sont réservées à l'obésité sévère, avec les médicaments ; la graisse viscérale reste le déterminant du risque métabolique. La dérivation biliopancréatique en fait aussi partie ; l'anneau est ajustable.","s":12},{"q":"Où sont produits les spermatozoïdes ?","o":["Dans les épididymes","Dans les testicules","Dans la prostate","Dans les vésicules séminales"],"r":1,"e":"Les testicules produisent les spermatozoïdes et sont situés dans le scrotum.","s":13},{"q":"Quelle est la fonction des épididymes ?","o":["La production des spermatozoïdes","Le stockage et la maturation des spermatozoïdes","La production du liquide prostatique, alcalin, fluide","L'expulsion de l'urine, vers l'urètre"],"r":1,"e":"Les épididymes assurent le stockage et la maturation des spermatozoïdes.","s":13},{"q":"Que produisent les vésicules séminales ?","o":["Un liquide nutritif pour les spermatozoïdes","Les spermatozoïdes, par la méiose","Les hormones sexuelles masculines","L'urine, avant son passage dans l'urètre prostatique"],"r":0,"e":"Les vésicules séminales produisent une sécrétion nutritive pour la survie des spermatozoïdes. Cette sécrétion assure la survie des spermatozoïdes.","s":13},{"q":"Quel est le rôle du liquide prostatique ?","o":["Nourrir les spermatozoïdes","Faciliter le mouvement des spermatozoïdes","Neutraliser l'acidité de l'urine, dans la vessie","Produire la testostérone, localement"],"r":1,"e":"La prostate produit le liquide prostatique, sécrétion qui facilite le mouvement des spermatozoïdes ; avec la sécrétion des vésicules séminales, ils forment le sperme.","s":13},{"q":"Qu'est-ce que le phimosis ?","o":["Une ouverture anormale de l'urètre, sur la face ventrale","Un excès de peau qui empêche de découvrir le gland","Une varice des veines du scrotum, unilatérale","Une inflammation aiguë de la prostate"],"r":1,"e":"Le phimosis est l'excès de peau qui recouvre le gland du pénis, gênant ou empêchant son exposition.","s":13},{"q":"Qu'est-ce que la varicocèle ?","o":["Une tumeur du testicule, germinale et maligne","Des varices sur les veines du scrotum","Du liquide accumulé autour du testicule","Une torsion du cordon spermatique"],"r":1,"e":"La varicocèle désigne la formation de varices sur les veines de la région du scrotum, où sont logés les testicules.","s":13},{"q":"Quelles formes de prostatite le cours distingue-t-il ?","o":["Bactérienne aiguë ou chronique, non bactérienne","Virale ou fongique, aiguë ou chronique","Traumatique, tumorale ou médicamenteuse","Congénitale ou acquise, selon l'âge de la survenue"],"r":0,"e":"Le cours distingue la prostatite bactérienne aiguë, la prostatite bactérienne chronique et la prostatite non bactérienne chronique. La forme non bactérienne est chronique.","s":13},{"q":"Dans quelle portion de la prostate apparaissent les nodules de l'hypertrophie bénigne ?","o":["Dans la portion périphérique","Dans la portion interne, péri-urétrale","Dans la capsule, en surface","Au niveau de l'apex seulement, près du sphincter"],"r":1,"e":"Les nodules de taille variable apparaissent dans la portion interne, péri-urétrale, de la prostate.","s":13},{"q":"De quoi sont composés les nodules de l'hyperplasie bénigne de la prostate ?","o":["De tissu adipeux, uniquement","De glandes et de stroma fibromusculaire","De cellules cancéreuses, infiltrantes","De calcifications, en amas"],"r":1,"e":"Les nodules sont composés de glandes en prolifération et de stroma fibromusculaire ; l'épithélium glandulaire hyperplasique peut former des papilles irrégulières. Les glandes sont en prolifération.","s":13},{"q":"Quelle relation existe entre l'hyperplasie nodulaire et le carcinome de la prostate ?","o":["L'hyperplasie évolue toujours en cancer","Aucune relation n'a été établie entre les deux","L'hyperplasie protège du cancer","L'hyperplasie est une forme débutante de cancer"],"r":1,"e":"Le cours indique explicitement qu'aucune relation n'a été établie entre l'hyperplasie nodulaire et le carcinome de la prostate.","s":13},{"q":"Quelle est la prévalence de l'hypertrophie bénigne de la prostate à 70 ans ?","o":["20 %","50 %","70 %","90 %"],"r":3,"e":"L'HBP concerne 20 % des hommes à 40 ans, 70 % à 60 ans et 90 % à 70 ans.","s":13},{"q":"Où a lieu la fécondation ?","o":["Dans l'utérus, au niveau du fond","Dans les trompes de Fallope","Dans les ovaires, à l'ovulation","Dans le vagin, près du col"],"r":1,"e":"Les trompes de Fallope sont des oviductes qui conduisent les ovules jusqu'à l'utérus ; c'est là qu'a lieu la fécondation.","s":13},{"q":"À quoi le cours compare-t-il la taille des ovaires ?","o":["À une poire","À une amande","À une noix","À un citron"],"r":1,"e":"Les ovaires ont la taille d'une amande ; l'utérus, lui, a la taille d'une poire.","s":13},{"q":"À quel moment de la gestation l'utérus du fœtus féminin est-il formé ?","o":["Au 1er mois","Au 3e mois de gestation","Au 6e mois","Après la naissance"],"r":1,"e":"Le cours précise que l'utérus est formé au 3e mois de gestation.","s":13},{"q":"Quelle est la fonction des lèvres de la vulve ?","o":["Produire les hormones sexuelles","Protéger le vagin et aider à la lubrification","Permettre le passage des ovules vers l'utérus","Sécréter le liquide séminal, au moment du rapport"],"r":1,"e":"Les lèvres supérieures et inférieures protègent le vagin des infections bactériennes et aident à la lubrification. Elles le protègent des infections bactériennes.","s":13},{"q":"Que se passe-t-il en l'absence de grossesse à la fin du cycle menstruel ?","o":["L'endomètre s'épaissit encore davantage","L'endomètre desquame, ce qui donne les règles","L'ovulation se répète immédiatement","Le cycle s'arrête définitivement, jusqu'à la ménopause"],"r":1,"e":"Lorsque la grossesse ne survient pas, il y a desquamation de l'endomètre et, par conséquent, les règles.","s":13},{"q":"Quelles hormones du cycle menstruel sont produites par l'hypophyse ?","o":["L'œstrogène et la progestérone","La FSH et la LH","L'ocytocine et la prolactine","La GnRH et le cortisol"],"r":1,"e":"La FSH (folliculo-stimulante) et la LH (lutéinisante) viennent de l'hypophyse ; l'œstrogène et la progestérone sont produits par les ovaires.","s":13},{"q":"Quels sont les deux agents de l'accouchement selon le cours ?","o":["L'ocytocine et les prostaglandines","L'œstrogène et la progestérone","La FSH et la LH","L'adrénaline et le cortisol"],"r":0,"e":"L'ocytocine renforce et maximise les contractions ; les prostaglandines provoquent un influx de Ca²⁺ conduisant également à davantage de contraction.","s":13},{"q":"Par quel mécanisme les prostaglandines augmentent-elles les contractions ?","o":["Par un influx d'ions calcium","Par une sortie de potassium","Par une baisse du pH utérin","Par une vasoconstriction locale"],"r":0,"e":"Les prostaglandines entraînent un influx de Ca²⁺ conduisant à davantage de contraction.","s":13},{"q":"Que dit le cours de la substitution hormonale à la ménopause ?","o":["Elle est systématiquement recommandée","Elle est encore controversée","Elle est formellement interdite","Elle remplace totalement l'activité ovarienne"],"r":1,"e":"Le cours indique que la substitution hormonale est encore controversée.","s":13},{"q":"Quelles formes de vulvodynie le cours distingue-t-il ?","o":["Aiguë et chronique","Généralisée et localisée","Primaire et secondaire","Superficielle et profonde"],"r":1,"e":"La vulvodynie est distinguée en forme généralisée et forme localisée ; le cancer de la vulve représente 5 %.","s":13},{"q":"Quel pourcentage représente le cancer vaginal selon le cours ?","o":["1 %","5 %","10 %","25 %"],"r":0,"e":"Le cancer vaginal représente 1 % ; le cancer de la vulve représente 5 %.","s":13},{"q":"Lequel de ces termes désigne des saignements en dehors des règles ?","o":["L'aménorrhée","L'oligoménorrhée","La métrorragie","La dysménorrhée"],"r":2,"e":"Parmi les troubles menstruels cités figurent aménorrhée primaire et secondaire, oligoménorrhée, ménorragie, métrorragie et dysménorrhée.","s":13},{"q":"Quelle hormone est augmentée dans l'ovaire polykystique et favorise la sécrétion de LH ?","o":["La gonadolibérine","La progestérone","L'ocytocine","La prolactine"],"r":0,"e":"L'ovaire polykystique est associé à l'augmentation de la GnRH, qui favorise la sécrétion de LH. La gonadolibérine est la GnRH.","s":13},{"q":"Quelles sont les conséquences de l'ovaire polykystique ?","o":["Une puberté précoce, avant l'âge de 8 ans","Une aménorrhée et une infertilité","Une hypertension gravidique","Une ostéoporose précoce isolée"],"r":1,"e":"L'ovaire polykystique, avec ses kystes folliculaires habituellement bilatéraux, est une cause d'aménorrhée et d'infertilité.","s":13},{"q":"Comment définit-on l'endométriose ?","o":["Une infection de l'endomètre","Du tissu endométrial hors de l'utérus","Une hypertrophie du muscle utérin","Une absence congénitale d'endomètre"],"r":1,"e":"L'endométriose est le développement et la croissance de stroma et de glandes endométriales hors de la cavité utérine, entraînant une réaction inflammatoire chronique. Stroma et glandes endométriales se développent hors de la cavité utérine, avec une réaction inflammatoire chronique.","s":13},{"q":"Pourquoi l'endométriose entraîne-t-elle des complications variées ?","o":["Elle touche les structures voisines","Elle provoque toujours un cancer","Elle détruit les deux ovaires","Elle bloque l'urètre, toujours"],"r":0,"e":"Le cours précise que la proximité anatomique d'autres structures entraîne des complications. C'est la proximité anatomique de ces structures qui les implique.","s":13},{"q":"Qu'est-ce qu'un myome utérin ?","o":["Une masse musculaire de grand volume","Une tumeur épithéliale du col","Un kyste ovarien","Une inflammation chronique de l'endomètre"],"r":0,"e":"Le myome est décrit comme une masse musculaire de grand volume.","s":13},{"q":"Lesquelles de ces entités sont des dysfonctions de soutien ?","o":["Galactorrhée, mastite et fibroadénome","Cystocèle, rectocèle et prolapsus utérin","Antéflexion, rétroversion et rétroflexion","Vaginite, candidose et vulvodynie"],"r":1,"e":"Les dysfonctions de soutien sont la cystocèle, la rectocèle et le prolapsus utérin ; l'antéflexion et la rétroversion sont des variations utérines de position.","s":13},{"q":"Que souligne le cours à propos du cancer du sein ?","o":["Qu'il est toujours de mauvais pronostic","Qu'un diagnostic précoce améliore le pronostic","Qu'il ne touche que les femmes ménopausées","Qu'il ne nécessite aucun suivi, après la chirurgie"],"r":1,"e":"Le cours souligne que le diagnostic précoce est associé à un meilleur pronostic.","s":13},{"q":"Les canaux déférents conduisent les spermatozoïdes :","o":["Des épididymes aux testicules","Des testicules aux vésicules séminales","De la prostate jusqu'à l'urètre","Du scrotum jusqu'à l'extrémité du pénis"],"r":1,"e":"Les épididymes assurent le stockage et la maturation, et l'urètre conduit vers l'extérieur urine et sperme.","s":13},{"q":"La fonction du scrotum est :","o":["De produire les spermatozoïdes","De protéger les testicules","De sécréter le liquide prostatique","De conduire le sperme"],"r":1,"e":"Ce sont les testicules, logés dans le scrotum, qui produisent les spermatozoïdes.","s":13},{"q":"La malformation urétrale dorsale correspond à :","o":["Une ouverture de l'urètre sur le dessus du pénis","Une ouverture de l'urètre sur la face ventrale","Un excès de peau qui recouvre entièrement le gland","Une absence complète d'urètre, congénitale"],"r":0,"e":"La malformation ventrale donne une ouverture anormale en un ou plusieurs endroits le long de la face ventrale, avec sortie anormale de l'urine. L'ouverture peut aussi être latérale.","s":13},{"q":"La prostatite non bactérienne chronique se définit comme :","o":["Une infection persistante, récidivante","Une inflammation chronique, sans germe","Une infection d'installation brutale","Une hyperplasie glandulaire, avec des nodules"],"r":1,"e":"Les deux autres formes citées sont la prostatite bactérienne aiguë et la prostatite bactérienne chronique. Aucun germe n'est identifié.","s":13},{"q":"Dans l'hypertrophie bénigne de la prostate, l'épithélium glandulaire hyperplasique peut :","o":["Former des papilles irrégulières","Se nécroser, par ischémie","Se calcifier, en amas de calcium dense","Disparaître, par atrophie"],"r":0,"e":"Les nodules sont composés de glandes en prolifération et de stroma fibromusculaire, dans la portion interne péri-urétrale.","s":13},{"q":"La prévalence de l'hypertrophie bénigne de la prostate à 40 ans est de :","o":["20 %","70 %","90 %","5 %"],"r":0,"e":"Elle atteint 70 % à 60 ans et 90 % à 70 ans.","s":13},{"q":"Le système génito-urinaire féminin se distingue de celui de l'homme par :","o":["Des fonctions sexuelles et urinaires séparées","Un urètre commun à l'urine et aux règles","L'absence de gonades, internes","Une seule voie génitale, externe"],"r":0,"e":"Chez l'homme, l'urètre conduit à la fois l'urine et le sperme.","s":13},{"q":"L'utérus est décrit comme :","o":["De la taille d'une amande, plein","De la taille d'une poire, creux et musculaire","Un organe plein, sans cavité, de la taille d'une prune","Un conduit fin, de quelques millimètres"],"r":1,"e":"Ce sont les ovaires qui sont de la taille d'une amande ; l'utérus est formé au 3ᵉ mois de gestation. Ses parois sont très musculaires et élastiques.","s":13},{"q":"Le clitoris a pour fonction :","o":["Le passage du flux menstruel","Le plaisir sexuel","L'expulsion de l'urine","La lubrification"],"r":1,"e":"Les lèvres protègent le vagin des infections bactériennes et aident à la lubrification ; l'orifice urinaire assure l'expulsion de l'urine.","s":13},{"q":"Le cycle menstruel a pour but :","o":["D'éliminer les toxines","De préparer le système à une grossesse","De réguler la température","De produire des hormones hypophysaires"],"r":1,"e":"En l'absence de grossesse survient la desquamation de l'endomètre, c'est-à-dire les règles.","s":13},{"q":"L'œstrogène et la progestérone sont produits par :","o":["L'hypophyse","Les ovaires","L'utérus","L'hypothalamus"],"r":1,"e":"La FSH et la LH sont, elles, produites par l'hypophyse.","s":13},{"q":"L'ocytocine agit lors de l'accouchement en :","o":["Renforçant et maximisant les contractions","Provoquant un influx de calcium seul","Dilatant le col, sans contraction","Relâchant le myomètre, au repos"],"r":0,"e":"Les prostaglandines agissent par un influx de Ca²⁺ conduisant également à davantage de contraction.","s":13},{"q":"La ménopause correspond :","o":["À l'arrêt de l'activité ovarienne","À l'arrêt de l'activité hypophysaire","À une aménorrhée primaire","À une insuffisance utérine"],"r":0,"e":"La substitution hormonale y reste controversée selon le cours.","s":13},{"q":"Le cancer de la vulve représente, selon le cours :","o":["1 %","5 %","10 %","20 %"],"r":1,"e":"Le cancer vaginal représente, lui, 1 % ; la vulvodynie peut être généralisée ou localisée.","s":13},{"q":"La métrorragie désigne :","o":["Une absence totale des règles, prolongée","Des saignements en dehors des règles","Des règles très abondantes, longues","Des règles très douloureuses, avec crampes"],"r":1,"e":"La ménorragie désigne des règles abondantes, la dysménorrhée des règles douloureuses et l'aménorrhée leur absence.","s":13},{"q":"L'ovaire polykystique est associé à :","o":["Une hausse de la GnRH, qui favorise la LH","Une chute isolée de la FSH, hypophysaire","Un excès de progestérone, ovarienne","Un déficit isolé en œstrogènes"],"r":0,"e":"Habituellement bilatéral, il constitue une cause d'aménorrhée et d'infertilité.","s":13},{"q":"La réaction inflammatoire chronique de l'endométriose est due :","o":["À une infection, bactérienne","À du tissu endométrial hors de l'utérus","À une tumeur, bénigne ou maligne","À une malformation de l'utérus, congénitale"],"r":1,"e":"La proximité anatomique d'autres structures explique les douleurs pelviennes, digestives et urinaires associées.","s":13},{"q":"Le myome utérin correspond à :","o":["Une masse développée aux dépens du muscle utérin","Un kyste de l'ovaire, liquidien ou mixte","Une néoplasie du col de l'utérus, d'origine virale","Un polype de l'endomètre, pédiculé"],"r":0,"e":"La grossesse extra-utérine et le cancer du col constituent les autres entités utérines citées. La masse musculaire est de grand volume.","s":13},{"q":"La cystocèle correspond à :","o":["Une descente du rectum","Une descente de la vessie","Une descente de l'utérus","Une rétroversion utérine"],"r":1,"e":"La rectocèle est la descente du rectum et le prolapsus utérin celle de l'utérus ; ces trois dysfonctions de soutien sont le terrain de la rééducation périnéale.","s":13},{"q":"La galactorrhée se définit comme :","o":["Une inflammation du sein, aiguë","Un écoulement de lait hors allaitement","Une tumeur bénigne du sein, mobile","Une lactation absente"],"r":1,"e":"La mastite est l'inflammation du sein, classiquement du post-partum, et le fibroadénome une tumeur bénigne.","s":13},{"q":"Quelle est l'origine embryologique de l'épiderme ?","o":["Mésodermique","Ectodermique","Endodermique","Neurectodermique exclusivement"],"r":1,"e":"L'épiderme est d'origine ectodermique ; le derme est d'origine mésodermique.","s":14},{"q":"Que dit le cours de l'hypoderme ?","o":["C'est la couche la plus superficielle de la peau","Il ne fait pas partie de la peau","Il est d'origine ectodermique","Il ne contient aucune cellule adipeuse"],"r":1,"e":"L'hypoderme, ou tissu cellulaire sous-cutané, ne fait pas partie de la peau ; il contient des cellules adipeuses et du tissu conjonctif.","s":14},{"q":"Quel pourcentage du poids corporel la peau représente-t-elle ?","o":["5 %","10 %","16 %","25 %"],"r":2,"e":"La peau est le plus grand organe du corps humain et représente 16 % du poids corporel.","s":14},{"q":"Quelle structure assure le filtre face aux radiations ultraviolettes ?","o":["La kératine","La mélanine","Le collagène","Le tissu adipeux"],"r":1,"e":"La fonction protectrice comprend un filtre face aux radiations ultraviolettes assuré par la mélanine.","s":14},{"q":"Quelle couche assure la balance hydro-électrolytique ?","o":["La couche kératinisée","La couche papillaire du derme","L'hypoderme","La couche réticulaire"],"r":0,"e":"La couche kératinisée agit comme barrière face à la perte d'eau, maintenant l'équilibre des fluides corporels.","s":14},{"q":"Quelle fonction métabolique la peau assure-t-elle ?","o":["La formation de vitamine D","La production d'insuline","La synthèse d'hémoglobine","La production d'érythropoïétine"],"r":0,"e":"La fonction métabolique de la peau correspond à la formation de vitamine D.","s":14},{"q":"Quelle manifestation relève de la fonction émotionnelle de la peau ?","o":["La transpiration, qui régule la chaleur","Rougir, pâlir, avoir la chair de poule","La synthèse de vitamine D, sous l'effet du soleil","La barrière contre les micro-organismes"],"r":1,"e":"Nous extériorisons notre état émotionnel à travers la peau : nous rougissons, pâlissons, avons la chair de poule et émettons des odeurs (phéromones). L'émission de phéromones en fait aussi partie.","s":14},{"q":"Quel type d'épithélium constitue l'épiderme ?","o":["Un épithélium cubique simple, de type glandulaire","Un épithélium pavimenteux stratifié kératinisé","Un épithélium cylindrique cilié","Un épithélium de transition, urinaire"],"r":1,"e":"L'épiderme est un épithélium pavimenteux stratifié kératinisé constitué de kératinocytes.","s":14},{"q":"En combien de temps l'épiderme se renouvelle-t-il ?","o":["Entre 2 et 5 jours","Entre 15 et 30 jours","Entre 2 et 3 mois","Entre 6 mois et un an"],"r":1,"e":"L'épiderme se renouvelle entre 15 et 30 jours.","s":14},{"q":"Quelles cellules, en plus des kératinocytes, composent l'épiderme ?","o":["Mélanocytes, cellules de Langerhans, de Merkel","Fibroblastes, adipocytes, mastocytes","Ostéoblastes, chondrocytes, ostéoclastes du derme","Hépatocytes, myocytes, neurones"],"r":0,"e":"Outre les kératinocytes, l'épiderme contient les mélanocytes, les cellules de Langerhans et les cellules de Merkel.","s":14},{"q":"Comment définit-on l'albinisme ?","o":["La disparition des mélanocytes, dans certaines zones","L'incapacité héréditaire à produire de la mélanine","Un excès de production de mélanine, localisé","Une absence de kératinocytes, congénitale"],"r":1,"e":"L'albinisme est l'incapacité héréditaire des mélanocytes à produire de la mélanine ; le vitiligo est la dégénérescence et la disparition des mélanocytes dans certaines zones.","s":14},{"q":"Quel est le mécanisme du psoriasis ?","o":["Une diminution des mitoses épidermiques","Des mitoses accrues avec un cycle raccourci","Une destruction auto-immune des mélanocytes","Une infection bactérienne du derme"],"r":1,"e":"Le psoriasis associe une augmentation marquée du nombre de mitoses dans les couches basale et épineuse et une diminution de la durée du cycle mitotique, rendant l'épiderme plus épais. Les mitoses augmentent dans les couches basale et épineuse.","s":14},{"q":"Quel aspect présentent les zones atteintes de psoriasis ?","o":["Des vésicules, à contenu limpide","Des plaques blanches qui desquament","Des taches dépigmentées, blanches","Des nodules compacts, bien délimités"],"r":1,"e":"Les zones atteintes présentent une accumulation de plaques blanchâtres de kératine desquamée. Ce sont des plaques de kératine desquamée.","s":14},{"q":"Quelle couche du derme possède les papilles dermiques ?","o":["La couche réticulaire","La couche papillaire","La couche cornée","La couche basale"],"r":1,"e":"La couche papillaire, la plus fine, possède des papilles dermiques qui augmentent la surface de contact du derme avec l'épiderme.","s":14},{"q":"Quelle manœuvre est utile au diagnostic du psoriasis ?","o":["La vitropression","Le grattage méthodique de Brocq","Le test épicutané de contact","La biopsie exclusivement"],"r":1,"e":"Le grattage méthodique de Brocq, réalisé en raclant avec une curette tranchante, observe l'épaisseur de chaque couche épidermique et est utile au diagnostic du psoriasis.","s":14},{"q":"Que permet de distinguer la vitropression ?","o":["L'érythème qui s'efface du purpura qui reste","Le psoriasis de l'eczéma, par la couleur","Le vitiligo de l'albinisme, par l'étendue","La papule du nodule, par la profondeur"],"r":0,"e":"La vitropression élimine la congestion vasculaire : dans l'érythème les lésions disparaissent, tandis que dans le purpura elles persistent.","s":14},{"q":"Comment définit-on une macule ?","o":["Une lésion surélevée, de moins d'un centimètre","Une lésion plane, définie par sa seule couleur","Une cavité, à paroi conjonctive et épithéliale","Une perte de l'épiderme et du derme"],"r":1,"e":"La macule ou tache est une lésion plane circonscrite qui se caractérise exclusivement par une altération de la couleur de la peau.","s":14},{"q":"Qu'est-ce qui distingue une papule d'une plaque ?","o":["La papule fait moins d'un centimètre, la plaque plus","La papule est liquide, la plaque est solide et bien ferme","La papule laisse une cicatrice, pas la plaque","La papule est toujours purulente, la plaque jamais"],"r":0,"e":"La papule est une lésion surélevée de moins de 1 cm évoluant sans cicatrice ; la plaque est surélevée et fait plus de 1 cm, généralement à surface plane.","s":14},{"q":"Quelle est l'évolution périodique caractéristique de la gomme ?","o":["Induration, ramollissement, puis ulcération","Vésicule, pustule, puis croûte et cicatrice blanche","Érythème, œdème, puis desquamation","Sclérose, épaississement, puis lichénification"],"r":0,"e":"La gomme évolue en trois temps : période d'induration, ramollissement, puis période d'ulcération où la peau s'ouvre en éliminant un liquide graisseux. L'ulcération élimine un liquide graisseux.","s":14},{"q":"Quelle est la taille limite distinguant une vésicule d'une bulle ?","o":["0,5 cm","1 cm","2 cm","5 mm de profondeur"],"r":0,"e":"La vésicule fait moins de 0,5 cm ; la bulle ou phlyctène fait plus de 0,5 cm, comme dans la brûlure ou le pemphigus.","s":14},{"q":"Quelle lésion est définie par un contenu purulent ?","o":["La vésicule","La pustule","Le kyste","Le nodule"],"r":1,"e":"La pustule est une lésion à contenu purulent, surélevée, pouvant reposer sur une peau normale ou sur une base infiltrée ; exemple : l'acné.","s":14},{"q":"Comment définit-on une fissure ?","o":["Une perte superficielle, qui guérit sans cicatrice","Une rupture linéaire du derme, dans les plis","Une cavité à contenu pâteux, entourée d'une paroi fine","Un dépôt d'exsudat et de débris, en surface"],"r":1,"e":"La fissure est une rupture de la peau avec solution de continuité linéaire affectant le derme, localisée dans les plis naturels, habituellement infectée par des champignons et douloureuse. C'est une solution de continuité de la peau, localisée dans les plis naturels.","s":14},{"q":"Qu'est-ce que la lichénification ?","o":["Une peau épaissie aux sillons marqués, par grattage","Une perte de pigmentation, localisée et nette","Une réparation par un tissu conjonctif fibreux","Une accumulation de pus, sous l'épiderme décollé en bulle"],"r":0,"e":"La lichénification correspond à une peau d'aspect épaissi avec visibilité accrue des sillons, généralement produite par un grattage intense. Le grattage est intense.","s":14},{"q":"Qu'est-ce qui caractérise la sclérose cutanée ?","o":["Une peau rigide, sans plis, qui résiste à la pression","Une peau qui se détache en squames fines","Une peau qui se creuse en ulcération profonde","Une peau couverte de vésicules, à contenu clair et limpide"],"r":0,"e":"La sclérose est une altération de l'épaisseur et de la consistance : la peau devient rigide, perd son plissement naturel et résiste à la distension, par augmentation du tissu conjonctif du derme.","s":14},{"q":"Quels sont les trois critères de gravité d'une brûlure ?","o":["Profondeur, étendue et localisation","Âge, sexe et poids du patient","Douleur, fièvre et prurit associé","Couleur, odeur et exsudat local"],"r":0,"e":"La gravité d'une brûlure dépend de sa profondeur, de son étendue et de sa localisation.","s":14},{"q":"Quelle est la caractéristique d'une brûlure du 1er degré ?","o":["Des vésicules, avec une douleur prolongée","Un érythème et un œdème, sans cicatrice","Une anesthésie totale, avec un aspect de cuir","Une destruction totale de la peau"],"r":1,"e":"La brûlure du 1er degré donne un érythème et un œdème de l'épiderme, dure 3 à 4 jours et ne laisse pas de cicatrice. L'atteinte se limite à l'épiderme et dure 3 à 4 jours.","s":14},{"q":"Quel élément caractérise la brûlure du 2e degré ?","o":["Une anesthésie complète, au toucher","Des vésicules, avec une douleur prolongée","Une atteinte limitée à l'épiderme seul","Aucune cicatrice, dans tous les cas"],"r":1,"e":"Le 2e degré implique épiderme et derme, avec érythème, œdème et vésicules, une douleur prolongée et 3 à 5 semaines pour guérir ; la perte de follicules et de glandes sébacées peut être permanente. La guérison prend 3 à 5 semaines.","s":14},{"q":"Quel aspect présente une brûlure du 3e degré ?","o":["Une peau rouge, chaude et douloureuse","Une surface blanche ou brune, cartonnée, insensible","Des vésicules claires, étendues sur une large surface","Une simple desquamation, sans douleur"],"r":1,"e":"Le 3e degré détruit toute l'épaisseur de la peau : surface blanche ou brune, consistance semblable au cuir et anesthésie totale. La consistance est semblable au cuir, avec une anesthésie totale.","s":14},{"q":"À partir de quel seuil une brûlure du 3e degré expose-t-elle au choc par perte de protéines ?","o":["Plus de 2 % de la surface corporelle","Plus de 10 % de la surface corporelle","Plus de 40 % de la surface corporelle","Il n'existe pas de seuil"],"r":1,"e":"Au-delà de 10 % de la surface corporelle avec brûlure du 3e degré, la perte de protéines peut entraîner hypoprotéinémie et hypovolémie, conduisant éventuellement au choc.","s":14},{"q":"Quel mécanisme explique l'insuffisance rénale aiguë du grand brûlé ?","o":["Une hémolyse, avec de l'hémoglobine libre dans le plasma","Une obstruction urétérale par des calculs, des deux côtés","Une infection urinaire ascendante, à colibacille","Un excès d'apport hydrique, par les perfusions"],"r":0,"e":"Les altérations sanguines associent nécrose des érythrocytes, hémolyse et libération d'hémoglobine libre dans le plasma, pouvant conduire à une insuffisance rénale aiguë. Les érythrocytes se nécrosent.","s":14},{"q":"L'origine embryologique du derme est :","o":["Ectodermique","Mésodermique","Endodermique","Neuroectodermique"],"r":1,"e":"L'épiderme est d'origine ectodermique ; l'hypoderme, lui, ne fait pas partie de la peau.","s":14},{"q":"La fonction thermorégulatrice de la peau est assurée par :","o":["Les vaisseaux, les glandes et le tissu adipeux","La mélanine, qui absorbe la chaleur des rayons solaires","La couche kératinisée, imperméable à l'eau","Les cellules de Merkel, sensorielles"],"r":0,"e":"La mélanine assure le filtre face aux UV, et la couche kératinisée la balance hydro-électrolytique.","s":14},{"q":"La fonction sensorielle de la peau transmet :","o":["La pression, la température et la douleur","Le toucher fin seulement, au bout des doigts","La douleur seulement, par les terminaisons libres","La vibration seule, par les corpuscules"],"r":0,"e":"Elle passe par des récepteurs et des terminaisons nerveuses réparties dans la peau.","s":14},{"q":"L'émission de phéromones relève de la fonction :","o":["Métabolique","Émotionnelle","Protectrice","Sensorielle"],"r":1,"e":"Cette fonction comprend aussi le fait de rougir, de pâlir et d'avoir la chair de poule.","s":14},{"q":"Le bronzage par exposition solaire résulte :","o":["D'une multiplication des mélanocytes","De l'assombrissement de la mélanine","D'un épaississement de la couche cornée","D'une vasodilatation"],"r":1,"e":"L'albinisme correspond à l'incapacité héréditaire des mélanocytes à produire de la mélanine, le vitiligo à leur disparition dans certaines zones.","s":14},{"q":"Le vitiligo correspond à :","o":["Une incapacité héréditaire à produire de la mélanine","La disparition des mélanocytes par zones","Un excès localisé de mélanine","Une prolifération des kératinocytes"],"r":1,"e":"L'albinisme est, lui, une incapacité héréditaire des mélanocytes à produire la mélanine. Les mélanocytes dégénèrent puis disparaissent.","s":14},{"q":"Dans le psoriasis, la durée du cycle mitotique des cellules basales et épineuses est :","o":["Allongée","Diminuée","Inchangée","Nulle"],"r":1,"e":"Le nombre de mitoses augmente et le cycle raccourcit : l'épiderme devient plus épais et se renouvelle plus rapidement.","s":14},{"q":"La couche réticulaire du derme est :","o":["La plus fine","La plus épaisse","Porteuse des papilles dermiques","Absente chez l'adulte"],"r":1,"e":"La couche papillaire est la plus fine et possède les papilles dermiques, qui augmentent la surface de contact avec l'épiderme.","s":14},{"q":"L'hypoderme contient :","o":["Un tissu conjonctif lâche et une couche de graisse","Uniquement des fibres élastiques, très denses et serrées","Des mélanocytes, en très grand nombre","Des kératinocytes, en couches superposées"],"r":0,"e":"Il relie de façon peu ferme le derme aux organes sous-jacents, sans faire partie de la peau à proprement parler. Le tissu adipeux sert de réserve d'énergie et protège du froid.","s":14},{"q":"Dans l'histoire clinique dermatologique, la question « Quoi » porte sur :","o":["Les données personnelles et le travail","La description du processus, surtout le prurit","Le début et la progression, aigus ou chroniques","Les facteurs déterminants, déclenchants"],"r":1,"e":"La question « Comment » porte sur le début et la progression, aigu ou chronique, et « Pourquoi » sur les facteurs déterminants. On décrit douleur, chaleur, fièvre et surtout prurit.","s":14},{"q":"Les tests épicutanés de contact servent à :","o":["Identifier l'allergène d'un eczéma de contact","Diagnostiquer le psoriasis, par le grattage","Différencier un érythème d'un purpura, par pression","Explorer la sensibilité thermique de la peau"],"r":0,"e":"Le grattage de Brocq sert au psoriasis et la vitropression à distinguer érythème et purpura. Ils servent aussi devant une urticaire.","s":14},{"q":"Le vitiligo et le pityriasis alba sont des exemples de macule :","o":["Vasculaire","Pigmentaire par défaut","Pigmentaire par excès","À pigments étrangers"],"r":1,"e":"Les éphélides et le chloasma relèvent de l'excès pigmentaire, les xanthélasmas et tatouages des pigments étrangers, et l'érythème de la macule vasculaire.","s":14},{"q":"Le nodule se distingue de la papule par :","o":["Sa taille plus grande, sa consistance compacte","Son contenu liquide, clair et limpide","Son absence de relief, totalement plane","Sa disparition complète à la vitropression"],"r":0,"e":"La papule mesure moins de 1 cm et évolue sans laisser de cicatrice ; la plaque dépasse 1 cm mais reste à surface généralement plane. Il dépasse 1 cm et évolue de façon chronique.","s":14},{"q":"La tumeur cutanée se caractérise par :","o":["Une régression spontanée, constante","Une croissance indéfinie, sauf exception","Un contenu purulent, sous tension","Une évolution en trois temps, jusqu'à l'ulcération"],"r":1,"e":"Le carcinome épidermoïde en est l'exemple cité ; la gomme est, elle, définie par son évolution périodique. Elle ne régresse spontanément qu'exceptionnellement.","s":14},{"q":"Le kyste se définit comme :","o":["Une cavité à paroi conjonctive et épithéliale","Une élévation de moins de 0,5 cm, à contenu limpide","Une lésion purulente, surélevée et chaude","Une lésion plane, définie par sa couleur"],"r":0,"e":"Le kyste sébacé et le kyste épidermique en sont les exemples cités. Son contenu est liquide, pâteux ou solide.","s":14},{"q":"La squame se définit comme :","o":["Un dépôt d'exsudat et de débris, en surface","Une lamelle d'épiderme, qui peut se détacher","Une plaque fixée, éliminée ensuite","Une lésion suppurative, fermée"],"r":1,"e":"La croûte est le dépôt d'exsudat et de débris, l'escarre une plaque fixée, et l'abcès une lésion fermée suppurative. Elle se détache spontanément ou au grattage.","s":14},{"q":"L'érosion ou excoriation se caractérise par :","o":["Une guérison sans cicatrice","Une cicatrice constante","Une atteinte de l'hypoderme","Une localisation dans les plis"],"r":0,"e":"Elle est presque toujours d'origine traumatique, avec perte de tissu épidermique et occasionnellement du derme supérieur.","s":14},{"q":"L'ulcération se définit par :","o":["Une perte de l'épiderme, superficielle seulement","Une perte de l'épiderme et du derme, parfois plus","Une rupture linéaire, dans un pli de la peau","Un épaississement de la peau, avec des sillons très marqués"],"r":1,"e":"L'ulcère variqueux en est l'exemple cité ; la fissure est, elle, une solution de continuité linéaire des plis naturels. Elle peut atteindre l'hypoderme et les tissus sous-jacents.","s":14},{"q":"La formule de surface corporelle citée dans le cours fait intervenir :","o":["La taille et le poids du patient","L'âge et le sexe du patient","Le poids seul, en kilogrammes","L'indice de masse corporelle seul, calculé"],"r":0,"e":"L'aire de surface corporelle s'estime plus simplement, en pratique d'urgence, par la règle des 9. La taille s'exprime en centimètres et le poids en kilogrammes.","s":14},{"q":"La localisation d'une brûlure aggrave le pronostic lorsqu'elle est :","o":["Facile à contaminer et difficile à mobiliser","Située sur le tronc, en avant ou en arrière","Située sur un membre supérieur, en distal","Symétrique, sur les deux côtés du corps à la fois"],"r":0,"e":"La gravité d'une brûlure combine profondeur, étendue et localisation. Le périnée en est l'exemple.","s":14}]};
